INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'No princípio criou Deus o céu e a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'A terra, porém, estava informe e vazia, e as trevas cobriam a face do abismo, e o Espírito de Deus movia-Se sobre as águas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'E Deus disse: Exista a luz. E a luz existiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'E Deus viu que a luz era boa, e separou a luz das trevas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'Chamou à luz dia, e às trevas noite. E fez-se tarde e manhã, (e foi) o primeiro dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'Disse também Deus: Faça-se o firmamento no meio das águas, e separe umas águas das outras águas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 7, 'E fez Deus o firmamento, e separou as águas que estavam por baixo, das águas que estavam por cima do firmamento. E assim se fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'E Deus chamou ao firmamento céu. E fez-se tarde e manhã, (e foi) o segundo dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'Disse também Deus: As águas, que estão debaixo do céu, juntem-se num só lugar, e apareça o (elemento) árido. E assim se fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'E Deus chamou ao (elemento) árido terra, e ao conjunto das águas chamou mares. E Deus viu que isto era bom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 11, 'Deus disse: produza a terra verdura, plantas germinadoras de semente e árvores frutíferas, que dêem fruto segundo a sua espécie, cuja semente esteja nelas mesmas (para se reproduzirem) sobre a terra. E assim se fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'E a terra produziu verdura, plantas germinadoras de semente e árvores que dão fruto, e cada uma das quais tem semente segundo a sua espécie. E viu Deus que isto era bom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'E fez-se tarde e manhã, (e foi) o terceiro dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'Disse também Deus: Sejam feitos luzeiros no firmamento do céu, que separem o dia da noite e sirvam para sinais, e que distingam as estações, os dias e os anos, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'e que resplandeçam no firmamento do céu, para alumiar a terra. E assim se fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'Deus fez os dois grandes luzeiros: o luzeiro maior para presidir ao dia, e o luzeiro menor para presidir à noite, e (fez também) as estrelas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'E colocou-as no firmamento do céu, para luzirem sobre a terra, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'e presidirem ao dia e à noite, e separarem a luz das trevas. E Deus viu que isto era bom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 19, 'E fez-se tarde e manhã, (e foi) o quarto dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 20, 'Disse também Deus: encham-se as águas de seres vivos, e voem aves sobre a terra, debaixo do firmamento do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 21, 'Deus criou os grandes animais aquáticos, e todos os animais que têm vida e movimento e que abundam nas águas, segundo a sua espécie, e todas as aves seguindo a sua espécie. E Deus viu que isto era bom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 22, 'E os abençoou, dizendo: Crescei e multiplicai-vos, e enchei as águas do mar: e as aves se multipliquem sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 23, 'E fez-se tarde e manhã (e foi) o quinto dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 24, 'Disse também Deus: Produza a terra animais viventes segundo a sua espécie, animais domésticos, e répteis, e animais selváticos segundo a sua espécie. E assim se fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 25, 'E fez Deus os animais selváticos, segundo a sua espécie, e os animais domésticos, e todos os répteis da terra (cada um) segundo a sua espécie. E viu Deus que isto era bom,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 26, 'e (por fim) disse: Façamos o homem à nossa imagem e semelhança, e presida aos peixes do mar, e as aves do Céu, e aos animais selváticos, e a toda a terra, e a todos os répteis, que se movem sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 27, 'E criou Deus o homem à sua imagem; criou-o à imagem de Deus, varão e fêmea os criou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 28, 'E Deus os abençoou, e disse: Crescei e multiplicai-vos, e enchei a terra, e sujeitai-a, e dominai sobre os peixes do mar e sobre as aves do céu, e sobre todos os animais que se movem sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 29, 'E Deus disse: Eis que vos dei todas as ervas, que dão semente sobre a terra, e todas as árvores, que encerram em si mesmas a semente do seu gênero, para que vos sirvam de alimento, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 30, 'e a todos os animais da terra, e a todas as aves do céu, e a tudo o que se move, sobre a terra, e em que há alma vivente, para que tenham que comer. E assim se fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 31, 'E Deus viu todas as coisas que tinha feito, e eram muito boas. E fez-se tarde e manhã, (e foi) o sexto dia. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Assim foram acabados o céu e a terra, e todos os seus ornatos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'E Deus acabou no sétimo dia a obra que tinha feito: e descansou no sétimo dia de toda a obra que tinha feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'E abençoou o dia sétimo, e o santificou, porque nele tinha cessado de toda a sua obra, que, ao operar, tinha criado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 4, 'Tal é a história da criação do céu e da terra. No dia em que o Senhor Deus fez a terra e o céu, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'nenhum arbusto campestre existia sobre a terra, e nenhuma erva do campo havia ainda brotado, porque o Senhor Deus não tinha (ainda) feito chover sobre a terra, nem havia homem que a cultivasse,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'embora da terra subisse um vapor que regava toda a sua superfície.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, 'O Senhor Deus formou, pois, o homem do barro da terra, e inspirou no seu rosto um sopro de vida, e o homem tornou-se alma (pessoa) vivente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Depois o Senhor Deus plantou um jardim no Eden, a Oriente, no qual pôs o homem que tinha formado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'E o Senhor Deus tinha produzido da terra toda a casta de árvores formosas à vista, e de frutos doces para comer; e a árvore da vida no meio do paraíso, e a árvore da ciência do bem e do mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 10, 'Do Eden saía um rio para regar o jardim, o qual dali se dividiu em quatro braços.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 11, 'O nome do primeiro é Fison, e é aquele que torneia todo o pais de Evilath, onde se encontra o ouro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 12, 'E o ouro deste país é ótimo; ali (também) se acha o bdélio e a pedra ónix.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 13, 'O nome do segundo rio é Geon, este é aquele que torneia toda a terra da Etiópia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 14, 'O nome, porém, do terceiro rio é Tigre, que corre para a banda dos Assírios. E o quatro rio é o Eufrates.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 15, 'Tomou, pois, o Senhor Deus o homem, e colocou-o no jardim do Eden, para que o cultivasse e guardasse, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 16, 'E deu-lhe este preceito, dizendo: Come de todas as árvores do paraíso, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 17, 'mas não comas do fruto da árvore da ciência do bem e do mal, porque, em qualquer dia que comeres dele, morrerás indubitàvelmente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 18, 'Disse mais o Senhor Deus: Não é bom que o homem esteja só: façamos-lhe um adjutório semelhante a ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 19, 'Tendo, pois, o Senhor Deus formado da terra todos os animais terrestres, e todas as aves do céu, levou-os diante de Adão, para este ver como os havia de chamar: e todo o nome que Adão pôs aos animais vivos, esse é o seu verdadeiro nome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 20, 'E Adão pôs nomes convenientes a todos os animais (domésticos), a todas as aves do céu, e a todos os animais selváticos: mas não se achava para Adão um adjutório semelhante a ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 21, 'Mandou, pois, o Senhor Deus um profundo sono a Adão, e, enquanto ele estava dormindo, tirou uma das suas costelas, e pôs carne no lugar dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 22, 'E da costela, que tinha tirado de Adão, Formou o Senhor Deus uma mulher, e a levou a Adão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 23, 'E Adão disse: eis aqui agora o osso de meus ossos e a carne da minha carne; ela se chamará Virago, porque do varão foi tomada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 24, 'Por isso deixará o homem seu pai e a sua mãe, e se unirá a sua mulher, e os dois serão uma só carne.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 25, 'Ora um e outro, isto é, Adão e sua mulher, estavam nus, e não se envergonhavam (porque ainda eram inocentes). ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'Mas a serpente era o mais astuto de todos os animais da terra que o Senhor Deus tinha feito. E ela disse à mulher: por que vos mandou Deus que não comêsseis de toda a árvore do paraíso? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'Respondeu-lhe a mulher: nós comemos do fruto das árvores, que estão no paraíso, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'mas do fruto da árvore, que está no meio do paraíso, Deus nos mandou que não comêssemos, e nem a tocássemos, não suceda que morramos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'Porém a serpente disse à mulher: vós de nenhum modo morrereis; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'mas Deus sabe que, em qualquer dia que comerdes dele, se abrirão os vossos olhos, e sereis como deuses, conhecendo o bem e o mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'Viu, pois, a mulher que (o fruto) do árvore era bom para comer, formoso aos olhos e desejável para alcançar a sabedoria, e tirou do fruto dela, e comeu: e deu a seu marido, que também comeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'E os olhos de ambos se abriram: e, tendo conhecido que estavam nus, coseram folhas de figueira, e fizeram para si cinturas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'E, tendo ouvido a voz do Senhor Deus, que passeava pelo paraíso, à hora da brisa, depois do meio-dia, Adão e sua mulher esconderam-se da face do Senhor Deus no meio das árvores do paraíso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'E o Senhor Deus chamou por Adão, e disse-lhe: onde estás? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'E ele respondeu: ouvi a tua voz no paraíso, e tive medo, porque estava nu, e escondi-me.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, 'Disse-lhe Deus: mas quem te fez conhecer que estavas nu? acaso comeste da árvore, de que eu tinha ordenado que não comesses?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, 'Adão disse: a mulher, que me deste por companheira, deu-me (do fruto) da árvore, e comi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'E o Senhor Deus disse para a mulher: por que fizeste isto? Ela respondeu: a serpente enganou-me, e comi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'E o Senhor Deus disse à serpente: pois que fizeste isto, és maldita entre todos os animais e bestas da terra; andarás de rastos sobre o teu peito, e comerás terra todos os dias da tua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'Porei inimizades entre ti e a mulher, e entre a tua posteridade e a posteridade dela. Ela te pisará a cabeça e tu armarás traições ao seu calcanhar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'Disse também à mulher: multiplicarei os teus trabalhos, e (especialmente os de) teus partos. Darás à luz com dor os filhos, e desejarás com ardor a teu marido, que te dominará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'E disse a Adão: porque deste ouvidos à voz de tua mulher, e comeste da árvore, de que eu te tinha ordenado que não comesses, a terra será maldita por tua causa; tirarás dela o sustento com trabalhos penosos todos os dias da tua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 18, 'Ela te produzirá espinhos e abrolhos, e tu comerás a erva da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 19, 'Comerás o pão com o suor do teu rosto, até que voltes à terra, de que foste tomado, porque tu és pó, e em pó te hás-de tornar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 20, 'E Adão pôs a sua mulher o nome de Eva, porque ela era a mãe de todos os viventes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 21, 'Fez também o Senhor Deus a Adão e a sua mulher umas túnicas de peles, e os vestiu '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 22, 'E disse: Eis que Adão se tornou como um de nós, conhecendo o bem e o mal; agora pois (expulsemo-lo do paraíso), para que não suceda que ele estenda a sua mão, tome também da árvore da vida, coma e viva eternamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 23, 'E o Senhor Deus lançou-o fora do jardim do Eden, para que cultivasse a terra, de que tinha sido tomado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 24, 'E expulsou Adão, e pôs diante do jardim do Eden Querubins brandindo uma espada de fogo, para guardar o caminho da árvore da vida. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'E Adão conheceu sua mulher Eva, a qual concebeu e deu à luz Caim, dizendo: alcancei um homem por (auxílio de) Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 2, 'E, depois, deu à luz seu irmão Abel. Abel foi pastor de ovelhas, e Caim lavrador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, 'Passado muito tempo, aconteceu oferecer Caim, em oblação ao Senhor, dos frutos da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Abel também ofereceu dos primogênitos do seu rebanho, e das gorduras deles. O Senhor olhou para Abel, e para os seus dons; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'não olhou, porém, para Caim, nem para os seus dons. Caim irou-se extremamente, e o seu semblante ficou abatido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'E o Senhor disse-lhe: por que estás irado? e por que está abatido o teu semblante?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 7, 'Porventura, Se tu obrares bem, não receberás (por isso galardão)? Se obrares mal, estará logo o pecado à tua porta, Mas sob ti está o teu desejo, e tu o dominarás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Caim disse a seu irmão Abel: saiamos fora. E, quando estavam no campo, investiu Caim contra seu irmão Abel, e matou-o.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'E o Senhor disse a Caim: onde está teu irmão Abel? E ele respondeu: não sei. Porventura sou eu o guarda de meu irmão?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, 'E o Senhor disse-lhe: Que fizeste? A voz do sangue de teu irmão ergue o seu clamor da terra até mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'Agora, pois, serás maldito sobre a terra, que abriu a sua boca, e recebeu da tua mão o sangue de teu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'Quando a cultivares, ela não te dará os seus frutos; serás vagabundo e fugitivo sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 13, 'E Caim disse ao Senhor: Insuportavelmente grande é o meu castigo, grande demais para que eu mereça perdão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 14, 'Eis que tu hoje me expulsas desta terra, e eu me esconderei da tua face, e serei vagabundo e fugitivo na terra; portanto todo o que me achar, me matará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 15, 'E o Senhor disse-lhe: não será assim; mas qualquer que matar Caim, será castigado sete vezes mais. E o Senhor pôs um sinal em Caim, para que o não matasse ninguém que o encontrasse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 16, 'E Caim, tendo-se retirado de diante da face do Senhor, andou errante sobre a terra, e habitou no pais de Nod, que está ao nascente do Eden.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 17, 'E Caim conheceu sua mulher, a qual concebeu e deu à luz Henoch. E edificou uma cidade, que chamou Henoch, do nome de seu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 18, 'Ora Henoch gerou Irad, Irad gerou Maviael, Maviael gerou Matusael, e Matusael gerou Lamech.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 19, 'E este tomou duas mulheres, uma chamada Ada e outra Sela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 20, 'E Ada deu à luz Jabel, que foi pai dos que habitam sob tendas e entre rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 21, 'O nome de seu irmão foi Jubal, que foi o pai (ou mestre) dos que tocam citara e orgão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 22, 'Sela também deu à luz Tubalcain, que foi artifice de todos os instrumentos de bronze e de feno. E a irmã de Tubalcain foi Noema.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 23, 'E Lamech disse a suas mulheres, Ada e Sela: Ouvi a minha voz, mulheres de Lamech, escutai as minhas palavras: eu matei um homem que me feriu, e um adolescente que me contundiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 24, 'Caim será vingando sete vezes, mas Lamech setenta vezes sete.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 25, 'E Adão conheceu outra vez sua mulher, a qual deu à luz um filho, e pôs-lhe o nome de Seth, dizendo: o Senhor deu-me outro filho em lugar de Abel, que Caim matou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 26, 'E nasceu também um filho a Seth, que ele chamou Enós. Este começou a invocar o nome do Senhor. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Este é o livro da posteridade de Adão. No dia em que Deus criou o homem, fê-lo à semelhança de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 2, 'Varão e fêmea os criou, e abençoou-os; e deu-lhes o nome de Homem no dia em que foram criados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'Tinha Adão cento e trinta anos quando gerou um filho à sua imagem e semelhança a que pôs o nome de Seth.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 4, 'E, depois que gerou Seth, viveu Adão oitocentos anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'Todo o tempo que Adão viveu foi de novecentos e trinta anos, e morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'Tinha Seth cento e cinco anos, quando gerou Enós,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'Depois que gerou Enós, viveu Seth oitocentos e sete anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'E toda a vida de Seth foi de novecentos e doze anos, e morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'Era Enós de noventa anos, quando gerou Cainan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'Depois do nascimento de Cainan, viveu oitocentos e quinze anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'Todo o tempo da vida de Enós foi de novecentos e cinco anos, e morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'Tinha Cainan setenta anos quando gerou Malaleel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Depois de ter gerado Malaleel, viveu Cainan oitocentos e quarenta anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Todo o tempo da vida de Cainan foi de novecentos e dez anos, e morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'Era Malaleel de sessenta e cinco anos, quando gerou Jared.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'Depois de ter gerado Jared, viveu Malaleel oitocentos e trinta anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 17, 'Todo o tempo da vida de Malaleel foi de oitocentos e noventa e cinco anos, e morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 18, 'Tinha Jared cento e sessenta e dois anos, quando gerou Henoch.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 19, 'Depois de ter gerado Henoch, viveu Jared oitocentos anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 20, 'E toda a vida de Jared foi novecentos e sessenta e dois anos, e morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 21, 'Era Henoch de sessenta e cinco anos, quando gerou Matusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 22, 'E Henoch andou com Deus; e, depois de ter gerado Matusalém, viveu trezentos anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 23, 'E todo o tempo da vida de Henoch foi de trezentos e sessenta e cinco anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 24, 'Andou constantemente com Deus, e desapareceu, porque Deus o levou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 25, 'Era Matusalém de cento e oitenta e sete anos, quando gerou Lamech.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 26, 'Depois de ter gerado Lamech, viveu Matusalém setecentos e oitenta e dois anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 27, 'E toda a vida de Matusalém foi de novecentos e sessenta e nove anos, e morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 28, 'Tinha Lamech cento e oitenta e dois anos, quando gerou um filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 29, 'ao qual pôs o nome de Noé, dizendo: este nos consolará nos trabalhos e nas fadigas das nossas, mãos, pela terra que o Senhor amaldiçoou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 30, 'Lamech, depois de ter gerado Noé, viveu quinhentos e noventa e cinco anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 31, 'Toda a vida de Lamech foi de setecentos e setenta e sete anos, e morreu. Noé, tendo de idade quinhentos anos, gerou Sem, Cam e Jafeth. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'Ora, tendo os homens começado a multiplicar-se sobre a terra, e tendo gerado filhas, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'vendo os filhos de Deus que as filhas dos homens eram formosas, tomaram por suas mulheres as que, dentre todas, lhes agradaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'E Deus disse: o meu espirito não permanecerá para sempre no homem, porque é carne. Os seus dias serão cento e vinte anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'Ora, naquele tempo, havia gigantes sobre a terra, e também depois, quando depois os filhos de Deus tiveram comércio com as filhas dos homens, e elas geraram filhos, que foram homens possantes e desde há muito afamados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'Deus, vendo que era grande a malicia dos homens sobre a terra, e que todos os pensamentos do seu coração estavam continuamente aplicados ao mal, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'arrependeu-se de ter feito o homem sobre a terra. E, tocado de íntima dor de coração, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'disse: exterminarei da face da terra o homem que criei; desde o homem até aos animais, desde os répteis até às aves do céu, porque me pesa de os ter feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Porém Noé achou graça diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, 'Esta é a posteridade de Noé. Noé foi um homem justo e perfeito entre os homens do seu tempo, e sempre andou com Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'Gerou três filhos: Sem, Cam e Jafeth.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'Ora a terra estava corrompida diante de Deus e cheia de iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, 'Vendo, pois. Deus que a terra estava corrompida (porque toda a carne (todo o homem) tinha corrompido o seu caminho sobre a terra), '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'disse a Noé: o fim de todos chegou diante de mim; a terra, por suas obras, está cheia de iniquidade, e eu os exterminarei com a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'Faze uma arca de madeiras resinosas: farás na arca uns pequenos quartos e calafetá-la-ás com betume por dentro e por fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 15, 'E hás-de fazê-la do seguinte modo: o comprimento da arca será de trezentos côvados, a largura de cincoenta côvados, e a altura de trinta côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 16, 'Farás na arca uma janela, um côvado abaixo do seu cume; porás a porta da arca a um lado; farás nela um andar em baixo, um segundo, e um terceiro andar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 17, 'Eis que estou para derramar as águas do dilúvio sobre a terra, para fazer morrer toda a carne em que há sopro de vida debaixo do céu; tudo o que há sobre a terra perecerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 18, 'Mas contigo estabelecerei a minha aliança: e entrarás na arca tu e teus filhos, tua mulher e as mulheres de teus filhos contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 19, 'De cada espécie de animais, farás entrar na arca dois, macho e fêmea, para que vivam contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 20, 'Das aves, segundo a sua espécie, e das bestas, segundo a sua espécie, de todos os répteis da terra, segundo a sua espécie, de todos entrarão contigo dois, para que possam conservar-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 21, 'Tomarás também contigo de todas as coisas que se podem comer, e as levarás junto de ti, (na arca), e servirão de alimento a ti e aos animais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 22, 'Fez, pois, Noé tudo o que Deus lhe tinha ordenado.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'E o Senhor disse-lhe: entra na arca tu e toda a tua casa, porque te reconheci justo diante de mim no meio desta geração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'Toma de todos os animais puros sete pares, macho e fêmea: e dos animais impuros um par, macho e fêmea.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, 'Toma também das aves do céu sete pares, macho e fêmea, para se conservar a raça sobre a face de toda a terra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'porque, daqui a sete dias, farei chover sobre a terra, durante quarenta dias e quarenta noites, e exterminarei da superfície da terra todos seres (vivos) que fiz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'Fez, pois, Noé tudo o que o Senhor lhe havia ordenado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'Tinha seiscentos anos de idade, quando as águas do dilúvio inundaram a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'Noé entrou na arca com seus filhos, sua mulher e as mulheres de seus filhos, para se salvarem das águas do dilúvio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'Também dos animais puros e impuros, e das aves, e de tudo o que se move sobre a terra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'entraram na arca com Noé, dois a dois, macho e fêmea, conforme o Senhor tinha mandado a Noé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'E, passados os sete dias, cairam sobre a terra as águas do dilúvio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'No ano seiscentos da vida de Noé, no segundo mês, aos dezessete do mês romperam-se todas as fontes do grande abismo, abriam-se as cataratas do céu, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'e caiu chuva sobre a terra durante quarenta dias e quarenta noites.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'Naquele mesmo dia entrou Noé na arca com seus filhos Sem, Cam e Jafeth, sua mulher e as três mulheres de Seus filhos, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'e com eles entraram todos os animais (selváticos), segundo a sua espécie, todos os animais (domésticos). Segundo a sua espécie, tudo o que rasteja Sobre a terra, segundo a sua espécie, tudo o que voa, segundo a sua espécie, todas as aves, e tudo o que tem asas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, '(todos estes animais), entraram com Noé na arca, dois a dois, de toda a espécie, em que havia sopro de vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'Os que entraram eram macho e fêmea de toda a espécie, conforme Deus tinha mandado a Noé; e o Senhor aí o fechou por fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'Veio o dilúvio sobre a terra durante quarenta dias, e as águas cresceram e elevaram a arca muito alto por cima da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'Inundaram tudo com violência e cobriram tudo na superfície da terra; a arca, porém, era levada sobre as águas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'Tanto cresceram as águas que todos os mais elevados montes, que há sob todo o Céu, ficaram cobertos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'A água elevou-se quinze côvados acima delas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'Toda a carne que se movia sobre a terra pereceu: as aves, os animais domesticados, as feras e todos os répteis que andam de rastos sobre a terra, e todos os homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'Tudo o que respira e tem vida sobre a terra, tudo morreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'Foram exterminados todos os sere.s (vivos) que havia sobre a terra, desde o homem até às bestas, tanto os répteis como as aves do céu, tudo foi exterminado da terra: ficou somente Noé, e os que estavam com ele na arca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'As águas cobriram a terra durante cento e cinquenta dias. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'Ora Deus lembrou-Se de Noé, de todos os animais selváticos e de todos os animais domésticos, que estavam com ele na arca, e fez soprar um vento sobre a terra, e as águas diminuíram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, 'Fecharam-se as fontes do abismo e as cataratas do céu, e foram retidas as chuvas (que caiam) do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'As águas, agitadas duma parte para outra, retiraram-se de cima da terra e começaram a diminuir, depois de cento e cinquenta dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'No sétimo més, no vigésimo sétimo dia do mês, parou a arca sobre os montes de Ararat.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, 'Entretanto as águas iam diminuindo até ao décimo més: no décimo mês, no primeiro dia do mês, apareceram os cumes dos montes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'Ao fim de quarenta dias, abriu Noé a janela, que tinha feito na arca, e soltou um corvo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 7, 'o qual ia e vinha, até que as águas secaram sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'Mandou também uma pomba (sete dias depois) dele, para ver se as águas teriam já cessado de cobrir a face da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'E ela; não encontrando onde pousar o seu pé, tomou a vir a ele para a arca, porque (ainda) as águas estavam sobre a terra: (Noé) estendeu a mão, e, tendo-a tomado, a recolheu na arca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'Depois de ter esperado outros sete dias, novamente deitou a pomba fora da arca,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'a qual voltou a ele pela tarde, trazendo no bico um ramo de oliveira com as folhas verdes. Entendeu, pois, Noé que as águas já não cobriam a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'Contudo esperou outros sete dias e mandou a pomba, que não tornou mais a ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'Portanto, no ano seiscentos e um (da vida de Noé), no primeiro mês, no primeiro dia do mês, as águas deixavam a terra: Noé, descoberto o teto da arca, olhou e viu que a superficie da terra se estava a secar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'No segundo mês, no vigésimo sétimo dia do mês, a terra ficou seca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Então Deus falou a Noé, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'sai da arca, tu e tua mulher, teus filhos e as mulheres de teus filhos contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'Faz sair contigo todos os animais que estão contigo, de todas as espécies, tanto de aves como de bestas, e de todos os répteis, que andam de rastos sobre a terra; enchei a terra, crescei e multiplicai-vos sobre ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'Saiu, pois, Noé com seus filhos, sua mulher e as mulheres de seus filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 19, 'Também saíram da arca todos os animais selváticos e domésticos, e os répteis, que andam de rastos sobre a terra, e todas as aves, segundo a sua espécie.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 20, 'E Noé edificou um altar ao Senhor, e, tomando de todos os animais e de todas as aves puras, ofereceu-as em holocausto sobre o altar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 21, 'E (com isto) recebeu o Senhor um suave odor, e disse em seu coração: não amaldiçoarei mais a terra por causa dos homens, porque os sentidos e os pensamentos do coração do homem são inclinados para o mal desde a sua mocidade: não tornarei, pois, a ferir todos os seres vivos como fiz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 22, 'Durante todos os dias da terra, a sementeira e a messe, o frio e o calor, o verão e o inverno, a noite e o dia não mais cessarão. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'Deus abençoou Noé e seus filhos, e disse-lhes: crescei e multiplicai-vos, e enchei a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'Temam e tremam na vossa presença todos os animais da terra, todas as aves do céu, tudo o que se move sobre a terra e todos os peixes do mar: todos ficam sujeitos ao vosso poder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'Tudo o que Se move e vive será vosso alimento: eu vos dou todas estas coisas, como (vos dei) os legumes verdes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, 'Sòmente não comereis carne com sangue,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'porque eu vingarei o vosso sangue da mão de todos os animais (que o derramarem); e ao homem que matar seu irmão, pedirei contas da vida deste homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Todo o que derramar o sangue humano, (será castigado) com a efusão do seu próprio sangue, porque o homem foi feito à imagem de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 7, 'Crescei, pois, e multiplicai-vos, espalhai-vos sobre a terra e enchei-a.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, 'Disse também Deus a Noé e a seus filhos com ele:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'eis que vou fazer a minha aliança convosco, com a vossa posteridade,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'e com todos os seres viventes que estão convosco, tanto aves, como animais domésticos e selváticos, que saíram da arca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'Farei a minha aliança convosco, e não tornará mais a perecer nenhuma criatura pelas águas do dilúvio, nem haverá mais para o futuro dilúvio que assole a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 12, 'E Deus disse: eis o Sinal de aliança, que faço convosco e com todos os animais viventes, que estão convosco, por todas as gerações futuras:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 13, 'porei o meu arco nas nuvens, e ele será o sinal da aliança entre mim e a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 14, 'Quando eu cobrir o céu de nuvens, o meu arco aparecerá nas nuvens, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 15, 'e me lembrarei da minha aliança convosco e com todos os seres vivos da terra, e não voltarão as águas do dilúvio a exterminar toda a carne (que vive).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 16, 'O arco estará nas nuvens, eu o verei e me lembrarei da aliança eterna que foi feita entre Deus e todas as almas viventes e toda a carne que existe sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 17, 'E Deus disse a Noé: este será o sinal da aliança que eu constituí entre mim e toda a carne (que vive) sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 18, 'Ora os filhos de Noé, que saíram da arca, eram Sem, Cam e Jafeth. Cam é o pai de Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 19, 'Estes são os três filhos de Noé, e por eles se propagou todo o género humano sobre toda a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 20, 'Noé, que era agricultor, começou a cultivar a terra e plantou vinha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 21, 'Tendo bebido vinho, embriagou-se e apareceu nu na sua tenda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 22, 'Cam, pai de Canaan, tendo visto a nudez de seu pai, saiu fora a dizê-lo a seus dois irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 23, 'Porém Sem e Jafeth puseram uma capa sobre os seus ombros, e, andando para trás, cobriram a nudez de seu pai: assim, tendo o rosto voltado, não viram a sua nudez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 24, 'Quando Noé, despertando da embriaguez, soube o que lhe tinha feito o seu filho mais novo, disse:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 25, 'maldito seja Canaan! Ele será o servo dos servos de seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 26, 'Depois disse: Bendito seja o Senhor Deus de Sem, e Canaan seja seu escravo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 27, 'Dilate Deus a Jafeth, e habite Jafeth nas tendas de Sem, e Canaan seja seu escravo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 28, 'Ora Noé viveu ainda depois do dilúvio trezentos e cinquenta anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 29, 'Todo o tempo da sua vida foi de novecentos e cinquenta anos, e morreu. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'Eis a posteridade dos filhos de Noé: Sem, Cam e Jafeth. A estes nasceram filhos depois do dilúvio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, 'Filhos de Jafeth: Gomer, Magog, Madai, Javan, Tubal, Mosoch e Tiras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'Filhos de Gomer: Arcenez, Rifath e Togorma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'Filhos de Javan: Elisa e Tarsis, Cetim e Dodanim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'Destes saíram (os habitantes) das ilhas das nações nas suas (diversas) regiões, cada um segundo a sua língua, segundo as suas famílias, segundo as suas nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Filhos de Cam: Cus, Mesraim, Futh e Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 7, 'Filhos de Cus: Saba, Hevila, Sabata, Regma e Sabataca. Filhos de Regma: Saba e Dadan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'Cus gerou Nemrod, o qual começou a ser poderoso na terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'Era um robusto caçador diante do Senhor. Daqui veio este provérbio: Robusto caçador diante do Senhor como Nemrod.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'O princípio do seu reino foi Babilônia, Arach, Acad e Calane, na terra de Senaar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'Daquela terra foi para Assur, e edificou Nínive, e Rechoboth-Ir, e Calé, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'e também Resen, a grande cidade, entre Nínive e Calé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'Mesraim gerou Ludim, Anamim, Laabim, Neftuim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'Fretusim e Casluim, dos quais saíram os Filisteus e os Caftoreus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 15, 'Canaan gerou Sidónio, seu filho primogênito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 16, 'Hete, (sendo também o pai dos) Jebuseus, Amorreus, Gergeseus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 17, 'Heveus, Araceus, Sineus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 18, 'Aradeus, Samareus e Amateus. Depois disto, espalharam-se as famílias dos Cananeus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 19, 'indo os limites dos seus territórios, desde Sidónia, na direção de Gerara, até Gaza, e, na direção de Sodoma, Gomorra, Adamam e Seboim, até Lesa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 20, 'Estes são os filhos de Cam, segundo as suas famílias, línguas, regiões e nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 21, 'De Sem, pai de todos os filhos de Heber e irmão mais velho de Jafeth, nasceram também filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 22, 'Filhos de Sem: Elam, Assur, Arfaxad, Lud e Arão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 23, 'Filhos de Arão: Us, Hul, Geter e Més.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 24, 'Arfaxad gerou Salé, de quem nasceu Heber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 25, 'A Heber nasceram dois filhos: um chamou-se Faleg, porque em seu tempo foi dividida a terra, e seu irmão chamou-se Jectan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 26, 'Este Jectan gerou Elmodad, Saleph, Asarmoith, Jaré,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 27, 'Adurão, Usai, Decla,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 28, 'Ebal, Abimael, Saba,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 29, 'Ofir, Hévila e Jobab; todos estes são filhos de Jectan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 30, 'O país onde eles habitaram estendia-se desde Messa até Sefar, monte que está ao oriente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 31, 'Estes são os filhos de Sem, Segundo as suas famílias, línguas, regiões e nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 32, 'Estas são as familias dos filhos de Noé, segundo as suas gerações e nações. Delas saíram todos os povos da terra depois do dilúvio. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, 'Ora toda a terra tinha uma só língua e um mesmo modo de falar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, 'Mas (os homens), tendo partido do oriente, encontraram uma planície na terra de Senaar e habitaram nela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'Disseram uns para os outros: vinde, façamos tijolos e cozámo-los no fogo. E serviram-se de tijolos em vez de pedras, e de betume em vez de argamassa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'Disseram ainda: vinde, façamos para nós uma cidade e uma torre, cujo cimo chegue até ao céu, e tomemos célebre o nosso nome, antes que nos espalhemos por toda a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'O Senhor, porém, desceu a ver a cidade e a torre, que os filhos dos homens edificavam, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'e disse: eis que são um só povo e têm todos a mesma lingua: começaram a fazer esta obra, e não desistirão do seu intento, até que a tenham de todo executado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'Vamos, pois, desçamos e confundamos de tal sorte a sua linguagem, que um não compreenda a palavra do outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'Assim o Senhor os dispersou daquele lugar por todos os países da terra, e cessaram de edificar a cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'Por isso, lhe foi posto o nome de Babel, porque aí foi confundida a linguagem de toda a terra, e daí os espalhou o Senhor por todas as regiões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'Eis as gerações de Sem: Sem tinha cem anos, quando gerou Arfaxad, dois anos depois do dilúvio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Depois que gerou Arfaxad, Sem viveu quinhentos anos e gerou filhos e filhas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'Arfaxad viveu trinta e cinco anos, e gerou Salé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'Depois que gerou Salé, viveu Arfaxad trezentos e três anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'Salé viveu trinta anos, e gerou Heber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'Depois que gerou Hebér, viveu Salé quatrocentos e três anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'Heber viveu trinta e quatro anos, e gerou Faleg.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'Depois que gerou Faleg, viveu Heber quatrocentos e trinta anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Faleg viveu trinta anos, e gerou Reu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'Depois que gerou Reu, viveu Faleg duzentos e nove anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, 'Reu viveu trinta e dois anos, e gerou Sarug.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Depois que gerou Sarug, viveu Reu duzentos e sete anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'Sarug viveu trinta anos, e gerou Nacor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'Depois que gerou Nacor, viveu Sarug duzentos anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 24, 'Nacor viveu vinte e nove anos, e gerou Taré.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 25, 'Depois que gerou Taié, viveu Nacor cento e dezanove anos, e gerou filhos e filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 26, 'Taré viveu setenta anos, e gerou Abrão, Nacor e Aran.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 27, 'Eis as gerações de Taré: Taré gerou Abrão, Nacor e Aran. Aran gerou Loth.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 28, 'Aran morreu antes de seu pai Taré, na terra do seu nascimento, em Ur dos Caldeus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 29, 'Abrão e Nacor tomaram mulheres; a mulher de Abrão chamava-se Sarai; e a de Nacor, Melca, filha de Aran, pai de Melca e de Jesca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 30, 'Sarai, porém, era estéril e não tinha filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 31, 'Tomou, pois, Taré a seu filho Abrão e a Loth, seu neto, filho de Aran, e a Sarai, sua nora, mulher de Abrão, seu filho, e fê-los sair de Ur dos Caldeus, afim de irem para o país de Canaan; foram até Haran, e aí habitaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 32, 'Taré viveu duzentos e cinco anos, e morreu em Haran.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'Ora o Senhor disse a Abrão: saí da tua terra, da tua parentela, da casa de teu pai, e vem para a terra que eu te mostrar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 2, 'Farei (sair) de ti um grande povo, e te abençoarei, engrandecerei o teu nome e serás bendito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'Abençoarei os que te abençoarem, amaldiçoarei os que te amaldiçoarem; em ti serão benditas todas as nações da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'Partiu, pois, Abrão, como o Senhor lhe tinha ordenado, e foi com ele Loth. Tinha Abrão setenta e cinco anos, quando saiu de Haran '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, 'Levou consigo Sarai, sua mulher, Loth, filho de seu irmão, todos os bens que possuíam e as pessoas que tinham adquirido em Haran. Partiram, a caminho da terra de Canaan, e lá chegaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, 'Abrão atravessou este pais até ao lugar de Siquém, até à cadeia de Moré. Os Cananeus estavam então naquela terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 7, 'O Senhor apareceu a Abrão e disse-lhe: darei esta terra aos teus descendentes. Naquele lugar, (Abrão) edificou um altar ao Senhor, que lhe tinha aparecido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'Passando dali ao monte, que estava ao oriente de Betel, ai levantou a sua tenda, tendo Betel ao ocidente, e Hai ao oriente. Aí edificou também um altar ao Senhor, e invocou o seu nome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, 'Abrão continuou a sua viagem, andando e avançando para o meio-dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'Sobreveio, porém, uma fome no país, e Abrão desceu ao Egito, para ai viver algum tempo, porque a fome era muita no (seu) pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'Quando estava perto de entrar no Egito disse a Sarai, sua mulher: conheço que és uma mulher formosa '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'e que, quando os Egípcios te virem, dirão: é sua mulher - e matar-me-ão, conservando-te a ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'Dize, pois, te peço, que és minha irmã, para que eu seja bem tratado por causa de ti, e me conservem a vida, em atenção a ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'Tendo pois Abrão entrado no Egito, viram os Egípcios que aquela mulher era muito formosa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'Os grandes de Faraó, vendo-a, gabaram-na muito diante dele: e a mulher foi levada ao palácio do Faraó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'Trataram bem Abrão, por causa dela, e ele teve ovelhas, bois, jumentos, servos, servas, jumentas e camelos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'O Senhor, porém, feriu Faraó e a sua casa com grandíssimas pragas, por causa de Sarai, mulher de Abrão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'Então Faraó chamou Abrão e disse-lhe: por que te houveste comigo desta sorte? Por que não declaraste que ela era tua mulher?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, 'Por que disseste que ela era tua irmã, para que eu a tomasse por minha mulher? Agora, pois, aí tens a tua mulher, toma-a e vai-te.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 20, 'E Faraó deu ordens a seus homens para cuidarem de Abrão, e eles o acompanharam (até à saída do Egito) com sua mulher e com tudo o que possuía. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'Abrão, pois, saiu do Egito com sua mulher e com tudo o que possuía, e Loth com ele, e caminhou para a parte meridional.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'Era Abrão muito rico em gado, ouro e prata.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'Voltou pelo caminho, por onde tinha vindo do meio-dia até Betei, até ao lugar onde primeiro tinha levantado a (sua) tenda, entre Betei e Hai, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, 'no lugar onde estava o altar que tinha levantado antes, e ai invocou o nome do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'Mas também Loth, que estava com Abrão, tinha rebanhos de ovelhas, manadas e tendas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'E a terra não tinha capacidade para poderem habitar juntos, porque os seus bens eram grandes demais para viverem um com o outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'Daqui nasceu uma contenda entre os pastores dos rebanhos de Abrão e os de Loth. Cananeus e Fereseus habitavam, então, naquela terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'Disse, pois, Abrão a Loth: peço-te que não haja contendas entre mim e ti, nem entre os meus pastores e os teus pastores, porque somos irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'Eis diante de ti todo o país, rogo-te que te apartes de mim: se fores para a esquerda, eu tomarei para a direita; se escolheres a direita, eu irei para a esquerda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'Loth, pois, levantando os olhos, contemplou toda a região do Jordão, a qual, antes que o Senhor destruísse Sodoma e Gomorra, era toda regada de água, como o paraíso do Senhor, e como o Egito, do lado de Segor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'Loth escolheu para si a região do Jordão, e retirou-se para o oriente: assim se separaram um do outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'Abrão habitou na terra de Canaan, e Loth nas cidades que estavam ao redor do Jordão, e fixou a sua residência em Sodoma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'Ora os homens de Sodoma eram péssimos, e grandes pecadores diante de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'O Senhor disse a Abrão, depois que Loth se separou dele: levanta os teus olhos e repara, desde o lugar em que agora estás, para o setentrião e para o meio-dia, para o oriente e para o ocidente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 15, 'Toda a terra que vês, eu a darei para sempre a ti e à tua posteridade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 16, 'Multiplicarei a tua descendência como o pó da terra; se algum dos homens pode contar o pó da terra, poderá também contar o número dos teus descendentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 17, 'Levanta-te e percorre o pais em todo o seu comprimento, porque eu to hei-de dar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 18, 'Portanto, levantando Abrão a sua tenda, foi habitar ao pé da cadeia de Mambré, que está em Hebron; e aí edificou um altar ao Senhor. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Naquele tempo sucedeu que Amrafel, rei de Senaar, e Arioch, rei do Ponto, e Codorlaomor, rei dos Elamitas, e Tadal, rei de Goím, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 2, 'fizeram guerra contra Bara, rei de Sodoma, e contra Bersa, rei de Gomorra, e contra Senaar, rei de Adama, e contra Semeber, rei, de Seboim, e contra o rei de Bala, isto é Segor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'Todos estes se juntaram no vale de Sidim, que agora é o mar salgado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, '(O motivo foi) porque, tendo estado sujeitos doze anos a Codorlaomor, no décimo terceiro ano revoltaram-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 5, 'Por isso Codorlaomor foi, no ano décimo quarto, com os reis que se lhe tinham unido, e desbarataram os Refaim em Astaroth-Carnaim, os Zuzim em Ham, os Emim na planície de Cariataim, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'os Horreus nos montes de Seir, até aos campos de Faran, que está no deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 7, 'E, voltando (estes reis da sua expedição), foram à fonte de Misfath, que é a mesma que Cades, e devastaram todos os países dos Amalecitas e dos Amorreus, que habitavam em Asason-Tamar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, 'Então o rei de Sodoma, o rei de Gomorra, o rei de Adama, o rei de Seboim e também o rei de Bala, isto é Segor, puseram-se em campanha, e ordenaram a batalha no vale de Sidim contra aqueles (príncipes),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'isto é, contra Codorlaomor, rei dos Elamitas e Tadal, rei de Goim e Anrabel, rei de Senaar, e Arioque, rei de Elasar: quatro reis contra cinco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, 'Ora o vale de Sidim tinha muitos poços de betume. Os reis de Sodoma e de Gomorra voltaram as costas e caíram lá dentro: os que escaparam fugiram para o monte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, '(Os vencedores) levaram todas as riquezas de Sodoma e Gomorra, e todos os víveres, e retiraram-se; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, '(levaram) também Loth, filho do irmão de Abrão, que morava em Sodoma, e os seus bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'Um dos fugitivos foi dar parte disto a Abrão, Hebreu, que vivia na cadeia de Mambré, Amorreu, irmão de Escol, e irmão de Aner, os quais tinham feito aliança com Abrão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'Abrão, tendo ouvido que Loth, seu irmão, ficara prisioneiro, escolheu os mais corajosos dos seus servos, em número de trezentos e dezoito, e foi no alcance dos inimigos até Dan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'Aí, repartidos em destacamentos, deu sobre eles, de noite, e desbaratou-os: e persegui-os até Hoba, que fica à esquerda de Damasco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 16, 'Recobrou todos os Seus bens, e Loth, seu irmão, com tudo o que lhe pertencia, assim como as mulheres e o povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 17, 'Quando voltava de derrotar Codorlaomor e os reis Abrão que estavam com ele, saiu-lhe ao encontro o rei de Sodoma, no vale de Save, que é o vale do Rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 18, 'E Melquisedech, rei de Salém, trazendo pão e vinho, porque era sacerdote do Deus Altíssimo, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 19, 'o abençoou e lhe disse: bendito esteja Abrão pelo Deus Altíssimo, que criou o céu e a terra, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 20, 'e bendito seja o Deus Altíssimo por cuja proteção os inimigos estão nas tuas mãos. E (Abrão) deu-lhe o dizimo de tudo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 21, 'O rei de Sodoma disse a Abrão: dá-me os homens, e toma para ti o resto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 22, 'Abrão respondeu-lhe: levanto a minha mão para o Senhor Deus Altíssimo, possuidor do céu e da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 23, '(e juro) que não receberei nada de tudo o que te pertence, desde o fio de trama até à correia dos sapatos, para que não digas: eu enriqueci Abrão; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 24, 'há a exceptuar aquilo que estes jovens comeram, e a porção dos homens que vieram comigo, Aner, Escol e Mambré: estes hão-de receber a sua parte. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'Passado isto, falou o Senhor a Abrão numa visão, dizendo: não temas, Abrão, eu sou o teu protetor e a tua recompensa (será) excessivamente grande.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'Abrão respondeu; Senhor Deus, que me darás tu? Eu irei sem filhos, e o herdeiro da minha casa é este Eliezer de Damasco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'E acrescentou Abrão: a mim não me deste filhos, e meu escravo será meu herdeiro. Imediatamente o Senhor lhe dirigiu a palavra, dizendo: este não será o teu herdeiro, mas terás por herdeiro aquele que nascer de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'Depois conduziu-o fora, e disse-lhe: olha para o céu e conta, se podes, as estrelas. Depois acrescentou: assim será a tua descendência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'Creu Abrão em Deus, e (este ato de fé) lhe foi imputado como justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 7, 'Disse-lhe mais o Senhor: eu sou o Senhor que te tirei de Ur dos Caldeus, para te dar esta terra, e a possuíres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'Abrão respondeu: Senhor Deus, por onde poderei eu conhecer que a hei-de possuir? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 9, 'E o Senhor continuou: toma-me (para sacrificar) uma vaca de três anos, uma cabra de três anos, um carneiro de três anos, e também uma rola e uma pomba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 10, 'Ele, tomando todos estes animais, dividiu-os pelo meio e pôs as duas partes uma defronte da outra, mas não dividiu as aves.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 11, 'Ora as aves (de rapina) desciam sobre os cadáveres, e Abrão as enxotava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 12, 'Ao pôr do sol, veio um profundo sono a Abrão, e um horror grande e tenebroso o acometeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 13, 'E foi-lhe dito: sabe, desde agora, que a tua descendência será peregrina numa terra não sua, e será reduzida à escravidão, e afligida durante quatrocentos anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 14, 'Mas eu exercerei os meus juízos sobre o povo ao qual estiverem sujeitos: e sairão depois (desse país) com grandes riquezas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 15, 'Tu, porém, irás em paz para teus pais, e serás sepultado numa ditosa velhice.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 16, 'Mas, à quarta geração, (os teus) voltarão para aqui, porque as iniquidades dos Amorreus não estão ainda completas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 17, 'Quando, pois, se pôs o sol, formaram-se densas trevas, apareceu um forno fumegante e um facho ardente, que passavam pelo meio dos animais divididos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 18, 'Naquele dia fez o Senhor aliança com Abrão, dizendo: darei à tua descendência esta terra, desde o rio do Egito até ao grande rio Eufrates, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 19, 'os Cineus, os Cenezeus, os Oedmoneus, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 20, 'os Heteus, os Ferezeus e também os Rafaim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 21, 'os Amorreus, os Cananeus, os Gergeseus e os Jebuseus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'Ora Sarai, mulher de Abrão, não tinha gerado filhos; mas, tendo uma escrava egípcia, chamada Agar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'disse a seu marido: eis que o Senhor me fez estéril, para que não de à luz; toma, pois, a minha escrava, a ver se, ao menos por ela, posso ter filhos. Como Abrão anuísse aos seus rogos, (Sarai) '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, 'tomou Agar egípcia, sua escrava, passados dez anos desde que tinham começado a habitar na terra de Canaan, e deu-a por mulher a seu marido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'E ele aproximou-se dela, que concebeu; ela, vendo que tinha concebido, desprezou sua Senhora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'Sarai disse a Abrão: tu tratas-me dum modo injusto: eu dei-te a minha escrava para tua mulher, e ela, vendo que concebeu, despreza-me: o Senhor seja juiz entre mim e ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'Abrão respondeu-lhe: eis que a tua escrava está em teu poder, usa dela como te aprouver. Então Sarai a maltratou e Agar fugiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'Tendo-a o anjo do Senhor achado no deserto junto da fonte, que está no caminho de Sur no deserto, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'disse-lhe: Agar, escrava de Sarai, donde vens e para onde vais? Ela respondeu: fujo da face de Sarai, minha senhora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'E o anjo do Senhor disse-lhe: volta para a tua senhora, e humilha-te debaixo da sua mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'E acrescentou: multiplicarei extraordinariamente a tua descendência e a farei tão numerosa que se não poderá contar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 11, 'Disse ainda mais: eis que concebeste, darás à luz um filho e lhe porás o nome de Ismael, parque o Senhor te ouviu na tua aflição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 12, 'Este será como um cavalo selvagem: a sua mão (se levantará) contra todos, e as mãos de todos (se levantarão) contra ele; levantará as suas tendas defronte de todos os seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 13, 'Então (Agar) invocou o nome do Senhor que lhe falava, chamando-lhe Atta-El-Roi porque, dizia ela, não vi eu, aqui mesmo, o Deus que me via? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 14, 'Por esta razão chamou ela àquele poço o Poço Lachai-Roi, o qual fica situado entre Cades e Barad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 15, 'Agar deu à luz um filho a Abrão, o qual lhe pôs o nome de Ismael '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 16, 'Tinha Abrão oitenta e seis anos, quando Agar lhe deu à luz Ismael.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 1, 'Mas, quando (Abrão) chegou à idade de noventa e nove anos, o Senhor apareceu-lhe e disse-lhe: Eu (sou) o Deus onipotente; anda em minha presença e sê perfeito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 2, 'Farei a minha aliança entre mim e ti, e te multiplicarei extraordinariamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 3, 'Abrão prostrou-se com o rosto por terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 4, 'Deus disse-lhe: Eis minha aliança contigo: tu serás pai de muitas gentes '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 5, 'e não mais serás chamado com o nome de Abrão, mas chamar-te-ás Abraão, porque te destinei para pai de muitas gentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 6, 'Eu te farei crescer (na tua posteridade) extraordinariamente, farei de ti nações, e de ti sairão reis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 7, 'E estabelecerei a minha que eu seja o teu Deus, e da tua descendência, depois de ti, no decurso das suas gerações, por um pacto eterno, para que eu seja o teu Deus, e da tua descendência, depois de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 8, 'Darei a ti e á tua posteridade a terra da tua peregrinação, (que é) toda a terra de Canaan, em possessão eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 9, 'Disse mais Deus a Abraão: tu, pois, guardarás a minha aliança, tu e os teus descendentes depois de ti, nas suas gerações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 10, 'Eis o pacto, que haveis de guardar, tu e a tua posteridade, depois de ti: todo o varão será circuncidado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 11, 'Circuncidareis a carne do vosso prepúcio, e este será o sinal da aliança entre mim e vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 12, 'O menino de oito dias será circuncidado entre vós, nas vossas gerações: os escravos, tanto o escravo (nascido em casa), como o que comprardes, mesmo que não seja da vossa linhagem, serão circuncidados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 13, 'Este meu pacto (será marcado) na vossa carne para (sinal de) aliança eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 14, 'O indivíduo do sexo masculino, cuja carne não tiver sido circuncidada, será excluido do seu povo, porque violou a minha aliança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 15, 'Disse também Deus a Abraão: a Sarai, tua mulher, não chamarás mais Sarai, mas Sara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 16, 'Eu a abençoarei, e dela te darei um filho, o qual abençoarei, e será chefe de nações, e dele sairão reis de povos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 17, 'Abraão prostrou-se com o rosto por terra e riu-se, dizendo no seu coração: é possível que a um homem de cem anos nasça um filho? e que Sara dê à luz aos noventa? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 18, 'E disse a Deus: Oxalá que Ismael viva em tua presença! '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 19, 'Deus respondeu a Abraão: Sara, tua mulher, te dará à luz um filho, e lhe porás o nome de Isaac, e farei o meu pacto com ele e com a sua descendência, depois dele, por uma aliança eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 20, 'Eu te ouvi também acerca de Ismael: abençoá-lo-ei, fá-lo-ei crescer e o multiplicarei extraordinariamente: gerará doze príncipes e farei dele uma grande nação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 21, 'Mas o meu pacto, firmá-lo-ei com Isaac, que Sara te dará à luz no próximo ano, nesta mesma época.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 22, 'Acabada que foi esta sua conversação com ele, retirou-se Deus de Abraão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 23, 'Tomou, pois, Abraão seu filho Ismael, todos os escravos nascidos em sua casa, todos os que tinha comprado, e, em geral, todos os homens de sua casa, e os circuncidou logo no mesmo dia, como Deus lhe tinha ordenado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 24, 'Tinha Abraão noventa e nove anos, quando se circuncidou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 25, 'Ismael, seu filho, tinha treze anos, quando foi circuncidado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 26, 'Abraão e seu filho Ismael foram circuncidados no mesmo dia;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 27, 'todos os homens da sua casa, tanto os escravos (nascidos nela), como os comprados e os estrangeiros, foram circuncidados com ele.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 1, 'O Senhor apareceu (a Abraão) na cadeia de Mambré, quando ele estava assentado à porta da sua tenda, no maior calor do dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 2, 'Tendo (Abraão) levantado os olhos, apareceram-lhe três homens que estavam em pé junto dele; logo que os viu, correu da porta da tenda ao seu encontro e prostrou-se por terra, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 3, 'dizendo-lhes: Senhor, se achei graça diante dos teus olhos, não passes (sem parar junto do) teu Servo; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 4, 'trarei um pouco de água para lavar vossos pés, e descansai debaixo desta árvore: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 5, 'servir-vos-ei um pedaço de pão, refareis as vossas forças e depois continuareis o vosso caminho, porque para isso viestes até junto do vosso servo. Eles responderam: faze como disseste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 6, 'Foi Abraão depressa à tenda de Sara e disse-lhe: amassa já três medidas de flor de farinha e faze cozer pães ao borralho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 7, 'Ele correu à manada, tomou um novilho dos mais tenros e melhores, e deu-o a um criado, o qual se apressou a cozê-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 8, 'Tomou também manteiga e leite, e o novilho cozido, e pôs (tudo) diante deles: enquanto comiam, estava de pé junto deles debaixo da árvore.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 9, 'Então disseram-lhe: onde está Sara, tua mulher? Ele respondeu: está, ali, na tenda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 10, 'E (um deles) disse-lhe: tornarei, a vir ter contigo neste mesmo tempo no próximo ano, e Sara, tua mulher, terá um filho. Sara, ao ouvir isto, riu-se detrás da porta da tenda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 11, 'Ambos eram velhos, de idade avançada, e o que é ordinário às mulheres tinha cessado para Sara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 12, 'Ela, pois, riu-se secretamente, dizendo: depois que sou velha, e meu senhor avançado em anos, entregar-me-ei ao deleite? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 13, 'Mas o Senhor disse a Abraão: Por que se riu Sara, dizendo: será verdade que eu possa dar à luz, sendo já velha? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 14, 'Há porventura alguma coisa (que seja) difícil a Deus? Voltarei a ti, segundo a promessa feita, neste mesmo tempo no próximo ano, e Sara terá um filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 15, 'Sara (cheia de medo) negou, dizendo: eu não me ri. Mas o Senhor disse: não é assim; tu riste-te.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 16, 'Tendo-se, pois, levantado dali aqueles homens, dirigiram-se para Sodoma; Abraão ia com eles, acompanhando-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 17, 'Senhor disse: acaso poderei eu ocultar a Abraão o que estou para fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 18, 'havendo de ser, como será, pai duma nação numerosíssima e poderosíssima, e havendo todas as nações da terra de ser benditas nele? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 19, 'Escolhi-o, com efeito, para ordenar a seus filhos e à sua casa, depois dele, que guardem os caminhos do Senhor e que pratiquem a equidade e a justiça, para que o Senhor cumpra a favor de Abraão tudo o que lhe prometeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 20, 'Disse, pois, o Senhor; o clamor de Sodoma e de Gomorra aumentou, e o seu pecado agravou-se extraordinariamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 21, 'Descerei e verei se as suas obras correspondem ao clamor que chegou até mim; ou, se assim não é, para o saber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 22, 'Partiram dali e foram para Sodoma; mas Abraão estava ainda diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 23, 'Aproximando-se (dele), disse: perderás tu o justo com o impio? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 24, 'Se houver cinquenta justos na cidade, perecerão todos juntos? E não perdoarás àquele lugar por causa de cinquenta justos, se aí os houver?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 25, 'Longe de ti que faças tal coisa, que mates o justo com o ímpio, e o justo seja tratado com o ímpio. Longe isso de ti! Tu que julgas toda a terra, de nenhuma sorte farás tal juízo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 26, 'O Senhor disse-lhe: se eu achar no meio da cidade de Sodoma cinquenta justos, perdoarei por amor deles a toda a cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 27, 'Respondendo Abraão, disse: uma vez que comecei, falarei ao meu Senhor, ainda que eu seja pó e cinza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 28, 'Que sucederá, se faltarem cinco para os cinquenta justos? Destruirás toda a cidade, porque nela se acham sòmente quarenta e cinco? E (o Senhor) disse: não a destruirei, se achar nela quarenta e cinco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 29, '(Abraão) continuou e disse-lhe: e se nela houver quarenta (justos), que farás tu? Não a castigarei, disse o Senhor, por amor dos quarenta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 30, 'Rogo-te, Senhor, diz (Abraão), que te não indignes, se eu (ainda continuo a) falar. Que farás tu, se lá houver trinta (justos)? Respondeu: se eu achar nela trinta, não farei (a sua destruição).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 31, 'Visto que comecei, disse Abraão, falarei (ainda) ao meu Senhor. E se ali forem achados vinte? Respondeu: não a arruinarei por amor dos vinte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 32, 'Eu, te conjuro. Senhor, continuou Abraão, não te enfades, se eu te falar ainda uma vez: que será, se lá forem achados dez justos? E (o Senhor) disse: não a destruirei por amor dos dez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 33, 'O Senhor retirou-se, depois que cessou de falar com Abraão, e Abraão voltou para casa.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 1, 'Sobre a tarde chegaram os dois anjos a Sodoma, quando Loth estava assentado às portas da cidade. Ele, tendo-os visto, levantou-se, foi ao seu encontro, prostrou-se por terra, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 2, 'e disse: vinde, vos peço, senhores, para casa de vosso servo, e ficai nela: lavareis os vossos pés e, pela manhã, continuareis o vosso caminho. Eles responderam: não, nós ficaremos na praça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 3, 'Loth instou com eles para que fossem para sua casa: depois que entraram, preparou-lhes um banquete, fez cozer uns pães ázimos, e eles comeram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 4, 'Mas, antes que se fossem deitar, os homens da cidade, os homens de Sodoma, desde os meninos até aos velhos, todos, sem excepção, cercaram a casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 5, 'Chamaram por Loth e disseram-lhe: onde estão aqueles homens que entraram em tua casa ao cair da noite? Faze-os sair para que os conheçamos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 6, 'Saiu Loth, fechando nas suas costas a porta, e disse-lhes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 7, 'não queirais, vos rogo, meus irmãos, não queirais fazer este mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 8, 'Tenho duas filhas, que ainda são virgens; eu vo-las trarei, e abusai delas como vos agradar, contando que não façais mal algum a estes homens, porque se acolheram à sombra do meu telhado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 9, 'Eles, porém, disseram: retira-te para lá. E acrescentaram: tu entraste aqui como estrangeiro; será talvez para nos julgares? A ti, pois, trataremos pior do que a eles. E forçavam Loth com grande violência; e já estavam a ponto de arrombar a porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 10, 'E eis que os (dois) homens (que estavam dentro) estenderam a mão, introduziram Loth em casa, e fecharam a porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 11, 'E feriram de cegueira os que estavam fora, desde o mais pequeno até ao maior, de sorte que não podiam encontrar a porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 12, 'E disseram a Loth: tens aqui algum dos teus? genro ou filho, ou filhas, faze sair desta cidade todos os que te pertencem, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 13, 'porque nós vamos destruir este lugar, visto que o clamor (dos seus crimes) aumentou diante do Senhor, o qual nos enviou para que os exterminemos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 14, 'Loth, pois, tendo saído falou a seus (futuros) genros, que estavam para casar com suas filhas, e disse: levantai-vos. Saí deste lugar, porque o Senhor destruirá esta cidade. E pareceu-lhes que (Loth) falava zombando.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 15, 'Ao amanhecer, instavam os anjos com Loth, dizendo: levanta-te, toma tua mulher e as duas filhas que tens, não suceda que também pereças na ruína da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 16, 'Como ele hesitasse, pegaram pela mão a ele, a sua mulher e ás suas duas filhas, porque o Senhor queria salvá-lo, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 17, 'e o tiraram de casa, e o puseram fora da cidade. Uma vez fora, falaram, dizendo: salva a tua vida, não olhes para trás e não pareis em parte alguma dos arredores deste país; mas salva-te no monte, para que não pereças com os outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 18, 'Loth disse-lhes: rogo-te, meu Senhor, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 19, 'visto que o teu servo achou graça diante de ti, e usaste comigo da grande misericórdia de salvar a minha vida, (consideres) que eu me não posso salvar no monte, sem correr o perigo de ser apanhado pelo mal e morrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 20, 'Eis que está perto uma cidade pequena, para a qual posso fugir, e salvar-me-ei nela. Não é ela pequena, e nela não estará segura a minha vida? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 21, 'E o Senhor disse-lhe: ainda nisto eu ouvi os teus rogos, para não destruir a cidade a favor da qual me falaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 22, 'Apressa-te e salva-te lá, porque não poderei fazer nada, enquanto tu lá não tiveres entrado. Por isso puseram àquela cidade o nome de Segor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 23, 'O sol levantava-se sobre a terra, quando Loth entrou em Segor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 24, 'Fez, pois, o Senhor da parte do Senhor chover sobre Sodoma e Gomorra enxofre e fogo (vindo) do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 25, 'e destruiu estas cidades, todo o pais em roda, todos os habitantes das cidades e toda a verdura da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 26, 'A mulher de Loth, tendo olhado para trás, ficou convertida numa estátua de sal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 27, 'Ora Abraão, tendo-se levantado de manhã, foi ao lugar onde antes tinha estado com o Senhor, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 28, 'e olhou para Sodoma e Gomorra, e para toda a terra daquela região, e viu que se elevavam da terra cinzas infamadas, como o fumo duma fornalha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 29, 'Quando destruía as cidades daquela região, lembrou-se de Abraão e livrou Loth da ruína destas cidades, em que tinha habitado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 30, 'Loth partiu de Segor e retirou-se para o monte com suas duas filhas (porque temia ficar em Segor), e habitou em uma caverna com as suas duas filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 31, 'A mais velha disse à mais nova: nosso pai está velho, e na terra não ficou homem algum com quem nos possamos casar, segundo o costume de todos os países.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 32, 'Vem, embriaguêmo-lo com vinho, e durmamos com ele, para que possamos conservar a linhagem de nosso pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 33, 'Deram, pois, a beber vinho a seu pai naquela noite, e a mais velha entrou e dormiu com o pai: ele, porém, não sentiu nem quando ela se deitou, nem quando se levantou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 34, 'No dia seguinte disse a mais velha para a mais nova: eis que eu ontem dormi com meu pai: demos-lhe também esta noite a beber vinho e dormirás tu com ele, para salvarmos a linhagem de nosso pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 35, 'Também, naquela noite deram a beber vinho a seu pai, e a filha mais nova entrou e dormiu com ele: nem então ele sentiu quando ela se deitou, nem quando se levantou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 36, 'E as duas filhas de Loth conceberam de teu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 37, 'A mais velha deu à luz um filho e pôs-lhe o nome de Moab: este é o pai dos moabitas (que existem) até ao dia de hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 38, 'A mais nova também deu à luz um filho e pôs-lhe o nome de Amon, que quer dizer filho do meu povo: este é o pai dos amonitas, (que existem) até ao dia de hoje.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 1, 'Abraão partiu dali para a parte do meio-dia, habitou entre Cades e Sur, e viveu como peregrino em Gerara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 2, 'Falando de Sara sua mulher, dizia: é minha irmã. Mandou, pois, Abimelech, rei de Gerara, buscá-la.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 3, 'Mas Deus apareceu de noite em sonhos a Abimelech e disse-lhe: Eis que morrerás por causa da mulher que roubaste, porque ela tem marido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 4, 'Abimelech, que não a tinha tocado, disse: Senhor, matarás tu assim mesmo um inocente?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 5, 'Porventura não me disse ele: ela é minha irmã? e não me disse ela: ele é meu irmão? Fiz isto na simplicidade do meu coração, e com pureza das minhas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 6, 'Deus disse-lhe: Sei que procedeste com um coração simples, e, por isso, te preservei de pecar contra mim, e não permiti que a tocasses.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 7, 'Agora, pois, entrega a mulher a seu marido, porque ele é profeta, rogará por ti, e viverás; se, porém, não quiseres restitui-la, sabe que morrerás indubitàvelmente, tu e tudo o que é teu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 8, 'Abimelech, levantando-se logo, Sendo ainda noite, chamou todos os seus servos, contou-lhes todas estas coisas, e eles ficaram muito atemorizados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 9, 'Depois Abimelech chamou também Abraão e disse-lhe: que nos fizeste tu? Que mal te fizemos nós para atraires sobre mim e sobre o meu reino um (tão) grande pecado? Fizeste-nos o que não deveras fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 10, 'E, continuando ainda as suas queixas, disse: o que tiveste em vista fazendo isto ?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 11, 'Abraão respondeu-lhe: pensei comigo mesmo: com certeza, nesta terra não há temor de Deus e me matarão por causa de minha mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 12, 'Por outra parte ela é verdadeiramente minha irmã, (como) filha de meu pai, (embora) não (seja) filha de minha mãe, e eu a recebi por mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 13, 'Depois que Deus me tirou da casa de meu pai, eu disse-lhe: faze-me esta graça: em qualquer lugar onde entrarmos, dirás que eu sou teu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 14, 'Tomou, pois, Abimelech ovelhas e bois, escravos e escravas, deu-os a Abraão, restituiu-lhe Sara, sua mulher, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 15, 'e disse-lhe: esta terra está diante de ti, habita onde te agradar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 16, 'E disse a Sara: eis que dei mil moedas de prata a teu irmão, e este dinheiro será para ti um véu sobre os olhos, diante de todos os que estiverem contigo: eis-te justificada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 17, 'E, orando Abraão, Deus sarou Abimelech, sua mulher e suas escravas, que tiveram (novamente) filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 18, 'Com efeito, o Senhor tinha tomado estéreis todas as mulheres da casa de Abimelech, por causa de Sara, mulher de Abraão.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 1, 'Ora o Senhor visitou Sara, como tinha prometido, e cumpriu o que tinha dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 2, 'Ela concebeu e deu à luz um filho, na sua velhice, no tempo que Deus lhe predissera.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 3, 'Abraão pôs o nome de Isaac ao filho que nascera de Sara, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 4, 'e circuncidou-o ao oitavo dia, como Deus lhe tinha ordenado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 5, 'Tinha Abraão cem anos, quando lhe nasceu seu filho Isaac.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 6, 'E Sara disse: Deus me deu (um motivo de) riso, e todo aquele que ouvir (a nova) rirá juntamente comigo'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 7, 'E acrescentou; quem acreditaria que Abraão havia de ouvir dizer que Sara amamentaria um filho, que lhe havia de dar à luz, sendo ele já velho? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 8, 'Entretanto cresceu o menino e foi desmamado; no dia em que foi desmamado, deu Abraão um grande banquete.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 9, 'Sara, porém, tendo visto o filho de Agar egípcia, que escarnecia de seu filho Isaac, disse para Abraão: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 10, 'expulsa esta escrava e o seu filho, porque o filho da escrava não há-de ser herdeiro com meu filho Isaac.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 11, 'Este falar foi duro para Abraão por causa de seu filho (Ismael).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 12, 'Deus, porém, disse-lhe: não te pareça áspero tratar assim o menino e a tua escrava. Atende Sara em tudo o que ela te disser, porque de Isaac sairá a descendência que há-de ter o teu nome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 13, 'Mas também do filho da escrava farei um grande povo, por ser teu sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 14, 'Abraão, pois, levantou-se de manhã, tomou pão e um odre de água, pô-lo ás costas de Agar, entregou-lhe o menino e despediu-a. Ela, tendo partido, andava errando pelo deserto de Bersabeia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 15, 'Quando se acabou a água do odre, deixou o menino deitado debaixo duma das árvores, que ali havia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 16, 'afastou-se, e sentou-se defronte, à distância dum tiro de flecha, dizendo: não verei morrer o menino. Sentando-se em frente, levantou a sua voz e chorou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 17, 'Deus ouviu a voz do menino, e o anjo de Deus chamou Agar do céu, dizendo: que fazes, Agar? Não temas, porque Deus ouviu a voz do menino do lugar em que está.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 18, 'Levanta-te, toma o menino, tem-no pela mão, porque eu farei dele um grande povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 19, 'E Deus abriu-lhe os olhos, e ela, vendo um poço de água, foi a ele, encheu o odre e deu de beber ao menino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 20, 'E (Deus) foi com ele, que cresceu, habitou no deserto e que, depois de crescido, se tornou frecheiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 21, 'Habitou no deserto de Faran, e sua mãe tomou para ele uma mulher do pais do Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 22, 'Por aquele mesmo tempo, Abimelech, acompanhado de Ficol, general do seu exército, disse a Abraão: Deus é contigo em tudo o que fazes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 23, 'Portanto jura por Deus que me não farás mal, nem aos meus descendentes, nem à minha estirpe, mas que usarás comigo e com a terra onde tens vivido como estrangeiro, da mesma benevolência com que te tratei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 24, 'Abraão disse: eu o jurarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 25, 'Mas Abraão queixou-se a Abimelech por cousa dum poço de água, que os seus servos lhe tinham tirado à força.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 26, 'Abimelech respondeu: eu não soube quem fez tal coisa, nem tão pouco tu me informaste, e eu não ouvi falar (disso) senão hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 27, 'Tomou, pois, Abraão ovelhas e bois, deu-os a Abimelech e fizeram ambos aliança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 28, 'Abraão pôs à parte sete cordeiras do rebanho'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 29, 'e Abimelech perguntou-lhe: que querem dizer estas sete cordeiras, que puseste à parte?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 30, 'Ele respondeu: tu receberás estas sete cordeiras da minha mão, para que elas me sirvam de testemunho de como eu cavei este poço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 31, 'Por isso foi aquele lugar chamado Bersabeia, porque ali juraram ambos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 32, 'E (foi assim que) fizeram aliança junto do poço do juramento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 33, 'Abimelech levantou-se, com Ficol, general do seu exército, e voltaram para a terra dos filisteus. Abraão plantou uma tamargueira em Bersabeia, e aí invocou o nome do Senhor Deus eterno.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 34, 'E foi por longo tempo morador na terra dos filisteus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 1, 'Passado isto, quis Deus tentar a Abraão, e disse-lhe: Abraão, Abraão! Ele respondeu: aqui estou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 2, '(E Deus) disse-lhe: toma Isaac, teu filho único, a quem amas, vai ao país de Moriab, e aí o oferecerás em holocausto sobre um dos montes, que eu te mostrar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 3, 'Abraão, pois, levantando-se de noite, pôs a sela ao seu jumento, levando consigo dois jóvens (severos), e Isaac, seu filho; cortou a lenha para o holocausto e partiu para o lugar que Deus lhe tinha dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 4, 'Ao terceiro dia, levantando os olhos, viu o lugar de longe,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 5, 'e disse aos seus servos; esperai aqui com o jumento: eu e o menino vamos até acolá, e, depois de adorarmos, voltaremos a vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 6, 'Tomou também a lenha do holocausto, e pô-la sobre Isaac, seu filho: ele, porém, levava nas mãos o fogo e o cutelo. Enquanto ambos caminhavam juntos, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 7, 'disse Isaac a seu pai: meu pai. Ele respondeu: que queres, filho? Eis, disse (Isaac), o fogo e a lenha, (mas) onde está a vítima para o holocausto? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 8, 'Abraão respondeu: meu filho. Deus deparará a vítima para o seu holocausto. Caminhavam, pois, ambos juntos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 9, 'Chegaram (finalmente) ao lugar que Deus lhe tinha designado, no qual levantou um altar, e sobre ele preparou a lenha; tendo ligado Isaac seu filho, pô-lo no altar sobre o feixe da lenha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 10, 'Estendeu a mão e pegou no cutelo, para imolar seu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 11, 'Então o anjo do Senhor gritou do céu, dizendo: Abraão, Abraão. Ele respondeu: aqui estou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 12, 'E (o anjo) disse-lhe: não estendas a tua mão sobre o menino, nem lhe faças mal algum; agora conheci que temes a Deus e não perdoaste a teu filho único por amor de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 13, 'Abraão levantou os olhos e viu atrás de si um carneiro preso pelos chifres entre os espinhos, e, pegando nele, o ofereceu em holocausto, em lugar de seu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 14, 'Chamou àquele lugar o Senhor providência. Donde até ao dia de hoje se diz: o Senhor providenciará sobre o monte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 15, 'Segunda vez chamou o anjo do Senhor a Abraão do céu, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 16, 'por mim mesmo jurei, diz o Senhor, que, porque fizeste tal coisa e não perdoaste a teu filho único por amor de mim, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 17, 'eu te abençoarei e multiplicarei a tua estirpe como as estrelas do céu, e como a areia das praias: a tua descendência possuirá as portas de seus inimigos, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 18, 'e na tua descendência serão benditas todas as nações da terra, porque obedeceste à minha voz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 19, 'Abraão voltou para (onde estavam) os seus servos, e foram juntos a Bersabeia, e aí habitou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 20, 'Depois destas coisas, foi anunciado a Abraão que Melca também tinha dado à luz filhos a Nacor, irmão dele: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 21, 'Hus, o primogênito, Bus, seu irmão, Camuel, pai dos Siros, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 22, 'Cased, Azau, Feldas, Jedlaph,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 23, 'e Batuel, de quem nasceu Rebeca. Estes são os oito filhos que Melca deu à luz a Nacor, irmão de Abraão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 24, 'E sua mulher secundária, chamada Roma, deu à luz Tabee, Gaam, Taas e Maaca. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 1, 'Sara viveu cento e vinte e sete anos, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 2, 'e morreu na cidade de Arbeia, que é Hebron, na terra de Canaan. Abraão veio para a prantear e chorar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 3, 'Quando se levantou, depois de acabado o pranto fúnebre, falou aos filhos de Heth, dizendo: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 4, 'sou forasteiro e peregrino entre vós: dai-me o direito da sepultura entre vós, para eu sepultar a minha defunta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 5, 'Os filhos de Heth responderam, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 6, 'senhor, ouve-nos: tu és entre nós um príncipe de Deus: sepulta a tua defunta nas nossas mais belas sepulturas, que nenhum de nós te proibirá que a sepultes no seu túmulo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 7, 'Abraão levantou-se e inclinou-se diante do povo daquela terra, isto é, diante dos filhos de Heth, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 8, 'e disse-lhe: se é do vosso agrado que eu sepulte a minha defunta, ouvi-me e intercedei por mim junto de Efron, filho de Seor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 9, 'para que ele me ceda a dupla caverna, que tem na extremidade do seu campo; pelo seu justo preço me ceda diante de vós, para que eu seja seu dono, e dela faça um sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 10, 'Ora Efron estava (sentado) no meio dos filhos de Heth. Efron respondeu a Abraão, ouvindo-o todos os que entravam pela porta da cidade, assim:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 11, 'de nenhuma sorte, meu senhor, mas antes ouve o que digo: dou-te o campo e a caverna que nele há, em presença dos filhos do meu povo: Sepulta a tua defunta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 12, 'Abraão inclinou-se, outra vez, diante do povo daquela terra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 13, 'e disse a Efron, em presença da multidão: peço-te que me ouças: eu te darei o dinheiro pelo campo; recebe-o, e assim sepultarei nele a minha defunta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 14, 'Efron respondeu:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 15, 'meu Senhor, ouve-me: a terra, que tu pedes, vale quatrocentos siclos de prata: este é o (seu) preço entre mim e ti; mas que é isto? Sepulta a tua defunta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 16, 'Tendo ouvido isto, Abraão pesou na presença dos filhos de Heth o dinheiro que Efron tinha pedido, isto é, quatrocentos siclos de prata de boa moeda corrente '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 17, 'E o campo, outrora de Efron, no qual estava uma dupla caverna, que olhava para Mambré, tanto o campo como a caverna, e todas as árvores que estavam em redor dentro dos seus confins,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 18, 'tudo foi cedido em pleno domínio a Abraão, na presença dos filhos de Heth e de todos os que entravam pela porta daquela cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 19, 'Deste modo, Abraão sepultou Sara, sua mulher, na dupla caverna do campo que olha para Mambré, que é Hebron, na terra de Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 20, 'E foi confirmado a Abraão pelos filhos de Heth o domínio do campo e da caverna, que havia nele, para servir de sepulcro.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 1, 'Ora Abraão, já velho e de idade avançada, vendo que o Senhor em tudo o tinha abençoado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 2, 'disse ao servo mais antigo da sua casa, que governava tudo o que possuía: Põe a tua mão por baixo da minha coxa, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 3, 'para eu te fazer jurar pelo Senhor, Deus do céu e da terra, que não tomarás para mulher de meu filho (nenhuma) das filhas dos Cananeus, entre os quais habito, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 4, 'mas que irás à minha terra e aos meus parentes, e daí tomarás mulher para meu filho Isaac.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 5, 'Respondeu o Servo: Se a mulher não quiser vir comigo para esta terra, porventura devo eu reconduzir teu filho para o lugar donde saiste? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 6, 'Abraão disse: Guarda-te de reconduzir jámais para lá o meu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 7, 'O Senhor Deus do céu, que me tirou da casa de meu pai e da terra do meu nascimento, que me falou e me jurou dizendo: A tua estirpe darei esta terra — ele mandará o seu anjo diante de ti, e tomarás lá uma mulher para meu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 8, 'Porém, se a mulher não quiser seguir-te, não estarás obrigado ao juramento: sòmente não reconduzas para lá o meu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 9, 'Pôs, portanto, o Servo a mão debaixo da coxa de Abraão, seu Senhor, e jurou-lhe fazer o que lhe tinha sido dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 10, 'Tomou dez camelos do rebanho de seu senhor, e partiu, levando consigo de todos os seus bens; pôs-se a caminho, andando para a Mesopotâmia, para a cidade de Nacor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 11, 'E, tendo pela tarde feito descansar os camelos fora da cidade junto a um poço de água, na ocasião em que as mulheres costumam sair a tirar água, disse:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 12, 'Ó Senhor Deus do meu Senhor Abraão, rogo-te me auxilies hoje, e uses de misericórdia para com meu senhor Abraão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 13, 'Eis que estou ao pé desta fonte de água, e as filhas dos habitantes desta cidade sairão a vir tirar água:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 14, 'portanto a donzela a quem eu disser: Inclina o teu cântaro para eu beber — e ela responder: Bebe, e também darei de beber a teus camelos — essa é aquela que destinaste para teu servo Isaac: por isso conhecerei que usaste de misericórdia com o meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 15, 'Ainda não tinha acabado de dizer no seu interior estas palavras, quando Rebeca, filha de Batuel, filho de Melca. mulher de Nacor, irmão de Abraão, saía com um cântaro aos ombros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 16, 'Era uma donzela linda em extremo, virgem formosíssima não conhecida por homem algum: tinha descido à fonte, enchido o cântaro, e já voltava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 17, 'Mas o Servo saiu-lhe ao encontro e disse: Dá-me de beber um pouco de água do teu cântaro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 18, 'Ela respondeu: Bebe, meu senhor: e prontamente inclinou o cântaro sobre o seu braço, e lhe deu de beber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 19, 'Tendo ele bebido, ela acrescentou: Também para os teus camelos tirarei água, até que todos bebam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 20, 'Despejando o cântaro nas pias, correu de novo ao poço a tirar água, e, tirada, deu a todos os camelos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 21, 'Ora ele contemplava-a em silêncio, querendo saber se o Senhor teria ou não tornado feliz a sua viagem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 22, 'Depois que os camelos beberam, tirou um anel de ouro, de meio siclo de peso, e dois braceletes, que pesavam dez siclos, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 23, 'e perguntou-lhe: De quem és filha? Dize-me: Há em casa de teu pai lugar em que se fique?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 24, 'Ela respondeu: Sou filha de Batuel, filho de Melca, o qual ela deu à luz a Nacor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 25, 'E acrescentou: Em nossa casa há muita palha e feno, e lugar espaçoso para ficar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 26, 'Aquele homem inclinou-se, e adorou o Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 27, 'dizendo: Bendito o Senhor Deus do meu Senhor Abraão, que não retirou a sua misericórdia e a sua verdade do meu senhor, e me conduziu por um caminho direito à casa do irmão do meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 28, 'A donzela, pois, correu, e contou em casa de sua mãe tudo o que tinha ouvido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 29, 'Ora Rebeca tinha um irmão, chamado Labão, o qual, apressado, saiu a ir ter com aquele homem, onde estava a fonte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 30, 'Tendo visto as arrecadas e os braceletes nas mãos de sua irmã, e tendo ouvido todas as palavras que ela referia: Aquele homem disse-nos estas e estas coisas — foi ter com ele, que estava junto dos camelos e perto da fonte,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 31, 'e disse-lhe: Entra, bendito do Senhor; porque estás fora? Eu já preparei a casa (para ti), e um lugar para os camelos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 32, 'Introduziu-o, pois, na habitação, descarregou os camelos e deu-lhes palha e feno, e (trouxe) água para lavar os pés dele e dos homens que com ele tinham vindo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 33, 'Depois serviu-lhe de comer. Porém (o servo) disse: Não comerei enquanto não expuser o que tenho para dizer. (Labão) respondeu-lhe: Fala.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 34, 'Então ele disse: Sou servo de Abraão;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 35, 'o Senhor encheu de bênçãos o meu senhor e o engrandeceu, dando-lhe ovelhas e bois, prata e ouro, criados e criadas, camelos e jumentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 36, 'Sara, mulher do meu senhor, deu-lhe na sua velhice um filho, a quem ele deu tudo o que tinha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 37, 'O meu senhor fez-me jurar, dizendo: Não tomarás para meu filho mulher das filhas de Cananeus, em cuja terra habito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 38, 'mas irás a casa de meu pai e tomarás da minha parentela mulher para meu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 39, 'Respondi ao meu senhor: E se a mulher não quiser vir comigo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 40, 'O Senhor, me disse ele, em cuja presença ando, mandará o seu anjo contigo, dirigirá o teu caminho, e tomarás para meu filho uma mulher da minha parentela; e da casa de meu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 41, 'Serás isento da minha maldição, quando tiveres ido a casa dos meus parentes, e eles não ta derem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 42, 'Eu, pois, cheguei hoje à fonte, e disse: Ó Senhor Deus do meu senhor Abraão, se tu dirigiste o caminho em que eu agora vou,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 43, 'eis que estou ao pé (desta) fonte de água: se a donzela que sair para tirar água, e ouvir de mim: Dá-me de beber um pouco de água do teu cântaro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 44, 'me disser: Bebe, e eu tirarei também para os teus camelos — seja essa a mulher que o Senhor destinou para o filho do meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 45, 'Ora, enquanto eu considerava comigo em silêncio estas coisas, apareceu Rebeca, que vinha com o cântaro ao ombro, desceu à fonte e tirou água. Eu disse-lhe: Dá-me um pouco de beber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 46, 'Ela apressando-se, desceu o cântaro do ombro e disse-me: Bebe, e eu darei também de beber aos teus camelos. Bebi e ela deu (também) água aos camelos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 47, 'Interroguei-a: De quem és tu filha? Ela respondeu: Sou filha de Batuel, filho de Nacor e de Melca. Eu, então, coloquei-lhe o anel no nariz e pus-lhe nos pulsos os braceletes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 48, 'Depois, inclinado, adorei o Senhor, bendizendo o Senhor Deus do meu senhor Abraão, o qual me conduziu por um caminho direito, a fim de tomar para seu filho uma filha do irmão de meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 49, 'Por isso se usais de bondade e lealdade com o meu senhor, declarai-mo: se porém, outra coisa é do vosso agrado, dizei-mo também, para que eu vá para a direita ou para a esquerda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 50, 'Labão e Batuel responderam: Do Senhor saíram estas palavras, e nós não podemos dizer-te outra coisa fora da sua vontade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 51, 'Eis Rebeca na tua presença, toma-a e parte, e seja esposa do filho de teu senhor, conforme o Senhor falou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 52, 'O servo de Abraão, tendo ouvido isto, prostrando-se por terra, adorou o Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 53, 'e, tendo tirado vasos de prata e de ouro, e vestidos, deu-os a Rebeca de presente, e também ofereceu dádivas a seus irmãos e à mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 54, 'Preparado o banquete comeram e beberam, e ficaram ali (aquela noite). Levantando-se pela manhã, disse o servo: Deixas-me ir, para que vá ter com o meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 55, 'Mas os irmãos dela e a mãe responderam: Fique a donzela connosco ao menos dez dias, e depois partirá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 56, 'Não queirais, respondeu-lhes, demorar-me, porque o Senhor dirigiu o meu caminho: Deixas que eu vá para o meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 57, 'Eles disseram: Chamemos a donzela e saibamos qual é a sua vontade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 58, 'Chamaram-na. pois, e perguntaram-lhe: queres ir com este homem? Ela respondeu: Irei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 59, 'Deixaram-na, pois, partir juntamente com a sua ama de leite, e o servo de Abraão e seus companheiros,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 60, 'fazendo votos pelas prosperidades de sua irmã, dizendo: És nossa irmã, cresce em milhares de milhares, e a tua posteridade possua as portas de seus inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 61, 'Então Rebeca e suas criadas, montadas nos camelos, seguiram aquele homem, o qual a toda a pressa voltava para o seu Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 62, 'Ora, naquele tempo, Isaac passeava pelo caminho que conduz ao poço, chamado (poço) do que vive e do que vê, porque habitava no pais meridional.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 63, 'Tinha saído ao campo para meditar, ao cair da noite, e, levantando os olhos, viu ao longe vir os camelos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 64, 'Rebeca também, tendo visto Isaac desceu do camelo'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 65, 'e disse ao servo: Quem é aquele homem que vem pelo campo ao nosso encontro? Ele respondeu: É o meu senhor. Ela tomou depressa o véu e cobriu-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 66, 'O servo contou a Isaac tudo o que tinha feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 67, 'Ele introduziu-a na tenda de Sara, sua mãe, recebeu-a por mulher, e tão extremosamente a amou, que moderou a dor que lhe ocasionara a morte de sua mãe. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 1, 'Abraão, porém, tomou outra mulher chamada Cetura, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 2, 'a qual lhe deu à luz Zanram, Jecsan, Madan, Madian, Jesboc e Sué.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 3, 'Jecsan gerou Saba e Dadàn. Os filhos, de Dadan foram Assurim, Latussim e Laomin,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 4, 'De Madian nasceram Efa, Ofer, Henoch Abida e Eldas. Estes são todos os filhos de Cetura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 5, 'Abraão deu tudo o que possuía a Isaac;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 6, 'pelos filhos das mulheres secundárias distribuiu dádivas, mas separou-os de Isaac, seu filho, ainda em sua vida, (mandando-os) para as partes do oriente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 7, 'Ora os dias da vida de Abraão foram cento e setenta e cinco anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 8, 'Faltando-lhe as forças, morreu numa ditosa velhice, em avançada idade, cheio de dias, e foi unir-se ao seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 9, 'Isaac e Ismael, seus filhos, sepultaram-no na dupla caverna que está situada no campo de Efron, filho de Seor Heteu, defronte de Mambré, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 10, 'o qual (campo Abraão) tinha comprado aos filhos de Heth; aí foi sepultado com Sara, sua mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 11, 'E, depois da sua morte. Deus abençoou Isaac, seu filho, o qual habitava junto do poço chamado (poço) do que vive e do que vê.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 12, 'Descendência de Ismael.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 13, 'e estes são os nomes de seus filhos, segundo os seus nomes, e nas suas gerações. O primogênito de Ismael foi Nabajoth; depois (nasceram) Cedar, Abdeel, Mabsam, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 14, 'Masma, Duma, Massa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 15, 'Hadar, Temia, Jetur, Nafis e Cedma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 16, 'Estes são os filhos de Ismael, e estes os seus nomes segundo as suas aldeias e os seus acampamentos; eles foram os doze chefes das suas tribos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 17, 'Os anos da vida de Ismael foram Cento e trinta e sete. Faltando-lhe as forças, morreu e foi unir-se ao seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 18, 'Seus filhos habitaram desde Hevila até Sur, que olha para o Egito, caminhando para a Assíria, em frente de todos os seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 19, 'Esta é a descendência de Isaac, filho de Abraão: Abraão gerou Isaac,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 20, 'o qual, tendo quarenta anos, se casou com Rebeca, filha de Batuel Siro, da Mesopotâmia, irmã de Labão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 21, 'Isaac orou ao Senhor por sua mulher, porque ela era estéril, e ele o ouviu, e permitiu que Rebeca concebesse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 22, 'Mas as crianças lutavam no seu ventre, e ela disse: Se assim me havia de acontecer, que necessidade havia de que eu concebesse? Foi consultar o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 23, 'o qual lhe disse: Duas nações estão no teu ventre, dois povos (ao sair) do teu ventre se dividirão, e um povo vencerá o outro, e o mais velho servirá ao mais novo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 24, 'Quando chegou o tempo de dar à luz, foram achados dois gêmeos no seu ventre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 25, 'O que saiu primeiro era ruivo e tudo peludo, como uma peliça: e foi-lhe posto o nome de Esaú. Imediatamente saiu o outro, que agarrava com a mão o pé de Esaú, e por isso ela o chamou Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 26, 'Era Isaac sexagenário quando os meninos lhe nasceram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 27, 'Tendo crescido, Esaú tomou-se perito caçador e do campo: Jacob, homem simples, habitava nas tendas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 28, 'Isaac amava Esaú, porque comia das suas caçadas: Rebeca amava Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 29, 'Ora, tendo Jacob feito um cozinhado, chegou Esaú do campo, (muito) cansado, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 30, 'e disse (a Jacob): Dá-me desse cozinhado vermelho, porque estou muito cansado. Por esta razão lhe puseram o nome Edom, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 31, 'Jacob disse-lhe: Vende-me o teu direito de primogenitura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 32, 'Ele respondeu: Eis que vou morrer: de que me aproveitará o direito de primogenitura? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 33, 'Jacob disse: Jura-mo pois. Esaú jurou-lho e vendeu o direito de primogenitura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 34, 'E assim, recebido o pão e o cozinhado de lentilhas, comeu, bebeu e foi-se embora, dando-se-lhe pouco de ter vendido o seu direito de primogenitura.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 1, 'Sobrevindo, porém, uma fome naquela terra, depois da esterilidade que tinha havido nos dias de Abraão, Isaac foi ter com Abimelech, rei dos filisteus, a Gerara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 2, 'O Senhor apareceu-lhe e disse: Não vás ao Egito, mas fica na terra que eu te disser.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 3, 'Habita nela como estrangeiro: eu serei contigo e te abençoarei, porque darei a ti e à tua descendência todas estas regiões, cumprindo o juramento que fiz a Abraão, teu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 4, 'Multiplicarei a tua descendência como as estrelas do céu, e darei à tua posteridade todas estas regiões: nela serão abençoadas todas as nações da terra, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 5, 'porque Abraão obedeceu à minha voz, guardou os meus preceitos, os meus mandamentos, e observou as cerimônias e leis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 6, 'Isaac, pois, ficou em Gerara.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 7, 'Sendo interrogado pelos homens daquele país acerca de sua mulher, respondeu; É minha irmã: com efeito, tinha medo de confessar que estava unido com ela em matrimônio, suspeitando que o matariam por causa da sua beleza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 8, 'Tendo passado largo tempo, e habitando (sempre) no mesmo lugar, olhando Abimelech, rei dos filisteus, por uma janela, viu-o acariciando Rebeca, sua mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 9, 'Tendo-o chamado, disse-lhe: Está visto que ela é tua mulher; por que mentiste tu (dizendo) que é tua irmã? Respondeu: Tive medo que me matassem por sua causa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 10, 'Abimelech disse: Por que razão nos enganaste? Podia suceder que alguém do povo abusasse de tua mulher, e tu terias atraído sobre nós um grande pecado. Então deu esta ordem a todo o povo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 11, 'Quem quer que tocar a mulher deste homem será punido de morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 12, 'Isaac, pois, semeou naquela terra e recolheu no mesmo ano o cêntuplo. O Senhor o abençoou, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 13, 'e este homem tornou-se rico e foi crescendo em bens, até que se fez muito poderoso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 14, 'Teve rebanhos de ovelhas e manadas, e muitos servos. Por isto, tendo-lhe os filisteus inveja,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 15, 'entulharam-lhe naquele tempo todos os poços que os servos de seu pai Abraão tinham aberto, enchendo-os de terra:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 16, '(chegou a coisa a) tanto que o mesmo Abimelech disse a Isaac: Aparta-te de nós, porque te tornaste muito mais poderoso do que nós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 17, 'Ele apartou-se para o vale de Gerara e ai habitou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 18, 'De novo abriu aqueles poços, que os servos de seu pai Abraão tinham aberto, os quais, morto, ele, os filisteus tinham antecedentemente entulhado, e pôs-lhes os mesmos nomes, que já seu pai lhes tinha posto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 19, 'Cavavam na depressão e acharam água viva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 20, 'Também ai os pastores de Gerara contenderam com os pastores de Isaac, dizendo: A água é nossa. Por esta razão, em virtude do que havia acontecido, chamou àquele poço Contenda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 21, 'Abriram ainda outro poço: também, por causa dele, houve rixas, e o chamou Inimizade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 22, 'Partindo dali, abriu outro poço, pelo qual não contenderam, e por isso lhe pôs o nome de Largura, dizendo: Agora o Senhor nos pôs ao largo, e prosperaremos nesta terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 23, 'Daquele lugar subiu a Bersabeía, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 24, 'onde, na mesma noite, lhe apareceu o Senhor, dizendo: Eu sou o Deus de Abraão, teu pai: não temas, porque sou contigo; eu te abençoarei e multiplicarei a tua descendência por causa do meu servo Abraão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 25, 'Portanto levantou ai um altar, e, invocado o nome do Senhor, ergueu a sua tenda e ordenou aos seus servos que abrissem um poço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 26, 'Ora Abimelech, com Ocozath, seu amigo, e Ficol, general do seu exército, tendo ido de Gerara àquele lugar, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 27, 'disse-lhes Isaac: Por que viestes vós a mim, a um homem que odiastes, e expulsastes de vós?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 28, 'Eles responderam: Vimos que o Senhor é contigo, e por isso dissemos: Haja juramento entre nós e façamos aliança,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 29, 'de maneira que tu nos não faças mal algum, assim como também nós não temos tocado em nada do que é teu, nem fizemos coisa que te prejudicasse, mas te deixamos partir em paz, cheio da bênção do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 30, 'Deu-lhes (Isaac) um banquete, e, depois de terem comido e bebido,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 31, 'levantando-se pela manhã, juraram de parte a parte (a aliança). Depois Isaac os despediu e deixou ir em paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 32, 'Ora, no mesmo dia, vieram os servos de Isaac, dando-lhe a noticia do poço que tinham aberto, dizendo: Achamos água.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 33, 'Pelo que (Isaac) o chamou Abundância; à cidade foi posto o nome de Bersabeia, (que conserva) até ao dia de hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 34, 'Ora Esaú, tendo quarenta anos, tomou por mulheres Judith, filha de Beeri Heteu, e Bademath, filha de Elom do mesmo pais,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 35, 'ambas as quais amarguraram o ânimo de Isaac e de Rebeca. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 1, 'Ora Isaac envelheceu, a vista escureceu-se-lhe e não podia ver. Chamou Esaú, seu filho mais velho, e disse-lhe: Meu filho! Ele respondeu: Aqui estou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 2, 'O pai disse-lhe: Tu vês que estou velho e que ignoro o dia da minha morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 3, 'Toma as tuas armas, a aljava e o arco, e sai (ao campo); quando tiveres caçado alguma coisa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 4, 'faze-me um guisado como sabes que eu gosto, traze-mo para eu comer, e (para que) a minha alma te abençoe antes de eu expirar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 5, 'Rebeca ouviu isto, e, tendo Esaú ido para o campo para cumprir o mandato do pai,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 6, 'disse a seu filho Jacob: Ouvi teu pai falar com Esaú, teu irmão, e dizer-lhe:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 7, 'Traze-me da tua caça, e faze-me um guisado para eu comer e (para que) te abençoe na presença do Senhor antes de morrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 8, 'Agora, pois, meu filho, segue os meus conselhos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 9, 'Vai ao rebanho, traze-me os dois melhores cabritos, para que eu faça deles a teu pai (um daqueles) pratos, de que ele come com vontade, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 10, 'a fim de que, quando lho apresentares e ele tiver comido, te abençoe antes de morrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 11, 'Ele respondeu: Tu sabes que Esaú, meu irmão, é um homem peludo, e eu não;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 12, 'se meu pai me apalpar e me reconhecer, temo que ele julgue que eu o quis enganar, e que assim eu atraia sobre mim a maldição em lugar de bênção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 13, 'Sua mãe disse-lhe: Sobre mim caia essa maldição, meu filho: ouve somente a minha voz, e, partindo, traze o que eu disse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 14, 'Ele foi, trouxe (os cabritos) e deu-os a sua mãe. Ela preparou o guisado, como sabia ser do gosto do pai dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 15, 'Vestiu Jacob com a melhor roupa de Esaú, que tinha junto de si, em casa; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 16, 'com as peles dos cabritos envolveu-lhe as mãos, e cobriu a parte nua do pescoço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 17, 'Deu-lhe o guisado, e entregou-lhe os pães que tinha cozido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 18, 'Jacob, tendo levado tudo a Isaac, disse-lhe: Meu pai! Ele respondeu: Aqui estou. Quem és tu, meu filho?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 19, 'Jacob disse: Sou o teu filho primogênito, Esaú; fiz como me ordenaste: levanta-te, senta-te e come da minha caçada, afim de que tua alma me abençoe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 20, 'Isaac disse outra vez a seu filho: Como pudeste encontrar tão depressa, meu filho? Ele respondeu: Foi vontade de Deus que depressa se me apresentasse o que eu queria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 21, 'Isaac disse; Chega-te aqui, meu filho, para que eu te apalpe e reconheça se és o meu filho Esaú, ou não.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 22, 'Aproximou-se do pai que, tendo-o apalpado, disse: A voz verdadeiramente é a voz de Jacob, mas as mãos são as mãos de Esaú.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 23, 'E não o conheceu, porque as mãos peludas eram semelhantes às do mais velho. Portanto, abençoando-o,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 24, 'disse: Tu és o meu filho Esaú? Respondeu: Sou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 25, 'Isaac disse; Serve-me os guisados da tua caçada, meu filho, para que a minha alma te abençoe. Jacob serviu-lhos, e, depois de ele comer, ofereceu-lhe também vinho, bebido o qual,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 26, '(Isaac) lhe disse: Aproxima-te de mim e dá-mé um beijo, meu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 27, 'Aproximou-se e beijou-o. Logo que Isaac sentiu a fragrância de seus vestidos, abençoando-o, disse: Eis que o perfume de meu filho é como o perfume dum campo florido que o Senhor abençoou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 28, 'Deus te dê do orvalho do céu, da fertilidade da terra, e abundância de trigo e de vinho! '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 29, 'Que os povos te sirvam, e as nações te reverenciem; sê o senhor de teus irmãos, e inclinem-se diante de ti os filhos de tua mãe. Aquele que te amaldiçoar, Seja amaldiçoado, e o que te abençoar, seja cumulado de bênçãos '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 30, 'Apenas Isaac tinha acabado de dar a bênção, e Jacob tinha saído, chegou Esaú.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 31, 'Levou ao pai os guisados preparados da sua caçada, dizendo: Levanta-te, meu pai, e come da caça de teu filho, para que a tua alma me abençoe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 32, 'Isaac disse-lhe: Mas quem és tu? Ele respondeu: Sou o teu filho primogénito Esaú.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 33, 'Isaac, possuído de uma violenta emoção, disse: Quem é, pois, aquele que há pouco me trouxe a caça que apanhou? Comi de tudo antes que tu viesses. abençoei-o, e ele será bendito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 34, 'Esaú, ouvidas as palavras do pai, gritou com grande clamor, e, consternado, disse: Dá-me também a mim a bênção, meu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 35, 'Ele disse: O teu irmão veio fraudulentemente e recebeu a tua bênção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 36, 'Esaú prosseguiu: com razão lhe foi posto o nome de Jacob, porque pela segunda vez me suplantou: Primeiro, tirou-me o direito da primogenitura, e, agora, novamente me roubou a minha bênção. Disse de novo ao pai: Porventura não reservaste uma bênção também para mim? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 37, 'Isaac respondeu: Eu o constitui teu senhor, e sujeitei à sua servidão todos os seus irmãos: estabeleci-o na posse do trigo e do vinho; depois disto, meu filho, que te posso eu fazer? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 38, 'Esaú disse-lhe: Porventura ó pai, tens uma só bênção? Rogo-te que me abençoes também a mim. E, como rompesse num grande pranto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 39, 'Isaac, comovido, disse-lhe: Sem a abundância da terra, e sem o orvalho do alto do céu será a tua bênção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 40, 'Viverás da espada, e servirás a teu irmão; porém virá tempo em que sacudas e desates o seu jugo da tua cerviz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 41, 'Por isso Esaú odiou Jacob por causa da bênção com que o pai o abençoara, e disse no seu coração: Virão os dias do luto por meu pai, e eu matarei Jacob, meu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 42, 'Estas coisas foram referidas a Rebeca, a qual, mandando chamar seu filho Jacob, lhe disse: Eis que Esaú, teu irmão, ameaça que te há-de matar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 43, 'Agora, pois, meu filho, ouve a minha voz, e foge ligeiro para (casa de) Labão, meu irmão, em Haran;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 44, 'habitarás com ele algum tempo, até que se aplaque o furor do teu irmão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 45, 'cesse a sua cólera e se esqueça do que lhe fizeste: depois mandarei (lá alguém), e te farei conduzir de lá para aqui. Por que hei-de eu perder ambos os meus filhos num só dia? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 46, 'E Rebeca disse a Isaac: Estou desgostosa da vida por causa das filhas de Heth, se Jacob tomar mulher da linhagem desta terra, não quero mais viver. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 1, 'Portanto Isaac chamou Jacob, abençoou-o, e deu-lhe esta ordem: Não tomes mulher da geração de Canaan, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 2, 'mas parte, vai para a Mesopotâmia da Siria, para casa de Batuel, pai de tua mãe, e toma de lá esposa entre as filhas de Labão, teu tio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 3, 'Deus omnipotente te abençoe, te faça crescer e te multiplique, para que sejas pai duma multidão de povos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 4, 'Ele te dê a ti e à tua posteridade, depois de ti, as bênçãos de Abraão, para que possuas a terra onde vives como peregrino, a qual ele prometeu a teu avô.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 5, 'E, tendo-o Isaac despedido, Jacob partiu e dirigiu-se para a Mesopotâmia da Siria, para casa de Labão, filho de Batuel Siro, irmão de Rebeca, sua mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 6, 'Ora Esaú, vendo que seu pai tinha abençoado Jacob, e o tinha mandado para a Mesopotâmia da Síria, para lá tomar mulher; que, depois da bênção, lhe tinha dado esta ordem: não tomarás mulher das filhas de Canaan;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 7, 'que Jacob, obedecendo a seus pais, fora para a Síria;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 8, 'reconhecendo também que seu pai não via com bons olhos as filhas de Canaan,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 9, 'foi a casa de Ismael, e, além das que já tinha, tomou por mulher a Maeleth, filha de Ismael, filho de Abraão, irmã de Nabajoth.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 10, 'Jacob, pois, tendo partido de Bersabeia, ia para Haran.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 11, 'Tendo chegado a um certo lugar e querendo nele descansar porque o sol estava no ocaso, tomou uma das pedras que ali estavam, e, pondo-a debaixo da cabeça, dormiu naquele mesmo sitio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 12, 'Viu (então) em sonhos uma escada posta sobre a terra, cujo cimo tocava o céu, e os anjos de Deus subindo e descendo por ela, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 13, 'e o Senhor apoiado na escada, que lhe dizia: Eu sou o Senhor Deus de Abraão, teu pai e o Deus de Isaac: darei a ti e à tua descendência a terra em que dormes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 14, 'A tua posteridade será como o pó da terra; dilatar-te-ás para o ocidente, para o oriente, para o setentrião te para o meio-dia, e serão abençoadas em ti e na tua geração todas as tribos da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 15, 'Eu serei o teu protector, para onde quer que fores, e te reconduzirei a esta terra, e não te abandonarei sem cumprir tudo o que disse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 16, 'Tendo Jacob despertado do sono, disse: na verdade o Senhor está neste lugar, e eu não o sabia: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 17, 'e, cheio de pavor, acrescentou: quão terrível é este lugar! Não é aqui outra coisa senão a casa de Deus e a porta do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 18, 'Levantando-se, pois, Jacob, ao amanhecer, tirou a pedra, que tinha posto debaixo da cabeça e erigiu-a em padrão, derramando óleo sobre ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 19, 'E pôs o nome de Betel à cidade que antes se chamava Lusa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 20, 'Também fez voto, dizendo: Se Deus for comigo e me proteger na viagem que empreendi, se me der pão para comer, vestido para me cobrir '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 21, 'e teu voltar felizmente a casa de meu pai, o Senhor será meu Deus, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 22, 'e esta pedra, que erigi em padrão, será chamada casa de Deus: de todas as coisas que me deres, te oferecerei (ó Senhor) o dizimo. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 1, 'Tendo partido (daquele lugar), Jacob dirigiu-se para o pais do oriente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 2, 'Viu um poço no campo, e, repousando junto dele, três rebanhos de ovelhas, porque dele se dava de beber aos rebanhos. A sua boca estava tapada com uma grande pedra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 3, 'Era costume (só) tirarem a pedra depois de estarem reunidos todos os rebanhos, e, depois que eles tinham bebido, tornavam-na a colocar sobre a boca do poço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 4, '(Jacob) disse aos pastores: Irmãos, donde sois vós? Eles responderam: De Haran.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 5, 'Perguntou-lhes: Conheceis porventura Labão, filho de Nacor? Disseram: Conhecemos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 6, 'Está de saúde? perguntou ele. Está bom, responderam, e até aqui vem Raquel, sua filha, com o seu rebanho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 7, 'Jacob disse; Ainda é muito dia, e ainda não é tempo de se recolherem os rebanhos aos currais: dai primeiro de beber às ovelhas, e depois reconduzi-as ao pasto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 8, 'Eles responderam: Não o podemos fazer enquanto não estejam juntas todas as ovelhas, e não tiremos a pedra da boca do poço, para darmos de beber a todos os rebanhos (conjuntamente).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 9, 'Ainda eles estavam falando, quando Raquel chegava com as ovelhas de seu pai, porque ela pastoreava o rebanho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 10, 'Jacob, tendo-a visto e sabendo que era sua prima, e que as ovelhas eram de Labão, seu tio, tirou a pedra que tapava o poço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 11, 'Depois de ter dado de beber ao seu rebanho, beijou-a, e, levantando a voz, chorou, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 12, 'e declarou que era irmão de seu pai, e filho de Rebeca. Ela, correndo, foi noticiá-lo a seu pai, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 13, 'o qual, tendo ouvido que tinha chegado Jacob filho de sua irmã, correu ao seu encontro, abraçou-o, beijou-o muitas vezes e levou-o a sua casa. Ouvidos os motivos da sua viagem,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 14, 'respondeu: Tu és meu osso e minha carne. E, tendo passado Jacob um mês inteiro com Labão, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 15, 'disse-lhe este: Acaso, porque és meu irmão, me servirás de graça? Dize-me que paga queres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 16, 'Ora Labão tinha duas filhas: a mais velha chamava-se Lia, e a mais nova Raquel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 17, 'Lia, porém, tinha os olhos remelosos, enquanto que Raquel era formosa de rosto, e de gentil presença.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 18, 'Jacob, tendo-lhe amor, disse (a Labão); Eu te servirei sete anos por Raquel, tua filha mais nova.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 19, 'Labão respondeu: Melhor é que eu a dê a ti do que a outro homem; fica comigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 20, 'Jacob, pois, serviu sete anos por Raquel, e estes lhe pareceram poucos dias pela grandeza do amor (que lhe tinha).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 21, 'E disse a Labão: Dá-me a minha mulher, pois já está completo o tempo de eu a tomar por esposa, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 22, '(Labão) fez as bodas, tendo convidado para o banquete uma grande turba de amigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 23, 'À noite, levou sua filha Lia a Jacob, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 24, 'dando à filha uma escrava chamada Zelfa. Jacob, tendo ficado com ela segundo o costume, viu pela manhã que era Lia, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 25, 'e disse ao seu sogro: Que é isto que me quiseste fazer? Porventura não te servi eu por Raquel? Porque razão me enganaste?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 26, 'Labão respondeu: No nosso país não é costume casarem-se as mais novas primeiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 27, 'Acaba a semana destas núpcias e dar-te-ei também a outra pelo trabalho que me prestarás durante outros sete anos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 28, 'Acomodou-se (Jacob) à proposta, e, passada a semana, casou-se com Raquel, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 29, 'à qual o pai tinha dado a (sua) escrava Bala.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 30, 'E (Jacob), tendo enfim alcançado as núpcias desejadas, preferiu no seu amor a segunda à primeira, e continuou servindo Labão outros sete anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 31, 'Mas o Senhor, vendo que ele desprezava Lia, tornou-a fecunda, permanecendo estéril a irmã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 32, 'Lia concebeu e deu à luz um filho, e pôs-lhe o nome de Ruben, dizendo: O Senhor viu a minha humilhação, agora o meu marido me amará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 33, 'E concebeu novamente e deu à luz um filho, e disse: Porque o Senhor ouviu que eu era tratada com desprezo, me deu também este (filho); e pôs-lhe o nome de Simeão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 34, 'Concebeu terceira vez e deu à luz um outro filho, e disse: Agora se unirá (ainda mais) a mim o meu marido, porque lhe dei à luz três filhos; e por isso chamou a este Levi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 35, 'Concebeu quarta vez e deu à luz um filho, e disse: Agora louvarei o Senhor e por isso pôs-lhe o nome de Judá. E cessou de dar à luz. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 1, 'Ora Raquel, vendo-se infecunda, teve inveja da sua irmã e disse a seu marido: Dá-me filhos, senão morrerei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 2, 'Jacob, enfadado, respondeu-lhe: Acaso estou eu em lugar de Deus, que te privou do fruto do teu ventre? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 3, 'Ela disse: Tenho (minha) serva Bala: toma-a, para que ela dê à luz sobre os meus joelhos, e eu tenha filhos dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 4, 'E deu-lhe Bala por mulher, a qual, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 5, 'depois que Jacob a tomou, concebeu, e deu à luz um filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 6, 'Raquel disse: O Senhor julgou a meu favor, e ouviu a minha voz, dando-me um filho; por isso o chamou Dan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 7, 'Concebendo ela segunda vez, deu à luz outro filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 8, 'do qual Raquel disse: O Senhor me fez entrar em competência com minha irmã, e eu venci; e chamou-o Neftali, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 9, 'Lia, vendo que tinha cessado de ter filhos, deu a seu marido sua escrava Zelfa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 10, 'E, tendo ela concebido e dado à luz um filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 11, 'Lia disse: Em boa hora: por isto lhe pôs o nome de Gad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 12, 'Zelfa deu à luz ainda outro filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 13, 'Lia disse: Isto é por minha dita, porque as mulheres me chamarão ditosa: por isso o chalou Aser.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 14, 'Ora Ruben, tendo saído ao campo no tempo da ceifa do trigo, achou umas mandrágoras e levou-as a Lia, sua mãe. Raquel disse (a Lia): Dá-me parte das mandrágoras do teu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 15, 'Ela respondeu-lhe: Porventura parece-te pouco teres-me roubado o marido. Senão que também me queres levar as mandrágoras de meu filho? Raquel disse: (consinto que ele) durma esta noite contigo pelas mandrágoras de teu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 16, 'Quando Jacob à tarde voltava do campo, Lia saiu-lhe ao encontro e disse-lhe: Virás comigo, porque eu te tomei pelo preço das mandrágoras de meu filho. E (Jacob) dormiu aquela noite com ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 17, 'Deus ouviu os seus rogos, e ela concebeu deu à luz o quinto filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 18, 'e disse: Deus me deu o pago, dei a minha escrava ao meu marido; e pôs-lhe o nome de Issacar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 19, 'Concebendo novamente Lia, deu à luz o sexto filho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 20, 'e disse: Deus me dotou com um bom dote; meu marido estará comigo ainda esta vez, porque eu lhe dei seis filhos; por isso lhe pôs o nome de Zabulon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 21, 'Depois disto (Lia) deu à luz uma filha, chamada Dina.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 22, 'O Senhor lembrou-se também de Raquel, ouviu-a e tornou-a fecunda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 23, 'Concebeu e deu luz um filho, dizendo: Deus tirou o meu opróbrio;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 24, 'e pôs-lhe o nome de José, dizendo: o Senhor me dê ainda outro filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 25, 'Nascido, porém, José, disse Jacob a seu sogro: Deixa que eu volte para a (minha) pátria, para a minha terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 26, 'Dá-me as mulheres e os meus filhos, pelos quais eu tenho servido, para que eu me vá: tu sabes que serviços eu tenho prestado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 27, 'Labão disse-lhe; ache eu graça diante de teus olhos. Reconheci, por experiência, que Deus me abençoou por causa de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 28, 'Determina tu a recompensa que deverei dar-te.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 29, 'Mas ele respondeu: Tu sabes de que modo te servi, e quanto os teus bens aumentaram nas minhas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 30, 'Tinhas pouco, antes que eu viesse para ti, e agora tornaste-te rico; o Senhor te abençoou com a minha vinda. É, pois, justo que eu pense também agora (em estabelecer) a minha casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 31, 'Labão disse-lhe: Que te hei-de eu dar? Respondeu- lhe Jacob: Não quero nada (em dinheiro); mas, se fizeres o que vou pedir-te, continuarei a apascentar e a guardar os teus rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 32, 'Passarei, hoje, pelo meio de todos os teus rebanhos, e porei à parte todas as ovelhas negras ou de diversas cores e de pêlo malhado; tudo o que for negro, malhado e vário, tanto entre as ovelhas como entre as cabras, será a minha recompensa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 33, 'E amanhã me dará testemunho a minha justiça, quando chegar o tempo combinado entre nós; tudo o que não for de cores variegadas, malhado ou negro, tanto entre as ovelhas como entre as cabras, me arguirá de furto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 34, 'Labão disse: agrada-me o que pedes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 35, 'E, naquele dia, Labão separou as cabras, as ovelhas, os bodes e os carneiros variegados e manchados: e entregou nas mãos de seus filhos todo o rebanho que era duma só cor, isto é, de pêlo branco e negro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 36, 'E pôs a distância de três dias de jornada entre si e o genro, o qual apascentava o restante dos seus rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 37, 'Jacob, pois, tomando varas verdes de choupo e de amendoeira e de plátano, tirou-lhes parte da casca; tirada a casca, (nos lugares) onde as varas tinham sido descascadas, apareceu o branco; e onde tinham ficado intactas permaneceram verdes; e isto causou (nas varas) uma variedade de cores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 38, 'E pô-las nos canais, onde se lançava a água, para que, quando os rebanhos fossem beber, tivessem as varas diante dos olhos, e concebessem olhando para elas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 39, 'E aconteceu que, no mesmo calor do coito, as ovelhas olhavam para as varas, e davam à luz cordeiros manchados e variegados e pintados de diversas cores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 40, 'Jacob separou o seu gado, e pôs as varas nos canais diante dos olhos das cabras; tudo o que era branco ou negro pertencia a Labão, e o restante a Jacob, tendo os rebanhos separados entre si.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 41, 'Quando, pois, na primavera, as ovelhas deviam conceber, Jacob punha as varas nos canais da água diante dos olhos dos carneiros e das ovelhas, para que elas concebessem olhando para as varas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 42, 'Mas, quando as ovelhas concebiam no outono pela segunda vez, não punha as varas. Assim o que era concebido no outono, era para Labão, e o que era concebido na primavera, era para Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 43, 'Assim tornou-se extraordinàriamente rico, teve muitos rebanhos, escravas e escravos, camelos e jumentos.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 1, 'Ora, depois que Jacob ouviu as palavras dos filhos de Labão, que diziam: Levou Jacob tudo o que era de nosso pai, e, enriquecido de seus bens, se tornou poderoso, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 2, 'observou também que Labão lhe não mostrava a mesma cara que a principio: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 3, 'além disso, o Senhor dizia-lhe: Volta para a terra de teus pais, para a tua parentela, e eu serei contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 4, 'Mandou, pois, vir Raquel e Lia ao campo, onde ele apascentava os rebanhos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 5, 'e disse-lhes: Vejo que vosso pai não me mostra a mesma cara que a principio: porém o Deus de meu pai tem estado comigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 6, 'Vós mesmas sabeis como eu tenho servido vosso pai com todas as minhas forças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 7, 'Porém o vosso pai enganou-me, e mudou dez vezes a minha recompensa; nem por isso permitiu Deus que ele me fizesse algum dano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 8, 'Se ele uma vez dizia: Os cordeiros manchados serão a tua recompensa, todas as ovelhas davam à luz cordeiros manchados: quando, pelo contrário, dizia: Receberás por recompensa todos os cordeiros brancos, todas as ovelhas davam à luz cordeiros brancos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 9, 'Deus tirou a fazenda de vosso pai, e deu-ma a mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 10, 'Chegado o tempo em que as ovelhas haviam de conceber, levantei os meus olhos, e vi em sonhos que os machos, que cobriam as fêmeas, eram variegados e manchados, e de diversas cores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 11, 'E o anjo de Deus disse-me em sonhos: Jacob. Respondi: Aqui estou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 12, 'Ele disse: Levanta os teus olhos e vê que todos os machos, que cobrem as fêmeas, são variegados, manchados, e de diversas cores. Com efeito, vi tudo o que te fez Labão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 13, 'Eu sou o Deus de Betel, onde tu ungiste a pedra e me fizeste um voto. Agora, pois, levanta-te, e sai desta terra, voltando para a terra onde nasceste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 14, 'Raquel e Lia responderam: Porventura resta-nos alguma coisa dos bens e da herança da casa de nosso pai?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 15, 'Não nos tratou ele como estranhas, e vendeu e comeu o que nos era devido? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 16, 'Mas Deus tomou as riquezas de nosso pai e as entregou a nós e aos nossos filhos: faze, portanto, agora, tudo o que Deus te mandou,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 17, 'Levantou-se, pois, Jacob, e, fazendo montar sobre camelos os seus filhos e as suas mulheres, partiu,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 18, 'levando toda a sua fazenda e rebanhos, e tudo o que tinha adquirido na Mesopotâmia, e encaminhou-se para Isaac, seu pai, na terra de Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 19, 'Quando Labão foi fazer a tosquia das ovelhas, Raquel furtou os ídolos de seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 20, 'Jacob não quis participar a seu sogro a sua fugida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 21, 'Tendo, pois, partido com tudo o que lhe pertencia, e enquanto, passado já o rio, caminhava para a banda do monte de Galaad, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 22, 'foi Labão avisado ao terceiro dia de que Jacob ia fugindo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 23, 'Então ele, tendo tomado consigo seus irmãos, foi no seu encalço durante sete dias e apanhou-o no monte Galaad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 24, 'E viu em sonhos a Deus, que lhe dizia: Não digas nada a Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 25, 'Jacob já tinha assentado a sua tenda no monte: Labão, tendo-o alcançado com seus irmãos, pôs a sua tenda no mesmo monte de Galaad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 26, 'E disse a Jacob: Por que procedeste assim levando-me furtivamente minhas filhas como (se elas fossem) prisioneiras de guerra?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 27, 'Por que razão quiseste fugir sem que eu o soubesse, nem quiseste avisar-me, para que eu te acompanhasse com alegria e com cânticos, ao som de tímpanos e de citaras?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 28, 'Não me deixaste beijar meus filhos e minhas filhas: procedeste como um néscio. Agora certamente '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 29, 'estava na minha mão fazer-te mal; porém o Deus de teu pai disse-me ontem: Não digas nada a Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 30, 'Que desejasses voltar para os teus e te estimulasse o desejo da casa de teu pai, (compreender-se-ia); (mas) por que me furtaste os meus deuses?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 31, 'Jacob respondeu: Parti sem tu o saberes, porque tive medo que me tirasses à força as tuas filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 32, 'Porém quanto ao furto de que me acusas, qualquer que seja aquele, em cujo poder achares os teus deuses, seja morto em presença de nossos irmãos. Busca e leva tudo o que achares teu junto de mim. Dizendo isto ignorava que Raquel tivesse furtado os ídolos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 33, 'Labão, pois, tendo entrado na tenda de Jacob e de Lia, e das duas escravas, nada encontrou. Mas, tendo entrado na tenda de Raquel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 34, 'ela, muito à pressa escondeu os ídolos debaixo da sela dum camelo, e assentou-se em cima. Revistando ele toda a tenda sem achar nada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 35, 'disse ela: Não se agaste o meu senhor, se eu me não posso levantar na tua presença, porque presentemente me acho com a indisposição que costuma vir às mulheres. Deste modo foi iludida a ansiedade com que ele procurava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 36, 'Então Jacob, todo alterado, disse com enfado a Labão: Por que culpa minha, ou por que pecado meu correste atrás de mim com tanto calor, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 37, 'e revistaste todos os meus móveis? Que achaste tu aqui de todas as coisas da tua casa? Põe-nas aqui diante dos meus irmãos e dos teus irmãos, e sejam eles juízes entre mim e ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 38, '(Foi) por isto que eu estive vinte anos contigo? As tuas ovelhas e as tuas cabras não abortaram e eu não comi os carneiros do teu rebanho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 39, 'Não te ia levar o (animal) que era despedaçado pelas feras, mas pagava todo o dano. Tudo o que era roubado de mim o exigias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 40, 'Eu era, de dia e de noite, queimado do calor e do gelo, e o sono fugia dos meus olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 41, 'Deste modo te servi em tua casa vinte anos: catorze pelas (tuas) filhas, e seis, pelos teus rebanhos: tu mudaste também dez vezes a minha recompensa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 42, 'Se o Deus de meu pai Abraão, e (o Deus) que Isaac teme, me não tivesse assistido talvez me tivesses despedido nu: (mas) Deus olhou a minha aflição e o trabalho das minhas mãos, e te ameaçou ontem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 43, 'Labão respondeu-lhe: As minhas filhas, os filhos delas, os teus rebanhos e tudo o que vês, tudo é meu; que posso eu fazer contra minhas filhas e os meus netos? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 44, 'Vem, pois, e façamos, uma aliança, que sirva de testemunho entre mim e ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 45, 'Jacob tomou, pois, uma pedra, levantou-a por padrão '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 46, 'e disse aos seus irmãos: Trazei pedras. Tendo juntado muitas, fizeram (com elas) um cabeço e comeram sobre ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 47, 'Labão chamou-o Cabeço da testemunha, e Jacob Cabeço do testemunho, cada um segundo a propriedade da sua língua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 48, 'Labão disse: Este cabeço será hoje testemunha entre mim e ti, e, por isso, este cabeço se chamou Galaad, isto é, o Cabeço do testemunho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 49, 'O Senhor nos veja e nos julgue, quando nos tivermos separado um do outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 50, 'Se tu maltratares minhas filhas, e se tomares outras mulheres além delas, ninguém é testemunha dás nossas palavras. Senão Deus, que está presente (e que nos) vê.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 51, 'Disse mais a Jacob: Eis que o cabeço e a pedra, que eu levantei entre mim e ti, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 52, 'será testemunha: este cabeço bem como esta pedra dêem testemunho de que o não passarei, indo contra ti, nem tu o passarás com intento de me fazeres mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 53, 'O Deus de Abraão, o Deus de Nacor, o Deus de seus pais, seja juiz entre nós. Jurou, pois, Jacob por aquele que era temido por seu pai Isaac.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 54, 'E, imoladas as vitimas sobre o monte, convidou seus irmãos para comer pão. Tendo comido, ficaram ali (a passar a noite).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 55, 'Labão, porém, levantando-se antes de amanhecer, beijou os filhos e as filhas, abençoou-os e voltou para sua casa. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 1, 'Jacob prosseguiu o caminho que levava, e saíram-lhe ao encontro uns anjos de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 2, 'Tendo-os visto disse: Estes são os acampamentos de Deus; por isso, deu àquele lugar o nome de Maanaim, isto é, acampamentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 3, 'Jacob mandou mensageiros adiante de si a Esaú, seu irmão, à terra de Seir, na região de Edom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 4, 'e ordenou-lhes: Falai assim a Esaú, meu senhor; Jacob, teu irmão, disse isto: Morei com Labão como estrangeiro, e (com ele) estive até ao dia de hoje.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 5, 'Tenho bois, jumentos, ovelhas, servos e servas, e mando agora uma embaixada ao meu senhor, para achar graça diante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 6, 'Os mensageiros voltaram a Jacob e disseram: Fomos ter com teu irmão Esaú, e eis que vem a toda a pressa encontrar-se contigo com quatrocentos homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 7, 'Teve Jacob muito medo, e, assustado, dividiu o povo que estava com ele, assim como os rebanhos e as ovelhas, os bodes e os camelos em duas partidas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 8, 'dizendo: Se vier Esaú a uma partida, e a desbaratar, a outra partida, que resta, se salvará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 9, 'Disse Jacob: Ó Deus de meu pai Abraão, Deus de meu pai Isaac! Ó Senhor, que me disseste: Volta para a tua terra, para o lugar do teu nascimento e eu te beneficiarei — '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 10, 'eu sou indigno de todas as tuas misericórdias e da fidelidade que tiveste com o teu servo. Passei este (rio) Jordão só com o meu cajado e agora volto com duas partidas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 11, 'Livra-me das mãos de meu irmão Esaú, porque o temo muito, não suceda que chegando ele, mate a mãe com os filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 12, 'Tu disseste que me beneficiarias e dilatarias a minha descendência como a areia do mar, a qual, pela sua multidão, não se pode contar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 13, 'Tendo passado, pois, aquela noite naquele lugar, separou das coisas que tinha, presentes para seu irmão Esaú:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 14, 'duzentas cabras, vinte bodes, duzentas ovelhas, vinte carneiros,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 15, 'trinta camelas com suas crias, quarenta vacas, vinte touros, vinte jumentas e dez das suas crias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 16, 'E mandou pelas mãos dos seus servos cada um destes rebanhos separadamente, dizendo aos seus servos: Ide adiante de mim, e haja um intervalo entre rebanho e rebanho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 17, 'Ordenou ao primeiro, dizendo: Se te encontrares com meu irmão Esaú, e ele te perguntar: De quem és? ou, para onde vais? ou, de quem são estes animais que conduzes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 18, 'Responderás: São do teu servo Jacob, que os mandou de presente a meu senhor Esaú; ele mesmo vem atrás de nós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 19, 'As mesmas ordens deu ao segundo, ao terceiro e a todos os que conduziam os rebanhos, dizendo: Por estas mesmas palavras falai a Esaú, quando o encontrardes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 20, 'Acrescentareis: O mesmo teu servo Jacob vem também atrás de nós. Com efeito (Jacob) disse (consigo): eu o aplacarei com os presentes que vão diante, e depois o verei; talvez me será propicio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 21, 'Foram, portanto, os presentes adiante dele, e ele ficou naquela noite no acampamento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 22, 'Tendo-se levantado muito cedo, tomou as suas duas mulheres, e as duas escravas com os onze filhos, e passou o vau de Jaboc.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 23, 'Depois de passar tudo o que lhe pertencia, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 24, 'ficou ele só, e um homem lutou com ele até pela manhã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 25, 'Esse (homem) vendo que o não podia vencer, tocou a articulação da sua coxa, e logo esta se deslocou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 26, 'E disse (a Jacob): Largá-me, porque já vem vindo a aurora. (Jacob) respondeu: Não te largarei, se me não abençoares.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 27, 'Disse-lhe pois (aquele homem): Qual é o teu nome? Respondeu: Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 28, 'Porém ele disse: De nenhuma sorte te chamarás Jacob, mas Israel, porque lutaste contra Deus e com os homens e ficaste vitorioso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 29, 'Perguntou-lhe Jacob: Dize-me, como te chamas? Respondeu: Por que me perguntas o meu nome? E abençoou-o no mesmo lugar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 30, 'Jacob pôs àquele lugar o nome de Fanuel, dizendo: Vi a Deus face a face, e a minha alma foi salva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 31, 'E logo o sol lhe nasceu, depois que ultrapassou Fanuel: ele, porém, coxeava dum pé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 32, 'Por esta razão os filhos de Israel até ao dia de hoje não comem o nervo da articulação da coxa, porque o anjo tinha tocado Jacob nesse nervo. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 1, 'Jacob, levantando os seus olhos, viu Esaú que vinha, e com ele quatrocentos homens. Repartiu os filhos (pelos grupos de) Lia, de Raquel e de ambas as escravas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 2, 'e pôs as duas escravas com os seus filhos na frente; em segundo lugar, Lia e os seus filhos; e em último Raquel e José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 3, 'Ele, adiantando-se, prostrou-se sete vezes por terra, até seu irmão se aproximar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 4, 'Então, correndo Esaú ao encontro de seu irmão, o abraçou, e, apertando-lhe o pescoço e beijando-o, chorou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 5, 'Em seguida, levantando os olhos, viu as mulheres e os seus filhos, e disse: Quem são estes? Porventura pertencem-te? Respondeu: São os filhos que Deus me deu a mim, teu servo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 6, 'Aproximando-se às escravas e os seus filhos, inclinaram-se profundamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 7, 'Chegou também Lia com seus filhos, que se inclinaram do mesmo modo; em último lugar se inclinaram José e Raquel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 8, 'Esaú disse: Que significam estas partidas que encontrei? Respondeu: (Enviei-as) para achar graça diante do meu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 9, 'Esaú, porém, disse: Tenho muitos bens, meu irmão, guarda para ti o que é teu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 10, 'Jacob disse: Não procedas assim, te peço, mas, se achei graça diante de teus olhos, recebe das minhas mãos esta pequena dádiva, porque eu vi a tua face, como se visse o rosto de Deus: sê-me propício, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 11, 'e aceita a bênção que eu te trouxe e que Deus me deu, o qual dá todas as coisas. Forçado pelo irmão, Esaú aceitou com dificuldade '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 12, 'e disse: Caminhemos juntamente, e eu serei companheiro na tua viagem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 13, 'Jacob respondeu: Tu vês. meu senhor, que tenho comigo meninos tenros, ovelhas e vacas prenhes: se eu as cansar, fazendo-as andar mais, morrerão num dia todos os rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 14, 'Vá o meu senhor adiante do seu servo: eu seguirei pouco a pouco os seus passos, como vir que os meus meninos podem, até chegar à casa de meu Senhor em Seir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 15, 'Esaú respondeu: Peço-te que, do povo que está comigo, fique ao menos quem te acompanhe na viagem. Jacob respondeu: Não é necessário: de uma única coisa necessito, meu senhor, que é achar graça em tua presença.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 16, 'Voltou, portanto, Esaú naquele dia para Seir pelo caminho por onde tinha vindo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 17, 'Jacob foi para Socoth, onde, tendo edificado uma casa, e levantado as tendas, pôs àquele lugar o nome de Socoth isto é, tendas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 18, 'E depois que voltou da Mesopotâmia da Síria, passou para Salém, cidade dos Siquimitas, a qual está na terra de Canaan, e habitou junto da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 19, 'Comprou parte do campo, onde tinha levantado as tendas, aos filhos de Hemor, pai de Siquem, por cem cordeiros '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 20, 'e, tendo levantado ai um altar, invocou sobre ele o Deus fortíssimo de Israel. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 1, 'Ora Dina, filha de Lia, saiu para ver as mulheres daquele país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 2, 'Tendo-a visto Siquem, filho de Hemor Heveu, príncipe daquela terra, enamorou-se dela, raptou-a e dormiu com ela, desflorando à força a virgem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 3, 'A sua alma se prendeu a ela, e, vendo-a triste, a acariciou com meiguices.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 4, 'E, indo ter com seu pai Hemor, disse: Toma esta donzela para minha mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 5, 'Jacob, tendo ouvido isto enquanto os filhos estavam ausentes e ocupados em apascentar os gados, não disse nada enquanto não voltaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 6, 'Mas, tendo Hemor, pai de Siquem, ido falar a Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 7, 'os filhos deste vinham do campo, e, tendo sabido o que acontecera, iraram-se muito, porque (Siquem) tinha feito uma ação vergonhosa contra Israel, violando a filha de Jacob, coisa que se não devia fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 8, 'Hemor falou-lhes assim: A alma de meu filho Siquem afeiçoou-se fortemente à vossa filha: dai-lha por mulher,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 9, 'e façamos matrimônios reciprocamente: dai-nos as vossas filhas, recebei as nossas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 10, 'e habitai connosco: a terra está ao vosso dispor, cultivai, negociai, e adquiri possessões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 11, 'Siquem também disse ao pai e aos irmãos dela: Ache eu graça diante de vós, e darei tudo o que determinardes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 12, 'Aumentai o dote, pedi dádivas, e eu, de boa vontade, darei o que pedirdes: sòmente me dai esta donzela por mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 13, 'Os filhos de Jacob, enfurecidos por causa do estupro da irmã, responderam dolosamente a Siquem e a seu pai: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 14, 'Não podemos fazer o que pedis, nem dar nossa irmã a um homem incircuncidado, porque isto é ilícito e abominável entre nós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 15, 'Mas poderemos fazer aliança, se quiserdes ser semelhantes a nós, e se entre vós se circuncidar todo o individuo do sexo masculino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 16, 'Então daremos as nossas filhas e receberemos reciprocamente as vossas; habitaremos convosco e seremos um só povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 17, 'Se, porém, não quiserdes circuncidar-vos, levaremos nossa filha e nos retiraremos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 18, 'O seu oferecimento agradou a Hemor e a Siquem, seu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 19, 'O jovem não demorou em executar logo o que lhe era exigido, porque amava extremamente a donzela, e ele mesmo era muito respeitado em toda a casa de seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 20, 'Tendo Hemor e Siquem entrado a porta da cidade, disseram ao povo: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 21, 'Estes homens são pacíficos e querem habitar connosco; negociem nesta terra e cultivem-na; sendo ela espaçosa e vasta, necessita de cultivadores: receberemos por mulheres as suas filhas, e dar-lhes-emos as nossas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 22, 'Uma só coisa faz dilatar tanto bem: é o circuncidarmos os nossos varões imitando o rito deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 23, 'Com isto, a sua riqueza, gados e tudo o que possuem será nosso: sòmente acedamos (ao seu desejo) e, habitando juntamente, formaremos um só povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 24, 'Assentiram todos, sendo circuncidados todos os vairões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 25, 'Ao terceiro dia, quando a dor das feridas é mais violenta, os dois filhos de Jacob, Simeão e Levi, irmãos de Dina, empunhadas as espadas, entraram resolutamente na cidade, e, mortos todos os varões,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 26, 'trucidaram igualmente Hemor e Siquem, tirando sua irmã Dina da casa de Siquem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 27, 'Tendo estes saído, os outros filhos de Jacob caíram impetuosamente sobre os mortos, e saquearam a cidade, por haver sido desonrada a irmã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 28, 'Tomaram as ovelhas, os rebanhos, os jumentos, devastaram tudo o que havia nas casas e nos campos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 29, 'e levaram cativos os (seus) filhos e (as suas) mulheres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 30, 'Praticado isto com tanta audácia, disse Jacob a Simeão e Levi: Vós me afligistes e me tornastes odioso aos Cananeus e aos Fereseus, habitantes deste país. Somos poucos. Eles, congregados, me acometerão, e serei destruído eu e a minha casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 31, 'Eles responderam: Porventura deviam eles abusar da nossa irmã, como uma prostituta? ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 1, 'Entretanto disse Deus a Jacob: Levanta-te, vai para Betel, fica aí e erige um altar ao Deus que te apareceu quando fugias de Esaú, teu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 2, 'Jacob, convocada toda a sua família, disse: Lançai fora os deuses estranhos que estão no meio de vós, purificai-vos e mudai os vossos vestidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 3, 'Levantai-vos e subamos para Betel, para erigirmos aí um altar a Deus, que me ouviu no dia da minha tribulação, e me acompanhou na minha jornada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 4, 'Deram-lhe, pois, todos os deuses estranhos que tinham, e as arrecadas que tinham nas orelhas, e ele enterrou estas coisas debaixo de um terebinto, que está por detrás da cidade de Siquem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 5, 'Tendo estes partido, o terror de Deus invadiu todas as cidades circunvizinhas, e não se atreveram a perseguir os que se retiravam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 6, 'Chegou, portanto Jacob, com toda a sua gente, a Luza, por apelido Betel, a qual está (situada) na terra de Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 7, 'Edificou ai um altar, e pôs àquele lugar o nome de casa de Deus, porque ali lhe apareceu Deus, quando fugia de seu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 8, 'No mesmo tempo morreu Débora, ama de Rebeca: foi ali sepultada debaixo de um carvalho ao pé de Betel, e aquele lugar foi chamado o Carvalho do pranto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 9, 'E Deus apareceu novamente a Jacob, depois que voltou da Mesopotâmia da Síria, e o abençoou'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 10, 'dizendo: Não te chamarás mais Jacob, mas teu nome será Israel. E chamou-O Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 11, 'Disse-lhe: Eu sou o Deus omnipotente: cresce e multiplica-te; nações e multidão de povos nascerão de ti, de ti procederão reis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 12, 'Dar-te-ei a ti e à tua posteridade, depois de ti, a terra que dei a Abraão e a Isaac.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 13, 'Deus afastou-se do lugar em que lhe tinha falado e'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 14, 'ai levantou Jacob um padrão de pedra, fazendo sobre ele libações e derramando óleo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 15, 'À esse lugar pôs o nome de Betel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 16, 'Partindo dali, chegou, no tempo da primavera, a um lugar junto da estrada que conduz a Efrata, onde Raquel, tendo as dores do parto, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 17, 'e sendo o parto difícil começou a estar em perigo (de vida). Disse-lhe a parteira: Não temas, porque ainda terás este filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 18, 'Estando prestes a render o espirito, sob a violência da dor, estando iminente a morte, pôs ao seu filho o nome de Benoni, isto é, filho da minha dor: o pai porém, chamou-o Benjamim, isto é, filho da mão direita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 19, 'Raquel morreu e foi sepultada na estrada que conduz a Efrata, a qual é Belém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 20, 'Jacob levantou um monumento sobre o seu sepulcro: este é o monumento do sepulcro de Raquel, que ainda hoje existe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 21, 'Saindo dali, levantou a sua tenda da outra parte da Torre do rebanho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 22, 'Enquanto habitava naquela região foi Ruben e dormiu com Bala, mulher secundária de seu pai, e este veio a sabê-lo. Os filhos de Jacob eram doze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 23, 'Filhos de Lia: Ruben, o primogênito, Simeão, Levi, Judá, Issacar e Zabulon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 24, 'Filhos de Raquel: José e Benjamim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 25, 'Filhos de Bala, escrava de Raquel: Dan e Neftali.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 26, 'Filhos de Zelfa, escrava de Lia: Gad e Aser. Estes são os filhos de Jacob, que lhe nasceram na Mesopotâmia da Síria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 27, 'Jacob foi depois ter com seu pai Isaac a Mambré, à cidade de Arbeia, que é Hebron, na qual Abraão e Isaac viveram como peregrinos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 28, 'Todos os dias de Isaac foram cento e oitenta anos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 29, 'exausto (de forças) pela idade, morreu, e uniu-se ao seu povo, velho e cheio de dias. Esaú e Jacob, seus filhos, sepultaram-no. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 1, 'Esta é a descendência de Esaú chamado tambem Edom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 2, 'Esaú tomou (as suas) mulheres entre as filhas de Canaan: Ada, filha de Elon Heteu, e Oolibama, filha de Ana, filha de Sebeon Heveu: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 3, '(tomou) também Basemath, filha de Ismael, irmã de Nabajoth.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 4, 'Ada deu à luz Elifás; Basemath gerou Rauel; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 5, 'Oolibama gerou Jeus, Jelon e Coré. Estes são os filhos de Esaú, que lhe nasceram na terra de Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 6, 'Depois Esaú tomou suas mulheres, filhos e filhas, toda a gente da sua casa, rebanhos e gados, e tudo o que tinha na terra de Canaan, e foi para outro país, e apartou-se do seu irmão Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 7, 'Com efeito, eram muito ricos e não podiam habitar juntamente, nem os podia sustentar a terra em que eram peregrinos, por causa da multidão dos rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 8, 'Esaú, por outro nome Edom, habitou sobre o monte de Seir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 9, 'Estes são os descendentes de Esaú, pai dos Idumeus, no monte Seir, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 10, 'estes os nomes de seus filhos: Elifás, filho de Ada, mulher de Esaú; Rauel, filho de Basemath, mulher de Esaú.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 11, 'Os filhos de Elifás foram: Teman, Omar, Sefo, Catam e Cenez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 12, 'Tamna era mulher secundária de Efifás, filho de Esaú, e ela deu-lhe à luz Amalech. Estes são os filhos de Ada, mulher de Esaú.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 13, 'Os filhos de Rauel foram: Nabath, Zara, Sama e Meza. Estes foram os filhos de Basemath, mulher de Esaú.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 14, 'Os filhos de Oolibama, filha de Ana, filha de Sebeon, mulher de Esaú, foram: Jeus, Jelon e Coré.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 15, 'Estes são os chefes (das tribos oriundas) dos filhos de Esaú: filhos de Elifás, primogénito de Esaú, foram o chefe Teman, o chefe Omar, o chefe Sefo, o chefe Cenez, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 16, 'o chefe Coré, o chefe Gatem, o chefe Amalech. Estes (são) os filhos de Elifás, na terra de Edom, e estes os filhos de Ada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 17, 'Estes (são) os filhos de Rauel, filho de Esaú: o chefe Naath, o chefe Zara, o chefe Sama, o chefe Meza; estes (são) os chefes (descendentes) de Rauel, na terra de Edom; estes (são) os filhos de Basemath, mulher de Esaú.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 18, 'E estes são os filhos de Oolibama, mulher de Esaú: o chefe Jeus, o chefe Jelon, o chefe Coré; estes os chefes que procederam de Oolibama, filha de Ana, mulher de Esaú.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 19, 'Estes são os filhos de Esaú, isto é, de Edom; e estes os seus chefes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 20, 'Estes são os filhas de Seir Horreu, que habitavam aquela terra: Lotan, Sobal, Sebeon, Ana, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 21, 'Dison, Eser e Disan; estes os chefes Horreus, filhos de Seir, na terra de Edom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 22, 'Os filhos de Lotan foram: Hori e Hemon. Tamna era irmã de Lotan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 23, 'Estes (foram) os filhos de Sobal: Alvau, Manaath, Ebal, Sefo e Onam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 24, 'E estes os filhos de Sebeon: Aía e Ana. Este Ana é o que achou umas águas quentes no deserto, enquanto apascentava os jumentos de seu pai Sebeon: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 25, 'teve um filho (chamado) Dison, e uma filha (chamada) Oolibama.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 26, 'E estes (são) os filhos de Dison: Hamdan, Eseban, Jetrão e Charão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 27, 'Do mesmo modo estes (são) os filhos de Eser: Balaão, Zavan e Acan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 28, 'Disan teve estes filhos: Hus e Arão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 29, 'Estes são os chefes dos Hoireus: o chefe Lotan, o chefe Sobal, o chefe Sebeon, o chefe Ana, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 30, 'o chefe Dison, o chefe Eser, o chefe Disan; estes os chefes dos Horreus, que governaram na terra de Seir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 31, 'Os reis, porém, que reinaram na terra de Edom, antes que os filhos de Israel tivessem rei, foram estes: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 32, 'Bela, filho de Beor, reinou em Edom, e o nome da sua cidade (foi) Denaba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 33, 'Morreu, porém, Bela, e reinou em seu lugar Jobab, filho de Zara de Bosra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 34, 'Tendo falecido Jobab, reinou em seu lugar Husão, da terra dos Temanitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 35, 'Morto também este, reinou em seu lugar Adad, filho de Badad, o qual derrotou os Madianitas no país de Moab; o nome da sua cidade era Avith.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 36, 'Tendo falecido Adad, reinou em seu lugar Semla de Masreca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 37, 'Morto este também, reinou em seu lugar Saul, de Rooboth, que está perto do rio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 38, 'Tendo este também falecido, sucedeu no reino Balanan, filho de Acobor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 39, 'Morto também este, reinou em seu lugar Adar: o nome da sua cidade era Fau, e sua mulher chamava-se Meetabel, filha de Matred, (que era) filha de Mezaab.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 40, 'Estes são, pois, os nomes dos chefes que procederam de Esaú, segundo suas estirpes, seus lugares e seus nomes: o chefe Tamna, o chefe Alva, o chefe Jeteth, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 41, 'o chefe Oolibama, o chefe Ela, o chefe Fincai,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 42, 'o chefe Cenez, o chefe Teman, o chefe Malsa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 43, 'o chefe Magdiel, o chefe Hirão. Estes (são) os chefes de Edom (isto é, de Esaú, pai dois Idumeus) segundo a residência dos mesmos, na terra que ocupavam. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 1, 'Habitou, pois Jacob na terra de Canaan, na qual seu pai tinha vivido como peregrino '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 2, 'Esta é a sua posteridade: Quando José, ainda jovem, tendo dezasseis anos, apascentava o rebanho com seus irmãos, filhos de Bala e de Zelfa, mulheres de seu pai, fez saber a seu pai a péssima fama deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 3, 'Ora Israel amava José mais que todos os seus (outros) filhos, porque o gerara na velhice, e fez-lhe uma túnica de várias cores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 4, 'Vendo, pois, seus irmãos que de era amado pelo pai mais que todos os (outros) filhos, odiavam-no, e não lhe podiam falar com bom modo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 5, 'Sucedeu também que ele referiu a seus irmãos um sonho que tivera, o que foi causa de maior ódio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 6, 'Disse-lhes: Ouvi o sonho que eu tive:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 7, 'parecia-me que atávamos no campo os feixes, e que o meu feixe como que se erguia, ficava de pé, e que os vossos, estando em roda, se prostravam diante do meu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 8, 'Responderam seus irmãos: Porventura serás nosso rei ou seremos sujeitos ao teu domínio? Estes sonhos e estas conversas acenderam mais a inveja e o ódio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 9, 'Teve ainda outro sonho, o qual referiu a seus irmãos: Vi em sonhos que o sol, a lua onze estrelas como que me adoravam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 10, 'Ora, tendo ele contado isto a seu pai e aos irmãos, seu pai repreendeu-o e disse: Que quer dizer este sonho, que tiveste? Porventura eu, tua mãe, e teus irmãos te adoraremos, prostrados por terra? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 11, 'Seus irmãos, por isto, tinham-lhe inveja; porem o pai meditava a coisa em silêncio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 12, 'Como seus irmãos estivessem em Siquem apascentando os rebanhos do pai, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 13, 'Israel disse-lhe: Teus irmãos apascentam as ovelhas em Siquem: vem, enviar-te-ei a eles. Respondeu (José): '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 14, 'Estou pronto. (Jacob) disse-lhe: Vai, vê se tudo corre bem a teus irmãos e aos rebanhos, e traze-me noticias do que se passa. (Sendo) mandado do vale de Hebron, (José) chegou a Siquem, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 15, 'e, andando errante pelo campo, um homem encontrou-o e perguntou-Ihe o que procurava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 16, 'Ele respondeu: Procuro meus irmãos; indica-me onde apascentam os rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 17, 'O homem disse-lhe: Retiraram-se deste lugar, e ouvi-lhes dizer: Vamos para Dotain. Partiu, pois, José atrás de seus irmãos e encontrou-os em Dotain.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 18, 'Eles, porém, tendo-o visto ao longe, antes que se aproximasse, resolveram matá-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 19, 'Diziam entre si: Eis ai vem o sonhador; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 20, 'vinde, matemo-lo, lancemo-lo em uma cisterna velha, diremos: Uma fera cruel o devorou; então se verá de que lhe aproveitam os seus sonhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 21, 'Ruben, porém, ouvindo isto, esforçava-se por o livrar das suas mãos, dizendo: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 22, 'Não lhe tireis a vida, nem lhe derrameis o sangue, mas lançai-o nesta cisterna, que está no deserto, e conservai puras as vossas mãos. Diria isto porque queria livrá-lo das suas mãos e restitui-lo a seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 23, 'Logo que (José) chegou junto de seus irmãos, despiram-no da túnica talar de várias cores'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 24, 'e lançaram-no na cisterna velha, que não tinha água.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 25, 'Depois, sentando-se para comer pão, viram uns viajantes Ismaelitas, que vinham de Galaad, com seus camelos carregados de aromas, resina e mirra, para o Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 26, 'Judá então disse a seus irmãos: de que nos aproveita matar o nosso irmão e ocultar a sua morte?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 27, 'É melhor que se venda aos Ismaelitas, e que se não manchem as nossas mãos, porque é nosso irmão, é nossa carne. Concordaram os irmãos com o que ele diria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 28, 'Quando passaram os negociantes Madianitas, tiraram-no da cisterna e venderam-no por vinte dinheiros de prata aos Ismaelitas: estes levaram-no para o Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 29, 'Tendo voltado Ruben à cisterna não encontrou José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 30, 'Rasgadas as suas vestes, foi ter com seus irmãos-e disse: O rapaz não aparece, e eu para onde irei? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 31, 'Tomaram então a sua túnica, tingiram-na no sangue de um cabrito, que mataram,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 32, 'mandaram-na levar ao pai, e dizer-lhe: Encontrámos esta túnica: vê se é a túnica de teu filho, ou não.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 33, 'O pai, tendo-a reconhecido, disse: A túnica é de meu filho, uma cruel fera o comeu, uma besta devorou José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 34, 'Rasgadas as suas vestes, cobriu-se de cilício, chorando seu filho por muito tempo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 35, 'E, tendo-se juntado todos os seus filhos para suavizarem a dor do pai, ele não quis admitir consolação, mas disse: Chorando, descerei até junto de meu filho, à morada dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 36, 'Enquanto ele perseverava no pranto, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 37, 'os Madianitas venderam José no Egito a Putifar, eunuco de Faraó, general dos exércitos.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 1, 'No mesmo tempo, apartando-se Judá de seus irmãos, foi ter a casa de um homem odolamita, chamado Hirão, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 2, 'e viu ali a filha de um homem cananeu, chamado Sue, recebeu-a por mulher e viveu com ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 3, 'Ela concebeu e deu à luz um filho, a que pôs o nome de Her.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 4, 'Concebendo outra vez, pôs ao filho nascido o nome de Onan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 5, 'Deu à luz ainda um terceiro filho, a quem chamou Sela. Nascido este, cessou de dar à luz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 6, 'Judá deu uma mulher, chamada Tamar, ao seu primogênito Her.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 7, 'Her, primogênito de Judá, foi um homem mau, na presença do Senhor, e (o Senhor) o fez morrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 8, 'Disse, pois, Judá a Onan, seu filho: Desposa a mulher de teu irmão, vive com ela, para suscitares descendência a teu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 9, 'Ele, porém, sabendo que os filhos que nascessem não seriam seus, quando se juntava com a mulher de seu irmão, impedia que ela concebesse a fim de que não nascessem filhos em nome de seu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 10, 'Por isso, o Senhor o feriu de morte, porque fazia uma coisa detestável.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 11, 'Pelo que Judá disse a Tamar, sua nora: Conserva-te viúva em casa de teu pai até que cresça Sela, meu filho. Com efeito, temia que ele também morresse, como seus irmãos. Ela retirou-se e habitou em casa de seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 12, 'Passados muitos dias, morreu a filha de Sue, mulher de Judá, o qual, depois de a ter chorado, e terminado o luto, foi a Tamnas ter com os tosquiadores das suas ovelhas, juntamente com Hiras odolamita, pastor dos rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 13, 'Noticiaram a Tamar que seu sogro ia a Tamnas para tosquiar as ovelhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 14, 'Então ela, depondo os vestidos de viúva, tomou um véu e, disfarçada, sentou-se na encruzilhada do caminho, que conduz a Tamnas, porque (via que) Sela tinha crescido, e (o pai dele) não lho tinha dado por marido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 15, 'Judá, tendo-a visto, julgou que era meretriz, porque tinha coberto o seu rosto para não ser reconhecida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 16, 'Chegando-se a ela, disse: Deixa que me junte contigo. De facto ignorava que fosse sua nora. Ela disse: Que me darás por isso?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 17, 'Ele respondeu: Mandar-te-ei um cabrito dos (meus) rebanhos. Ela replicou: Consentirei no que queres, contanto que me dês um penhor, até que mandes o que prometes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 18, 'Judá disse: Que queres tu que te dê por penhor? Respondeu: O teu anel, e o cordão e o cajado que tens na mão. Ele deu-lhos, esteve com ela, e a mulher concebeu com esse ajuntamento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 19, 'Depois, levantando-se, retirou-se, e, deposto o traje que havia tomado, vestiu-se com os vestidos de viúva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 20, 'Ora Judá mandou o cabrito pelo seu pastor odolamita, para receber o penhor que tinha dado à mulher; ele, porém, não a tendo encontrado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 21, 'perguntou aos habitantes daquele lugar: onde se encontra aquela mulher que estava sentada na encruzilhada? Responderam-lhe todos: Neste lugar não esteve meretriz alguma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 22, 'Voltou para Judá, e disse-lhe: Não a encontrei; além disso, os homens daquele lugar disseram-me que nunca ali estivera sentada meretriz alguma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 23, 'Judá disse: Guarde ela (o penhor que lhe dei); ao menos não pode acusar-me de mentira: mandei o cabrito que tinha prometido e tu não a encontraste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 24, 'Mas, três meses depois, foram dizer a Judá: Tamar, tua nora, prostituiu-se, e vê-se que está grávida. Judá disse: Tirai-a para fora para ser queimada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 25, 'Enquanto era conduzida ao suplício, mandou dizer a seu sogro: Eu concebi do varão, de quem são estas coisas: vê de quem é o anel, e o cordão, e o cajado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 26, 'Ele, reconhecidas as dádivas disse: Ela é mais justa do que eu, pois que a não entreguei a meu filho Sela. Ele, todavia, não a conheceu mais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 27, 'Mas, quando estava para dar à luz, apareceram dois gêmeos no ventre: e, na saída dos meninos, um deitou de fora a mão, na qual a parteira atou um fio vermelho, dizendo; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 28, 'Este sairá primeiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 29, 'Porém, recolhendo ele a mão, saiu o outro: e a mulher disse: Que brecha tu abriste! Por este motivo pôs-lhe o nome de Farés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 30, 'Depois saiu seu irmão, em cuja mão estava o fio vermelho, e chamou-o Zara. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 1, 'José foi, pois, conduzido ao Egito, e Putifar Egípcio, eunuco de Faraó e general do exército, comprou-o aos Ismaelitas, que o tinham levado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 2, 'O Senhor era com ele, e tudo o que fazia lhe sucedia pròsperamente: habitava em casa do seu senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 3, 'o qual conhecia muito bem que o Senhor era com ele, o qual (Deus) fazia prosperar em suas mãos tudo o que José fazia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 4, 'José achou graça diante do Senhor, a quem prestava serviço: tendo recebido dele a superintendência de todas as coisas, governava a casa que lhe tinha sido confiada, e tudo o que lhe fora entregue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 5, 'O Senhor abençoou a casa do Egípcio, por causa de José, e multiplicou todos os seus bens, tanto em casa como no campo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 6, '(Putifar) não tinha outro cuidado que pôr-se à mesa a comer. José era de rosto formoso e aspecto gentil.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 7, 'Pelo que, passados muitos dias, lançou sua senhora os olhos sobre José e disse: Dorme comigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 8, 'Mas de, não consentindo de modo algum na execrável acção, disse-lhe: Se o meu Senhor, tendo entregue tudo nas minhas mãos, não pede contas do que tem em sua casa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 9, 'e nada há que não esteja em meu poder, ou que me não tenha sido confiada, excepto tu, que és sua mulher, como posso eu cometer esta maldade, e pecar contra o meu Deus?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 10, 'Ainda que, todos os dias, a mulher falasse (no mesmo assunto) ao jovem, ele recusava estar com ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 11, 'Mas aconteceu que, um dia, entrando José em casa, para fazer o seu serviço, sem que ninguém o visse,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 12, 'ela, segurando-o pela orla do seu vestido, disse-lhe: Dorme comigo. Mas ele, deixando a capa na sua mão, fugiu e saiu para fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 13, 'A mulher, vendo a capa na suas mãos, e (vendo) que era desprezada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 14, 'chamou a si a gente da casa e disse: Vede, trouxe-nos este homem hebreu para zombar de nós; veio ter comigo para me seduzir, e, tendo eu gritado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 15, 'ele, ao ouvir a minha voz, deixou a capa, em que eu pegava, e fugiu para fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 16, 'Em prova da sua fidelidade mostrou ao marido, quando ele voltou para casa, a capa com que tinha ficado, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 17, 'e disse: Aquele servo hebreu, que trouxeste, veio ter comigo para abusar de mim: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 18, 'porém, ouvindo-me gritar, deixou a capa, em que eu pegava, e fugiu para fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 19, 'Ao ouvir isto, o senhor, demasiado crédulo nas palavras da mulher, irou-se em extremo '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 20, 'e lançou José no cárcere, onde estavam detidos os presos do rei, e ali ficou ele encarcerado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 21, 'O Senhor, porém, foi com José; compadecido dele, fê-lo encontrar graça diante do governador da prisão, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 22, 'o qual confiou à sua vigilância todos os presos que estavam no cárcere: tudo o que se fazia, era feito por sua ordem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 23, 'Nem sequer (o governador) tomava conhecimento de coisa alguma, depois que lhe confiou tudo, porque o Senhor era com ele e fazia prosperar todas as suas obras.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 1, 'Depois disto, aconteceu que dois eunucos, o copeiro do rei do Egito e o padeiro, pecaram contra o seu senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 2, 'Faraó, irado contra eles (um era chefe dos copeiros, e outro dos padeiros) '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 3, 'mandou-os meter no cárcere do chefe da guarda, no qual estava também preso José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 4, 'O guarda do cárcere entregou-os a José que também os servia. Estiveram um certo tempo, ali, encarcerados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 5, 'Ambos, numa noite, tiveram um sonho, que, por sua interpretação, se referia a eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 6, 'Tendo ido José junto deles, pela manhã, e vendo-os tristes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 7, 'interrogou-os: Por que razão está hoje o vosso semblante mais triste que de costume?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 8, 'Eles responderam: Tivemos um sonho, e não há quem no-lo interprete. José disse-lhes: Porventura não pertence a Deus a interpretação? Contai-me o que vistes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 9, 'O copeiro-mor foi o primeiro que contou o seu sonho: Eu via diante de mim uma cepa, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 10, 'na qual havia três varas, crescer pouco a pouco em gomos, e, depois das flores, amadurecerem as uvas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 11, '(Eu tinha) a taça de Faraó na minha mão; tomei as uvas, espremi-as na taça, que tinha na mão, e apresentei de beber a Faraó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 12, 'José respondeu: A interpretação do sonho é esta: As três varas são três dias ainda (que aqui estarás),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 13, 'depois dos quais se lembrará Faraó dos teus serviços e te restituirá ao antigo cargo: tu lhe apresentarás a taça conforme o teu oficio, como costumavas fazer antes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 14, 'Sòmente lembra-te de mim e usa para comigo de compaixão, quando fores feliz; solicita a Faraó que me tire deste cárcere, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 15, 'porque, por fraude, fui tirado da terra dos Hebreus, e, estando inocente, fui lançado nesta prisão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 16, 'Vendo o padeiro-mor que (José) tinha interpretado sabiamente o sonho, disse: Também eu tive um sonho: (parecia-me) ter três cestos de farinha sobre a minha cabeça, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 17, 'e que, no cesto que estava mais alto, levava todos os manjares, que a arte de padeiro pode preparar, e que as aves comiam dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 18, 'José respondeu: A interpretação do sonho é esta: Os três cestos são três dias ainda (que te restam),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 19, 'depois dos quais Faraó mandará tirar-te a cabeça, te suspenderá em uma forca, e as aves devorarão as tuas carnes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 20, '(Com efeito) três dias depois, era o dia do nascimento de Faraó, o qual, dando um grande banquete aos seus criados, se lembrou à mesa do copeiro-mór e do padeiro-mór.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 21, 'Restituiu um ao seu lugar, para lhe ministrar a taça, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 22, 'e mandou suspender o outro num patíbulo, pelo que foi comprovada a verdade do intérprete.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 23, 'Não obstante sucederem-lhe prôsperamente as coisas, o copeiro-mór esqueceu-se do seu intérprete. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 1, 'Dois anos depois Faraó teve um sonho. Parecia-lhe que estava na margem do rio, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 2, 'do qual saiam sete vacas, muito formosas e gordas, as quais pastavam nos lugares palustres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 3, 'Saiam também outras sete do rio, desfiguradas e consumidas de magreza, as quais pastavam na mesma margem do rio, em lugares cheios de erva: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 4, '(estas) devoravam aquelas que eram belas de aspecto e gordas de corpo. Tendo Faraó despertado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 5, 'adormeceu novamente, e teve outro sonho; sete espigas saiam do mesmo caule, cheias de grãos e formosas; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 6, 'e nasciam também outras tantas espigas delgadas e queimadas do vento, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 7, 'as quais devoravam todas as primeiras que eram tão belas. Despertando Faraó do sono, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 8, 'de manhã, cheio de pavor, mandou chamar todos os adivinhos do Egito e todos os sábios; estando reunidos, contou-lhes o sonho e não havia quem lho esplicasse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 9, 'Então, finalmente, lembrando-se o copeiro-mór (de José) disse: Confesso a minha falta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 10, 'Tendo-se o rei irado contra os seus servos, mandou que eu e o padeiro-mór fôssemos metidos no cárcere do chefe da guarda;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 11, 'ai, uma noite, ambos nós tivemos um sonho que presagiava o futuro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 12, 'Achava-se lá um jovem hebreu, servo do mesmo chefe da guarda. Tendo-lhe nós referidos os sonhos, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 13, 'ouvimos tudo o que depois os factos comprovaram: Eu fui restituído ao meu ofício e o outro foi pendurado em uma forca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 14, 'Imediatamente José foi tirado do cárcere por mandado do rei. Barbeou-se, mudou de roupa e foi ter com Faraó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 15, 'Este disse-lhe; Tive uns sonhos, e não há quem os interprete; ouvi dizer que tu sabes explicar os sonhos que te contam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 16, 'José respondeu: Não sou eu, é Deus quem dará uma resposta favorável a Faraó, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 17, 'Faraó, pois, contou o que tinha visto: Parecia-me estar sobre a margem do rio,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 18, 'e que saíam do rio sete vacas, em extremo formosas, e muito gordas, as quais pastavam a erva verde nos lugares palustres;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 19, 'a seguir, atrás destas, vinham outras sete vacas tão disformes e magras, que nunca as vi semelhantes na terra do Egito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 20, 'as quais devoraram e consumiram as primeiras,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 21, 'Sem que parecessem tê-las engolido, pois ficaram tão macilentas e feias como antes. Acordei, fui novamente oprimido pelo sono,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 22, 'e tive este sonho: sete espigas saíam do mesmo caule cheias (de grãos) e formosas:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 23, 'outras sete, delgadas e queimadas do vento nasciam doutro caule,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 24, 'as quais devoravam as primeiras, que eram tão belas. Referi aos adivinhos o sonho, e não há quem o explique.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 25, 'José respondeu: O sonho do rei reduz-se a um só: Deus mostrou a Faraó o que está para fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 26, 'As sete vacas formosas, e as sete espigas cheias, (de grãos), são sete anos de abundância: no sonho têm a mesma significação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 27, 'As sete vacas magras e macilentas, que subiram (do rio) após as primeiras, e as sete espigas delgadas e queimadas do vento, são sete anos de fome que estão para vir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 28, 'Isto cumprir-se-á por esta ordem:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 29, 'virão sete anos de grande fertilidade por toda a terra do Egito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 30, 'depois dos quais se seguirão outros sete anos de tanta esterilidade que será esquecida toda a abundância passada; com efeito, a fome há-de consumir toda a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 31, 'e a grandeza da penúria há-de absorver a grandeza da abundância.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 32, 'Quanto ao segundo sonho que tivestes, que se refere à mesma coisa, é um sinal certo de que se há-de executar a palavra de Deus, e prontamente se cumprirá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 33, 'Agora, pois, escolha, o rei um homem sábio e ativo, a quem dê autoridade sobre a terra do Egito:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 34, 'este ;(homem) estabeleça superintendentes por todas as províncias: a quinta parte dos frutos nos sete anos de fertilidade, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 35, 'que já estão para começar, seja recolhida nos celeiros: guarde-se todo o trigo debaixo do poder do Faraó, conserve-se nas cidades,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 36, 'e tenha-se preparado para a futura fome dos sete anos, que há-de oprimir o Egito. Assim o país não será consumido pela fome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 37, 'Agradou o conselho a Faraó e a todos os seus ministros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 38, 'Disse-lhes: Poderemos nós encontrar um homem como este, que esteja (tão) cheio de espirito de Deus? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 39, 'Disse, pois, a José; Visto que Deus te manifestou tudo o que disseste, poderei eu encontrar alguém mais inteligente e sábio do que tu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 40, 'Tu governarás a minha casa, e, ao mando da tua voz, obedecerá todo o povo; eu não terei sobre ti outra precedência além do trono.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 41, 'Faraó disse mais a José: Dou-te autoridade sobre toda a terra do Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 42, 'E tirou o anel da sua mão, meteu-o na mão dele, mandou-lhe um hábito branco de linho fino, e pôs-lhe ao pescoço um colar de oiro; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 43, 'fê-lo subir para o seu segundo coche, clamando o pregoeiro que todos ajoelhassem, diante dele, e soubessem que era o superintendente de toda a terra do Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 44, 'Disse também o rei a José: Eu sou Faraó; sem o teu mando ninguém moverá mão ou pé em toda a terra do Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 45, 'Mudou-lhe o nome, e chamou-o, na lingua egípcia, Salvador do Mundo. Deu-lhe por mulher a Aseneth, filha de Putifar, sacerdote de Heliópolis. Saiu, portanto, José a correr a terra do Egito, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 46, '(tinha trinta anos quando se apresentou diante do rei Faraó), e percorreu todas as provindas do Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 47, 'Veio a fertilidade dos sete anos, e, atado o trigo aos molhos, foi recolhido nos celeiros do Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 48, 'Recolheu-se também em cada uma das cidades toda a abundância de frutos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 49, 'Foi tanta a abundância do trigo, que igualava a areia do mar, e a quantidade excedia toda a medida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 50, 'Nasceram a José dois filhos antes de chegar a fome, os quais lhe foram dados à luz por Aseneth, filha de Putifar, sacerdote de Heliópolis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 51, 'Ao primogênito pôs o nome de Manassés, dizendo: Deus me fez esquecer de todos os meus trabalhos, e da casa de meu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 52, 'Ao segundo pôs o nome de Efraim, dizendo: Deus me fez crescer, na terra da minha aflição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 53, 'Passados os sete anos da abundância, que houve no Egito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 54, 'começaram a vir os sete anos de escassez que José prognosticara. Em todo o mundo, se fez sentir a fome: porém em toda a terra do Egito havia pão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 55, 'Quando também o Egito sentiu a fome, o povo clamou a Faraó, pedindo sustento. Ele respondeu-lhes: Ide a José e fazei tudo o que ele vos disser.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 56, 'Ora a fome crescia todos os dias em toda a terra, e José abriu todos os celeiros, e vendia aos Egípcios, porque também a eles oprimia a fome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 57, 'De todas as partes vinham ao Egito, para comprar de comer porque a fome era grande em toda a terra. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 1, 'Jacob, tendo ouvido dizer que no Egito se vendia de comer, disse a seus filhos: Por que estais a olhar uns para os outros? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 2, 'Ouvi dizer que no Egito se vendia trigo: ide e comprai-nos o necessário, para que possamos viver e não sejamos consumidos pela fome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 3, 'Os dez irmãos de José foram, pois, ao Egito para comprar trigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 4, 'Benjamim ficou retido em casa por Jacob, o qual tinha dito aos teus irmãos: É de temer que lhe aconteça alguma desgraça na viagem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 5, 'Eles entraram na terra do Egito com outros que iam comprar (trigo), porque existia a fome na terra de Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 6, 'José era governador na terra do Egito, e, conforme a sua vontade, se vendia o trigo aos povos. Tendo-se prostrado diante dele os seus irmãos, ele os reconheceu, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 7, 'e falava-lhes com aspereza, como a estrangeiros, perguntando-lhes: Donde vindes? Eles responderam: Da terra de Canaan, a fim de comprar o necessário para o sustento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 8, 'Embora ele reconhecesse os irmãos, todavia não foi reconhecido por eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 9, 'Lembrado dos sonhos que em outro tempo tivera, disse-lhes: Vós sois espiões; viestes reconhecer os lugares mais fracos do pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 10, 'Eles responderam: Não é assim, senhor, mas os teus servos vieram para comprar de comer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 11, 'Somos todos filhos de um mesmo homem; viemos com sentimentos pacíficos, nem os teus servos maquinam mal algum.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 12, 'Ele respondeu-lhes: Isso não é assim; vós viestes observar os lugares não fortificados deste país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 13, 'Eles porém disseram: Nós, teus servos, somos doze irmãos, filhos de um mesmo homem na terra de Canaan: o mais pequeno está com nosso pai, o outro já não existe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 14, 'E o que eu disse, tornou (José): sois espiões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 15, 'Desde já vos porei à prova: pela saúde de Faraó não saireis daqui, até que venha vosso irmão mais novo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 16, 'Mandai um de vós que o traga: vós ficareis prisioneiros, até que se prove se é verdadeiro ou falso o que dissestes: aliás, pela saúde de Faraó, sois espiões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 17, 'Meteu-os, pois, em prisão, durante três dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 18, 'Tendo-os mandado tirar do cárcere no terceiro dia, disse: Fazei o que vos disse, e vivereis, por quanto temo a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 19, 'Se sois de paz, um vosso irmão fique ligado no cárcere: vós ide e levai para vossas casas o trigo que comprastes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 20, 'Trazei-me vosso irmão mais novo, para que eu possa verificar ás vossas palavras, e não sejais condenados à morte. Eles fizeram como (José) lhes tinha dito; '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 21, 'disseram uns para os outros: Justamente sofremos estas coisas porque pecamos contra o nosso irmão, vendo a angústia do seu coração, quando nos suplicava e nós o não atendemos; por isso veio sobre nós esta tribulação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 22, 'Ruben, um deles, disse: Porventura não vos disse eu: Não pequeis contra o menino? E vós não me ouvistes. Eis que se requer (de nós) o seu sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 23, 'Ora eles não sabiam que José os entendia, porque lhes falava por intérprete.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 24, '(José) retirou-se, um momento, e chorou; e, voltando; falou com eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 25, 'Tendo mandado tomar e ligar Simeão na presença deles, mandou aos oficiais que enchessem os seus sacos de trigo e repusessem o dinheiro de cada um no seu (respectivo) saco, dando-lhes, além disso, mantimentos para o caminho. E assim se fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 26, 'Eles levando trigo sobre os seus jumentos, partiram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 27, 'Abrindo um deles o saco, para dar de comer ao (seu) jumento na estalagem, vendo o dinheiro, na boca do saco,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 28, 'disse para seus irmãos: Tornaram-me a dar o dinheiro, ei-lo aqui no (meu) saco. E, pasmados e perturbados, disseram uns para os outros: Que é isto que Deus nos fez?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 29, 'Chegaram a casa de Jacob, seu pai, na terra de Canaan, e contaram-lhe tudo o que lhes tinha acontecido, dizendo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 30, 'O Senhor daquela terra falou-nos com dureza e julgou que nós eramos espiões do país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 31, 'Nós respondemos-lhes: Somos homens pacíficos, não maquinamos traição alguma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 32, 'Somos doze irmãos gerados de um mesmo pai; um já não existe, e o mais novo está com nosso pai na terra de Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 33, 'Ele disse-nos: Provarei deste modo se sois homens pacíficos: Deixa, um vosso irmão em meu poder, tomai os mantimentos necessários para as vossas famílias, e parti:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 34, 'trazei-me (depois) o vosso irmão mais novo, para que eu saiba que não sois espiões e possais, recuperar este, que fica em prisão, e tenhais licença de comprar o que quiserdes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 35, 'Dito isto, ao despejar o trigo, cada um deles encontrou na boca do (seu) saco o dinheiro embrulhado; ao verem isto, eles e seu pai ficaram aterrados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 36, 'Jacob disse: Vós levastes-me a ficar sem filhos: José já não existe, Simeão está em cadeias, e haveis de levar-me Benjamin. Sobre mim caíram todos estes males.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 37, 'Ruben respondeu-lhe; Mata os meus dois filhos, se eu to não trouxer outra vez; entrega-to nas minhas mãos e eu to restituirei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 38, 'Ele, porém, disse: Meu filho não irá convosco: seu irmão morreu, e ele ficou só; se lhe acontecer alguma desgraça na terra para onde ides, fareis descer os meus cabelos brancos com (essa) dor à habitação dos mortos. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 1, 'Entretanto a fome oprimia cruelmente toda a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 2, 'Consumidos os viventes que tinham levado do Egito, Jacob disse a seus filhos: Voltai e comprai-nos um pouco de viveres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 3, 'Judá respondeu: Aquele homem intimou-nos com juramento, dizendo; Não vereis a minha face, se não trouxerdes convosco o vosso irmão mais novo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 4, 'Se tu, pois, queres mandá-lo connosco, iremos juntos e te compraremos o necessário:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 5, 'mas, se não queres, não iremos, porque aquele homem, como temos dito muitas vezes, declarou-nos: Não vereis a minha face sem (trazerdes) o vosso irmão mais novo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 6, 'Israel disse-lhes: Para minha desgraça fizestes-lhe saber que tinheis ainda um outro irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 7, 'Eles, porém, responderam: Aquele homem interrogou-nos insistentemente sobre a nossa família; se vivia o pai, se tínhamos outro irmão, — e nós respondemos-lhe segundo o que ele perguntava. Porventura podiamos nós saber que ele iria dizer: Trazei vosso irmão convosco? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 8, 'Judá disse também a seu pai: Manda o menino comigo, para partirmos e podermos viver, e não morrermos nós e os nossos meninos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 9, 'Eu me encarrego dele; requere-o da minha mão: se eu o não trouxer, e to não restituir, serei sempre réu de pecado para contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 10, 'Se não tivesse havido (tanta) demora, já teríamos vindo segunda vez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 11, 'Então Israel, seu pai, disse-lhes: Se assim é necessário, fazei o que quereis: tomai dos melhores frutos do país nos vossos vasos, e levai de presente a esse homem um pouco de bálsamo, de mel, de estoraque, de mirra, e de terebinto, e de amêndoas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 12, 'Levai também convosco dobrado dinheiro, e tornai a levar aquele que encontrastes nos sacos, colocado neles talvez por engano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 13, 'Tomai também o vosso irmão e ide ter com esse homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 14, 'O meu Deus omnipotente vo-lo torne propicio, e remeta convosco o vosso irmão que retém preso e este (meu) Benjamim. Quanto a mim, se me hei-de ver privado de meus filhos, seja! '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 15, 'Eles, pois, tomaram os presentes, o dinheiro dobrado e Benjamim, desceram ao Egito e apresentaram-se a José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 16, 'Este, tendo-os visto, e a Benjamim com eles, deu ordens ao despenseiro de sua casa, dizendo: Manda entrar para dentro de casa (esses) homens, mata alguns animais e prepara um banquete, porque hão-de comer comigo ao meio-dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 17, 'Fez ele o que lhe tinha sido ordenado, e introduziu os homens em casa (de José).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 18, 'Ai, amedrontados, disseram uns para os outros: Por causa daquele dinheiro, que levamos em nossos sacos, somos introduzidos aqui para fazer cair sobre nós esta calúnia e sujeitar violentamente à escravidão nós e os nossos jumentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 19, 'Por isso, ao entrar a porta, aproximaram-se do despenseiro da casa'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 20, 'e disseram: Rogamos-te, senhor, que nos ouças. Já uma vez viemos comprar víveres: '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 21, 'depois de os termos comprado, quando chegamos à estalagem, abrimos os nossos sacos e encontramos na boca dos sacos o dinheiro, o qual tornamos a trazer agora no mesmo peso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 22, '(Além deste) trouxemos outro dinheiro, para comprarmos o que nos é necessário: não sabemos quem pôs aquele nos nossos sacos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 23, 'Ele, porém, respondeu: A paz seja convosco: não temais. O vosso Deus, o Deus de vosso pai, pôs-vos (aqueles) tesouros nos vossos sacos, porque o vosso dinheiro, eu o recebi. E trouxe-lhes Simeão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 24, 'Introduzidos em casa, deu-lhes água para lavarem os pés, e deu de comer aos seus jumentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 25, 'Eles preparavam os presentes, para quando José entrasse ao meio-dia, porque tinham ouvido que ai haviam de comer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 26, 'José entrou em sua casa, e eles ofereceram-lhe os presentes, que tinham nas suas mãos, e saudaram-no, inclinando-se até à terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 27, 'Ele perguntou se estavam bons e, a seguir, interrogou: O vosso velho pai, de quem me falastes, está de saúde? Ainda vive?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 28, 'Eles responderam: Nosso pai, teu servo, está de saúde, ainda vive. E, inclinando-se, o saudaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 29, 'José, levantando os olhos, viu Benjamim, seu irmão, filho de sua mãe, e disse: É este o vosso irmão mais novo, de quem me tinheis falado? E acrescentou: Deus se compadeça de ti, meu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 30, 'Então apressou-se (a retirar), porque o seu íntimo se tinha comovido por causa de seu irmão. Procurando onde chorar, entrou no (seu) quarto e aí chorou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 31, 'Saindo outra vez, depois de lavado o rosto, conteve-se e disse: Trazei de comer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 32, 'E foi posta a mesa à parte para José, à parte para os irmãos, à parte também para os Egípcios, que comiam com ele porque não é licito aos Egípcios, comer com os Hebreus, pois consideram isso abominável.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 33, 'Sentavam-se na sua presença, o primogênito segundo o seu privilégio de primogenitura, e o mais novo segundo a sua idade, olhando-sé espantados uns para os outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 34, 'Ao receberem as rações que lhes mandava, (viram que) a de Benjamim era cinco vezes mais abundante. E beberam e alegraram-se com ele. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 1, 'José ordenou ao despenseiro da sua casa: Enche de trigo os seus sacos, quanto eles podem levar, e põe o dinheiro de cada um na boca do saco.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 2, 'Põe, também, na boca do saco do mais novo a minha taça de prata, e o dinheiro que deu pelo trigo. Assim foi feito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 3, 'Chegada a manhã, foram despedidos com os seus jumentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 4, 'Já haviam saído da cidade e tinham caminhado um pouco, quando José, chamando o despenseiro da casa, disse: Levanta-te, vai atrás daqueles homens, e, quando os tiveres alcançado, diz-lhes: Por que razão tornastes mal por bem? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 5, '(A taça que roubastes) é aquela pela qual bebe o teu senhor, e da qual se serve para as suas adivinhações: vós fizestes uma péssima coisa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 6, '(O despenseiro) fez como lhe foi mandado. Tendo-os alcançado, falou-lhes nos termos ordenados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 7, 'Eles responderam: Por que fala assim o nosso senhor? Longe de nós, teus servos, tão grande crime.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 8, 'Voltamos a trazer da terra de Canaan o dinheiro que tínhamos achado no cimo dos sacos; ora como é que, depois disto, pode ser que tenhamos furtado da casa do teu senhor ouro e prata?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 9, 'Aquele dos teus servos, em cujo poder se encontrar o que procuras, morra, e seremos escravos do nosso senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 10, 'Ele disse-lhes: Faça-se segundo as vossas palavras: aquele em cujo poder se encontrar (o que eu procuro). Será meu escravo, e os outros irão em liberdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 11, 'Portanto, pondo à pressa os sacos em terra, cada um abriu o seu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 12, 'E (o despenseiro), tendo-os examinado, principiando desde o maior até ao mais pequeno, encontrou a taça no saco de Benjamim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 13, 'Então eles, rasgadas as vestes e carregados outra vez os jumentos, voltaram para a cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 14, 'Judá foi o primeiro que entrou com seus irmãos na casa de José, o qual ainda se não tinha retirado de lá, e todos se prostraram por terra diante dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 15, 'José disse-lhes: Por que quiseste proceder assim? Porventura ignorais que em favor não há semelhante a mim na ciência de advinhar? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 16, 'Judá disse-lhe: Que responderemos nós ao meu senhor? ou que coisa diremos, ou que justa desculpa poderemos apresentar? Deus encontrou a iniquidade de teus servos: eis que somos todos escravos do meu senhor, nós e aquele junto do qual foi encontrada a taça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 17, 'José respondeu: Longe de mim proceder desse modo: aquele que roubou a taça, seja meu escravo, e vós ides livres para vosso pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 18, 'Então Judá, aproximando-se (de José), cheio de ânimo disse: Peço-te, meu senhor, que permitas ao teu servo dizer uma palavra aos teus ouvidos, e que não te agastes com o teu servo, porque tu és depois de Faraó, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 19, 'o meu senhor. Primeiramente perguntaste a teus servos: Tendes pai ou irmão? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 20, 'Nós respondemos-te, meu senhor: Temos um pai já velho, e um menino mais pequeno, que (lhe) nasceu na sua velhice, um irmão uterino daquele que morreu; é o único que resta de sua mãe, e o pai ama-o ternamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 21, 'E tu disseste a teus, servos: Trazei-mo, e porei os meus olhos sobre ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 22, 'Nós replicámos ao meu senhor: O menino não pode deixar seu pai, porque se o deixar, (seu pai) morrerá,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 23, 'e tu disseste a teus servos: Se não vier convosco vosso irmão mais novo, não vereis mais a minha face.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 24, 'Tendo nós, pois, ido para nosso pai, teu servo, contámos tudo o que o meu senhor tinha dito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 25, 'E (passado algum tempo) nosso pai disse-nos: Voltai e comprai-nos mais algum trigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 26, 'Nós dissemos-lhe: Não podemos ir: se nosso irmão mais novo for connosco, partiremos juntamente, mas de outra maneira, sem ele, não nos atrevemos a ver a face daquele homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 27, 'Ao que ele respondeu: Vós sabeis que minha mulher me deu à luz dois filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 28, 'Um deles saiu de casa, e vós dissestes: Uma fera o devorou; e até agora não aparece.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 29, 'Se levardes também este, e lhe acontecer alguma desgraça no caminho, fareis descer com tristeza os meus cabelos brancos à habitação dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 30, 'Portanto, se eu entrar em casa de nosso pai, teu servo, e faltar o menino, como a sua vida depende da dele,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 31, 'vendo que ele não está connosco, morrerá; e teus servos farão descer com tristeza os seus cabelos brancos à habitação dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 32, 'Seja eu mesmo teu próprio escravo, eu que, sob minha fé, o recebi, e obriguei minha pessoa, dizendo: Se eu o não tornar a trazer, serei para sempre réu de pecado contra meu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 33, 'Portanto eu ficarei teu escravo, em lugar do menino, ao serviço do meu senhor, e o menino volte com seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 34, 'Não posso tornar para meu pai sem o menino, para que eu não seja testemunha da aflição que o oprimirá. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 1, 'José não se podia conter mais diante dos muitos circunstantes, pelo que ordenou que todos saíssem, e, nenhum estranho assistisse ao reconhecimento mútuo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 2, 'José levantou a voz tão alto chorando, que a ouviram o Egípcios e toda a casa de Faraó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 3, 'Disse a seus irmãos: Eu sou José; vive ainda meu pai? Não podiam responder-lhe seus irmãos, possuídos dum excessivo terror.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 4, 'Ele, porém, com benignidade. disse-lhes: Aproximai-vos de mim. E, tendo-se eles aproximado, disse: Eu sou José, vosso irmão, a quem vós vendestes para o Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 5, 'Não temais, nem vos pareça ser coisa dura o terdes-me vendido para este país, porque para vossa salvação me mandou Deus adiante de vós para o Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 6, 'Portanto há dois anos que principiou a haver fome neste país, e ainda restam cinco anos, nos quais nem se poderá lavrar, nem ceifar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 7, 'Deus enviou-me adiante para que sejais conservados sobre a terra, e possais ter alimento para viver.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 8, 'Não (foi) por vosso conselho que fui mandado para aqui, mas por vontade de Deus, o qual me tornou quase pai de Faraó, senhor de toda a sua casa, e príncipe em toda a terra do Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 9, 'Apressai-vos, ide a meu pai e lhe direis: Isto te manda dizer teu filho José: Deus fez-me senhor de toda a terra do Egito: vem para a minha companhia, não te demores,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 10, 'e habitarás na terra de Gessen; estarás perto de mim, com teus filhos, com filhos de teus filhos, as tuas ovelhas, os teus rebanhos, e tudo o que possuis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 11, 'Aí te sustentarei, porque ainda restam cinco anos de fome, para que não pereças tu, a tua casa e tudo o que possuis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 12, 'Eis que os vossos olhos e os olhos de meu irmão Benjamim vêem que é a minha boca que vos fala.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 13, 'Contai a meu pai toda a minha glória e tudo o que vistes no Egito; apressai-vos e trazei-mo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 14, 'E, tendo-se lançado ao pescoço de seu irmão Benjamim para o abraçar, chorou, chorando também (Benjamim) sobre o seu pescoço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 15, 'José beijou todos os seus irmãos, e chorou sobre cada um deles. Depois disto, afoutaram-se a falar com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 16, 'Ouviu-se e divulgou-se de boca em boca no palácio do rei: Chegaram os irmãos de José. Faraó e todos os seus cortesãos se alegraram com isso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 17, 'Disse Faraó a José que ordenasse a seus irmãos: Carregai os vossos jumentos, ide para a terra de Canaan,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 18, 'tirai de lá vosso pai e família, e vinde para junto de mim; eu vos darei o que há de melhor no Egito, e comereis o melhor dá terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 19, 'Ordena também que tomem carros da terra do Egito para a condução de seus filhos e mulheres, e diz-lhes: Tomai vosso pai, e apressai-vos a vir quanto antes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 20, 'Não tenhais pena de não trazer todas as vossas alfaias, porque todas as riquezas do Egito serão vossas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 21, 'Os filhos de Israel fizeram como lhes fora mandado. José deu lhes carros, segundo a ordem de Faraó, e mantimentos para o caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 22, 'Mandou também dar a cada um duas vestes: a Benjamim, porém, deu trezentas moedas de prata com cinco ótimas vestes, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 23, 'mandando a seu pai outro tanto de dinheiro e de roupa, acrescentando dez jumentos, que levavam de todas as riquezas do Egito, e outras tantas jumentas, que levavam trigo e pão para o caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 24, 'Despediu, pois seus irmãos, e, ao partir, disse-lhes: Não alterqueis durante a viagem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 25, 'Eles, partindo do Egito, chegaram à terra de Canaan, a casa de seu pai Jacob,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 26, 'e deram-lhe a nova, dizendo: José, teu filho, vive, e governa toda a terra do Egito. Ouvindo isto, Jacob não se comoveu, pois não os acreditava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 27, 'Eles, porém, contavam toda a série dos acontecimentos. Quando (Jacob) viu os carros e tudo o que (José) tinha mandado, reviveu o seu espírito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 28, 'e disse: Basta-me que ainda viva meu filho José: irei, e vê-lo-ei antes de morrer. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 1, 'Partiu, pois, Israel com tudo o que possuía foi ao poço do juramento. Tendo imolado aí vítimas ao Deus de seu pai Isaac, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 2, 'ouviu-o numa visão de noite, que o chamava e lhe dizia: Jacob, Jacob! Ao qual ele respondeu: Eis-me aqui.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 3, 'Deus disse-lhe: Eu sou o Deus fortíssimo de teu pai; não temas, vai para o Egito, porque eu te farei ser uma grande nação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 4, 'Eu irei para lá contigo e te reconduzirei de lá quando voltares: e José porá as suas mãos sobre os teus olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 5, 'Jacob partiu do poço do juramento, e seus filhos colocaram-no com seus meninos e suas mulheres sobre os carros que Faraó tinha mandado para o transportar, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 6, 'com tudo o que ele possuía na terra de Canaan, e foi para o Egito com toda a sua família, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 7, 'com seus filhos, netos e filhas, e toda a sua descendência juntamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 8, 'Eis os nomes dos filhos de Israel, que entraram no Egito, quando ele para lá foi com seus filhos. O primogénito (era) Ruben.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 9, 'Os filhos de Ruben (eram) Henoch, Fallu, Hesron e Carmi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 10, 'Os filhos de Simeão (eram) Jamuel, Jarnin, Aod, Jaquin, Soar e Saul, filho duma Cananeia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 11, 'Os filhos de Levi (eram) Gerson Caath e Merari.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 12, 'Os filhos de Judá (eram) Her, Onan, Sela, Farés e Zara: mas Her e Onan morreram na terra de Canaan. A Farés nasceram as filhas Hesron e Hamul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 13, 'Os filhos de Issacar (eram) Tola, Fua, Job e Semron.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 14, 'Os filhos de Zabulon (eram) Sared, Elon e Jaelel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 15, 'Estes são os filhas de Lia, que ela gerou na Mesopotâmia da Síria, com Dina, sua filha. Os seus filhos e filhas (eram), ao todo, trinta e três.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 16, 'Os filhos de Gad (eram) Sefion, Hagi, Suni, Esebon, Heri, Arodi, e Arel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 17, 'Os filhos de Aser (eram) Jame, Jesua Jessui e Béria, e também Sara, irmã deles. Os filhos de Béria (eram) Heber e Melquiel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 18, 'Estes são os filhos de Zélfa, (a criada) que Labão tinha dado a sua filha Lia; ela os deu à luz a Jacob: (ao todo) dezasseis pessoas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 19, 'Os filhos de Raquel, mulher de Jacob, (eram) José e Benjamim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 20, 'A José, na terra do Egito, nasceram os filhos Manassés e Efraim, que lhe deu à luz Aseneth, filha de Putifar, sacerdote de Heliópolis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 21, 'Os filhos de Benjamim (eram) Bela, Becor, Asbel, Gera, Naaman, Equi, Ros, Mofim, Ofim e Ared.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 22, 'Estes são os filhos que Raquel deu à luz a Jacob: ao todo catorze pessoas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 23, 'Filhos de Dan: Husim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 24, 'Os filhos de Neftali (eram) Jasiel, Guni, Jeser e Salem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 25, 'Estes são os filhos de Bala, que Labão tinha dado a sua filha Raquel; ela os deu à luz a Jacob: ao todo sete pessoas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 26, 'Todas as pessoas que entraram com Jacob no Egito, e que descendiam dele, não contando com as mulheres de seus filhos, eram sessenta e seis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 27, 'Os filhos de José, que lhe tinham nascido no Egito, eram dois. Todas as pessoas da casa de Jacob, que entraram no Egito, foram setenta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 28, '(Jacob) enviou Judá adiante de si a José, para o avisar que lhe saísse ao encontro em Gessen.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 29, 'Quando chegou, José tendo mandado aparelhar o seu coche, foi ao encontro de seu pai no mesmo lugar, e, quando o viu, lançou-se ao seu pescoço, e, abraçando-o, chorou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 30, 'O pai disse a José: Agora morrerei contente, porque vi a tua face e tu vives ainda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 31, '(José), porém disse a seus irmãos e a toda a família de seu pai: Irei levar a nova a Faraó e lhe direi: Meus irmãos e toda a família de meu pai, que estavam na terra de Canaan, vieram para mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 32, 'São homens pastores de ovelhas, que se ocupam em apascentar rebanhos: trouxeram consigo o seu gado e os rebanhos, e tudo o que podiam ter.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 33, 'Quando (Faraó) vos chamar e vos disser: Que ocupação é a vossa?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 34, 'Responder-lhes-eis: Nós, teus servos, somos proprietários de gado, desde a nossa infância até ao presente, assim nós, como nossos país. Direis isto, para poderdes habitar na terra de Gessen, porque os Egípcios detestam todos os pastores. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 1, 'José foi, pois, levar a nova a Faraó, dizendo: Meu pai e meus irmãos, com as suas ovelhas, rebanhos e com tudo o que possuem, vieram da terra de Canaan: e eis que estão parados na terra de Gessen.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 2, 'Apresentou também ao rei os cinco últimos de seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 3, '(Faraó) perguntou-lhes: Que ocupação tendes? Eles responderam: Nós, teus servos, somos proprietários de gado, (como o foram) nossos pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 4, 'Viemos habitar como peregrinos na tua terra, porque não há erva para os rebanhos dos teus servos, e a fome vai crescendo; suplicamos-te que ordenes que nós, teus servos, habitemos na terra de Gessen.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 5, 'O rei disse, pois, a José: Teu pai e teus irmãos vieram ter contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 6, 'A terra do Egito está diante de ti: faze-os habitar no melhor lugar: entrega-lhes a terra de Gessen. Se sabes que há entre eles homens de capacidade, constitui-os superintendentes dos meus rebanhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 7, 'Depois disto José conduziu seu pai ao rei, e apresentou-lho. Jacob abençoou o rei,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 8, 'que lhe perguntou: Quantos são os teus anos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 9, 'Respondeu: Os dias da minha peregrinação são cento e trinta anos; poucos e trabalhosos, não chegaram aos dias da peregrinação de meus pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 10, 'Abençoado o rei, retirou-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 11, 'José deu a seu pai e a seus irmãos uma propriedade, em um ótimo lugar do país, em Ramsés, como Faraó tinha ordenado, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 12, 'e sustentava-os a eles e a toda a família de seu paí, dando a cada um o seu sustento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 13, 'Ora o pão faltava em toda aquela terra, a fome muito grande, principalmente no Egito e em Canaan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 14, '(José) recolheu destes países todo o dinheiro pela venda do trigo, e meteu-o no erário do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 15, 'Faltando o dinheiro aos compradores, todo o Egito foi ter com José, dizendo: Dá-nos pão; por que razão morreremos nós na tua presença, por falta de dinheiro? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 16, 'Ele respondeu-lhes: Trazei os vossos gados, e eu vos darei por eles de comer, se não tendes (mais) dinheiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 17, 'Trouxeram-nos a José e ele deu-lhes alimento em troca de cavalos, de ovelhas, de bois e de jumentos, e sustentou-os aquele ano pela troca de gados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 18, 'Voltaram também no ano seguinte e disseram-lhe: Não encobriremos ao nosso senhor, que, faltando o dinheiro, nos faltaram juntamente os gados; nem tu ignoras que não temos mais nada, além dos (nossos) corpos e da (nossa) terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 19, 'Por que morreremos, pois, à tua vista? Nós e a nossa terra seremos teus; compra-nos para sermos escravos do rei, dá-nos sementes, para que não morramos e a terra se não reduza a um deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 20, 'Portanto José comprou toda a terra do Egito, vendendo cada um deles as suas possessões por causa do rigor da fome: assim a sujeitou a Faraó,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 21, 'com todos os seus povos, desde uma extremidade do Egito até à outra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 22, 'Sòmente não comprou a terra dos sacerdotes, porque os sacerdotes tinham uma determinada provisão de Faraó, e comiam a provisão que lhes dava Faraó. Por isso não venderam as suas terras, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 23, '(Depois disto) disse José aos povos: como vedes, Faraó é o Senhor de vós e da vossa terra: tomai sementes e semeai os campos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 24, 'para que possais colher frutos. Dareis ao rei a quinta parte: as outras quatro deixo-os a vós para semente e para sustento das vossas famílias e filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 25, 'Eles responderam: A nossa conservação está nas tuas mãos: que o nosso senhor apenas volva para nós o seu olhar, e alegres serviremos o rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 26, 'Desde aquele tempo até ao dia de hoje, em toda a terra do Egito, se paga aos reis a quinta parte; isto tornou-se lei (para todos) excetuada a terra sacerdotal, que ficou livre desta sujeição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 27, 'Israel habitou, pois, no Egito, na terra do Gessen, e adquiriu, ali, bens, aumentando e multiplicando-se extraordinariamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 28, 'Viveu nela dezassete anos; e todo o tempo da sua vida foi de cento e quarenta e sete anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 29, 'Vendo que se aproximava o dia da sua morte, chamou seu filho José e disse-lhe: Se achei graça diante de ti, põe a tua mão debaixo da minha coxa; usarás comigo de bondade e fidelidade, e não me sepultarás no Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 30, 'Quando for dormir com os meus pais, tu me tirarás desta terra e me sepultarás no túmulo dos meus antepassados. José respondeu-lhe: Farei o que mandaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 31, 'Ele acrescentou: Jura-mo. José fez o juramento e Israel (adorou a Deus) prostrado sobre a cabeceira do leito. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 1, 'Passadas assim estas coisas, foi anunciado a José que seu pai estava doente, e ele, tomando consigo os dois filhos, Manassés e Efraim, foi vê-lo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 2, 'Disseram ao velho: Teu filho José vem visitar-te. Ele, reunidas as suas forças, sentou-se sobre o leito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 3, 'Logo que (José) entrou, disse-lhe: O Deus Omnipotente apareceu-me em Luza, que é a terra de Canaan, abençoou-me '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 4, 'e disse: Eu te aumentarei e multiplicarei, e farei de ti uma multidão de povos: darei esta terra a ti e à tua descendência depois de ti, para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 5, 'Portanto os teus dois filhos, que te nasceram na terra do Egito, antes que eu para aqui viesse ter contigo, serão meus: Efraim e Manassés serão considerados meus (filhos), como Ruben e Simeão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 6, 'Mas os outro, que tiveres depois destes, serão teus, e serão chamados com o nome de seus irmãos nas suas possessões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 7, 'Quando eu voltava da Mesopotâmia, morreu-me Raquel na terra de Canaan, mesmo durante a viagem, na Primavera; eu estava para entrar em Efrata, e enterrei-a junto do caminho de Efrata, que, por outro nome, se chama Belém, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 8, 'Vendo Israel os filhos (de José), disse-lhe: Quem são estes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 9, '(José) respondeu: São os meus filhos, que Deus me deu aqui. Faze-os aproximar de mim, disse (Jacob), para que eu os abençoe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 10, 'Com efeito. Os olhos de Israel se tinham escurecido por causa da grande velhice, e não podia ver claramente. José aproximou-os, e ele, beijando-os, e abraçando-os'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 11, 'disse a seu filho: Não fui privado de te ver, e, além disso, Deus mostrou-me a tua geração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 12, 'José, tendo-os tirado de entre os joelhos do pai, inclinou-se profundamente por terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 13, 'Em seguida pôs Efraim à sua direita, isto é, à esquerda de Israel, e Manassés à sua esquerda, isto é, à direita de seu pai, e fez que ambos se aproximassem dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 14, 'Israel, estendendo a mão direita, pô-la sobre a cabeça de Efraim, irmão mais novo, e a esquerda sobre a cabeça de Manassés, o mais velho, cruzando, assim as mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 15, 'Jacob abençoou José (nos seus filhos), dizendo: O Deus, em cuja presença andaram meus pais Abraão e Isaac, o Deus que me sustentou desde a minha mocidade até este dia, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 16, 'o Anjo, que me livrou de todos os males, abençoe estes meninos; que eles sejam chamados com o meu nome, e também com os nomes de meus pais Abraão e Isaac, e se multipliquem em abundância sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 17, 'José, vendo que o pai tinha posto a mão direita sobre a cabeça de Efraim, teve com isto grande pena, e, pegando na mão de seu pai, procurava afastá-la da cabeça de Efraim, e levá-la sobre a cabeça de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 18, 'Disse ao pai; Não está assim bem, pai: visto que este é o primogênito, põe a tua direita sobre sua cabeça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 19, 'Ele, porém, recusando, disse: Eu o sei, meu filho, eu o sei: este também será chefe de povos, e se multiplicará, mas seu irmão mais novo será maior do que ele, e a sua descendência se tornará uma multidão de nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 20, 'Então os abençoou, dizendo: Por ti será bendito Israel, quando se disser: Deus te faça como Efraim e como Manassés. E pôs Efraim adiante de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 21, 'Disse a seu filho José: Vou morrer, mas Deus será convosco e vos reconduzirá à terra de vossos pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 22, 'Eu te dou, de mais que a teus irmãos, aquela parte que ganhei da mão dos Amorreus, com a espada e com o meu arco. ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 1, 'Jacob chamou seus filhos, e disse-lhes: Juntai-vos, para que vos anuncie o que vos acontecerá nos dias futuros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 2, 'Juntai-vos e ouvi, filhos de Jacob, ouvi Israel, vosso pai:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 3, 'Ruben, meu primogênito, tu, a minha fortaleza e o primeiro fruto do meu vigor, o primeiro na dignidade, o maior no império, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 4, 'derramaste-te como a água. Não terás a preeminência, porque subiste ao leito do teu pai, e profanaste o seu tálamo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 5, 'Simeão e Levi (são) irmãos. (As suas espadas são) instrumentos mortíferos de iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 6, 'Que a minha alma não tenha parte nos seus conselhos, e que a minha alma não se una aos seus conluios, porque, no seu furor, mataram homens, e na sua vontade (criminosa) cortaram os jarretes dos touros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 7, 'Maldita a sua cólera porque (foi) violenta, e o seu furor, porque (foi) cruel. Eu os dividirei em Jacob, e os espalharei em Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 8, 'Judá, teus irmãos te louvarão: a tua mão estará sobre as cervizes de teus inimigos: os filhos de teu pai se prostrarão diante de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 9, 'Judá é um cachorro de leão. Correste, meu filho, para a presa, deitaste-te para descansar como o leão, e como a leoa, quem o despertará? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 10, 'O cetro não será tirado de Judá, nem o bastão soberano de entre os seus pés, até que venha aquele de quem é o mando, e a quem os povos devem obediência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 11, 'Ele atará à vinha o seu jumentinho, e à videira, ó meu filho, a suá jumenta, Lavará a sua túnica no vinho, e a sua capa no sangue da uva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 12, 'Os seus olhos são mais escuros que o vinho, e os seus dentes mais brancos do que o leite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 13, 'Zabulon habitará na praia do mar, e no ancoradouro dos navios, estendendo-se até Sidónia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 14, 'Issacar é (como) jumento robusto que está deitado dentro do seu estábulo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 15, 'Viu que o repouso era bom, e que a (sua) terra era ótima; curvou os seus ombros para levar pesos, e sujeitou-se aos tributos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 16, 'Dan julgará o seu povo, como qualquer outra tribo de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 17, 'Dan é como uma serpente no caminho, uma víbora no atalho, que morde as unhas do cavalo, para que o cavaleiro caia para trás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 18, 'A tua salvação esperarei, ó Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 19, 'Gad: salteadores o assaltam, e ele fere-os nos calcanhares.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 20, 'Aser: Suculento é o seu pão, e ministrará delicias aos reis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 21, 'Neftali é uma corsa veloz, pronuncia palavras graciosas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 22, 'José é o rebento duma árvore fértil, o rebento duma árvore fértil junto duma fonte, cujos ramos passam por cima do muro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 23, 'Os arqueiros provocam-no, lançam-lhe flechas, os arqueiros o atacam,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 24, 'O seu arco apoiou-se no forte; os seus braços e as mãos permanecem ágeis, pela mão do Poderoso de Jacob, por aquele que é o Pastor e a Rocha de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 25, 'O Deus de teu pai será o teu auxilio, e o Omnipotente te abençoará com as bênçãos do alto céu, com as bênçãos do abismo, que jaz em baixo, com as bênçãos dos seios maternos e dos úteros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 26, 'As bênçãos de teu pai, que excedem as que ele recebeu de seus pais, e as delícias das colinas eternas. Derramem-se sobre a cabeça de José, sobre a cabeça daquele que é Príncipe dos seus irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 27, 'Benjamim, lobo arrebatador. Pela manhã devorará a presa, e, à tarde, repartirá os despojos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 28, 'Todos estes são os chefes das doze tribos de Israel. Foi assim que lhes falou seu pai, foi assim que abençoou cada um deles, com bênçãos próprias, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 29, 'Depois ordenou-lhes: Vou unir-me ao meu povo; sepultai-me com meus pais na caverna que está no campo de Efrom, o Heteu, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 30, 'em frente de Mambré na terra de Canaan, e que Abraão comprou a Efrom, o Heteu, com o campo (onde ela está) para ter um sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 31, 'Ali sepultaram Abraão e Sara, sua mulher: ali foi sepultado Isaac com sua mulher Rebeca; ali jaz também sepultada Lia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 32, 'Tendo (Jacob) acabado de dar estas ordens a seus filhos, recolheu os seus pés para o leito, e morreu, e foi reunido ao seu povo (no Limbo). ');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 1, 'José, vendo isto, lançou-se sobre o rosto do pai, chorando e beijando-o.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 2, 'Ordenou aos médicos que o serviam, que embalsamassem o seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 3, 'Enquanto eles cumpriam a ordem, passaram-se quarenta dias, porque este é o tempo gasto para embalsamar (um cadáver). O Egito chorou-o durante setenta dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 4, 'Terminado o tempo do luto, disse José à família de Faraó; Se eu achei graça diante de vós, fazei chegar aos ouvidos de Faraó '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 5, 'que meu pai me obrigou a jurar, quando disse: Vou morrer, sepultas-me-ás no meu sepulcro, que mandei abrir para mim na terra de Canaan. Irei, pois, sepultar meu pai, e depois voltarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 6, 'Faraó respondeu: Vai e sepulta teu pai, como prometeste com juramento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 7, 'Partindo ele, acompanharam-no todos os anciães da casa de Faraó, e todos os principais da terra do Egito, '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 8, 'a casa de José com seus irmãos, e a casa de seu pai, à excepção dos pequeninos, dos rebanhos, e dos armamentos, os quais deixaram na terra de Gessen.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 9, 'Teve também (José) o acompanhamento de carros e cavaleiros, de forma que o cortejo era enorme.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 10, 'Chegaram à eira de Atad, que está situada além do Jordão, onde gastaram sete dias a celebrar as exéquias com um pranto grande e profundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 11, 'Tendo observado isto os habitantes da terra de Canaan, disseram: Grande pranto é este dos egípcios. Por isto, se ficou chamando aquele lugar o Pranto do Egito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 12, 'Fizeram, pois, os filhos de Jacob como ele lhes tinha mandado:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 13, 'levando-o à terra de Canaan, o sepultaram na caverna, em frente de Mambré, que Abraão tinha comprado a Efron, o Heteu, com o campo (em que ela está), para ter um sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 14, 'José, sepultado seu pai, voltou para o Egito com seus irmãos e toda a comitiva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 15, 'Depois da morte de Jacob, os irmãos (de José) ficaram temerosos, dizendo entre si: Quem sabe se José nos ganhará ódio lembrado da injúria que padeceu, e nos fará pagar todo o mal que lhe fizemos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 16, 'Mandaram-lhe, pois, dizer: Teu pai antes de morrer ordenou-nos '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 17, 'que em seu nome te disséssemos: Peço-te que esqueças o crime de teus irmãos, o pecado e a maldade que usaram contra ti; nós te suplicamos também que perdoes esta iniquidade aos servos do Deus de teu pai. Ouvindo isto, José chorou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 18, 'Seus irmãos foram ter com ele, e, prostrados por terra, disseram: Nós somos teus servos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 19, 'Ele respondeu-lhes: Não temais: porventura podemos nós resistir à vontade de Deus? '),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 20, 'Vós tivestes intenção de me fazer mal, mas Deus o converteu em bem, para me exaltar, como presentemente vedes, e para salvar muitos povos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 21, 'Não temais: eu vos sustentarei a vós e a vossos filhinhos. Assim os consolou, falando-lhes com doçura e mansidão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 22, '(José) habitou no Egito, com toda a família de seu pai. Viveu cento e dez anos, e viu os filhos de Efraim até à terceira geração. Os filhos de Maquir, filho de Manassés, nasceram também sobre os joelhos de José.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 23, 'Passado isto, disse a seus irmãos: Deus vos visitará, depois da minha morte, e vos fará sair desta terra para a terra prometida com juramento a Abraão, a Isaac e a Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 24, 'José obrigou os filhos de Israel a jurar, dizendo: Deus vos visitará, levai os meus ossos convosco deste lugar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 25, 'Morreu, tendo completado os cento e dez anos da sua vida, e foi embalsamado e depositado num caixão no Egito. ');
